// مولّدة آلياً بواسطة scripts/split-fatwas.mjs — لا تُعدَّل يدوياً.
export default [{"id":7,"question":"سائلٌ يقول: سماحة الشيخ، ذُكر في فتوى لكم عن الحكم بالحقوق العربية والمعاديل أنَّها لا تجوز، ولكن ما الحل لمثل هذه القضايا، والتي اعتادتها القبائل، ويعتبرونها صلحًا، خاصَّةً وأنها تردع عن التَّعدي على الغير؟نريد من فضيلتكم -أطال الله عمركم- توضيح هذه المسألة؟ وحبَّذا لو كان هناك اجتماعٌ لمشايخ القبائل لتوضيح مثل هذه العملية، والسلام عليكم.","title":"ما حكم العمل بأعراف القبائل وعاداتها؟","answer":"الجواب: هذا سؤال فيه إجمالٌ، والذي صدر فيه منَّا الفتوى والرسائل التي كتبناها للقبائل -تُقرأ على رؤوس القبائل- هي حثّهم على الالتزام بحكم الله، والحذر من القوانين والعادات والسَّوالف التي مشوا عليها وتُخالف الشرع، فما كان يُوافق الشرعَ من الصُّلح فلا بأس به، وما كان يُخالف الشرع فهو الذي فيه التَّوجيه والتَّحذير، حتى لا يفعلوا ما يُخالف شرع الله المُطهر.\nفهذه القوانين التي يعتادها الآباء والأسلاف والعادات التي يعتمد عليها بعضُ الناس يُنْظَر فيها، وتُعرض على الكتاب والسنة، فما وافق الكتابَ والسنةَ قُبِلَ منها، وما لم يُوافق ذلك يرد على أهله، ويُنصحون عنه، فإذا كان ما بينهم من عادةٍ لا تُخالف الشرع؛ كأن يتوجهوا إلى المُعتدى عليه ويطلبوا منه المُوافقة على السماح والصُّلح بينه وبين أخيه بمالٍ يُبذل من أخيه، أو من القبيلة؛ حتى لا تقع بينهم فتنةٌ؛ لأنه تعدَّى عليه –ضربه، أو قتل ولده، أو قتل أخاه، أو ما أشبه ذلك- إذا توجَّهوا إليه بالصلح، وأن يُقدِّموا إليه ما يُرضيه من مالٍ، أو يجمعون له من القبيلة ما يُرضيه من المال، أو يصنعون طعامًا ويدعون القبيلة وهو معهم ليسترضوه ويستسمحوه؛ فهذه أمور ليس فيها شيءٌ، إنما الذي يُخشى منه هو ما يُخالف الشرع المُطهر.\nفإذا كانت العادةُ أو الصلحُ على وجهٍ لا يرضاه الشرعُ ولا يُقرّه الشرعُ ،فهذا هو الذي يُمنع من عادات القبائل وسوالف المشايخ القديمة.","link":"https://binbaz.org.sa/fatwas/2752/ما-حكم-العمل-باعراف-القباىل-وعاداتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0257.mp3","categories":["أصول الفقه"]},{"id":26,"question":"ما الفرق بين التعاليم الإسلامية والتقاليد الإسلامية؟ وهل نُطلق على الحجاب الشَّرعي تقليدًا إسلاميًّا أو تعليمًا إسلاميًّا؟ أفتونا مأجورين.","title":"ما الفرق بين التعاليم والتقاليد الإسلامية؟","answer":"الجواب: الأوْلى في مثل هذا أن يُقال: تعليم إسلامي، وتعاليم إسلامية، أحكام شرعية، أحكام إسلامية. أما التقاليد ما لها وجه، التقاليد للعوائد والأعراف، ولا ينبغي استعمالها، وربما أوهم بذلك أنها أشياء ما لها أساس، إنما هي تقليد وأعراف، هذا غلط. بل يقال في الأحكام الشرعية: أحكام إسلامية، تعاليم شرعية، وما أشبه من العبارات التي تنسب العمل إلى الشرع المُطهر إذا كان من الشرع المطهر. أما إذا كان أعرافًا: في البناء، في الفُرُش، في أكل الطعام، هذه أعراف، فإنَّ الناس تختلف، أما ما يتعلق بأحكام الشرع فيُقال: تعاليم إسلامية، أو أحكام إسلامية، أو تعاليم شرعية، أو أحكام شرعية، أو ما أشبهها من العبارات.","link":"https://binbaz.org.sa/fatwas/2806/ما-الفرق-بين-التعاليم-والتقاليد-الاسلامية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0279.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":40,"question":"سؤاله الثالث يقول: فيه سماحة الشيخ دلني على كتاب أو كتابين جيدَين؛ لأتفقه بهما في أمر ديني!","title":"ما الكتب التي يوصى بها للتفُّقه في الدين؟","answer":"الجواب: أدلك على كتب مناسبة، منها:\n- \"بلوغ المرام\" للحافظ ابن حجر، وهو كتاب جيد في الحديث.\n- و\"الأربعون النووية\"، وتتمتها لـ ابن رجب خمسين حديثًا.\nوهذان الكتابان في الحديث كتابان عظيمان.\nوفي الفقه أدلك على:\n- \"آداب المشي إلى الصلاة\"، للشيخ محمد بن عبد الوهاب رحمه الله، فإنه كتاب جيد في الصلاة، وفي الزكاة، وفي الصيام، جمع فيه كلمات طيبة وعبارات مفيدة.\nوهكذا أرشدك إلى \"زاد المعاد\"، لـ ابن القيم، فإنه كتاب جيد مفيد، سماه مؤلفه: \"زاد المعاد في هدي خير العباد\"، وهو كتاب جيد ومفيد.\nوهذان كتابان جيدان، مفيدان.\nومن الكتب الطيبة النافعة:\n\"الوابل الصيب في الكلم الطيب\" لـ ابن القيم رحمه الله، فإنه ذكر فيه فوائد جمة في أوله، وأبوابًا مفيدة في الأذكار.","link":"https://binbaz.org.sa/fatwas/2820/ما-الكتب-التي-يوصى-بها-للتفقه-في-الدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0013.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":53,"question":"وصلنا من الأخوات سؤال يقول: يا فضيلة الشيخ إذا أرادت المرأة العمل في مجال الدعوة في المجتمع فما هي الكتب التي تنصحون بقراءتها ومناقشتها بين النساء سواء للمتعلمات أو الجاهلات بشكل مبسّط؟","title":"ما أهم الكتب في الدعوة إلى الله؟","answer":"الجواب: أهم شيء القرآن الكريم، تعليم القرآن وما تيسّر منه؛ لأنه كتاب الله فيه الهدى والنور: إِنَّ هَذَا الْقُرْآنَ يَهْدِي لِلَّتِي هِيَ أَقْوَمُ [الإسراء:9]، قُلْ هُوَ لِلَّذِينَ آمَنُوا هُدًى وَشِفَاءٌ [فصلت:44] فنصيحتي لأخواتي الدعاة إلى الله من النساء أن يعنين بالقرآن الكريم تفقهًا وتفيقهًا وتعليمًا للنساء، وما يتعلق بالسور القصيرة، وأهم ذلك الفاتحة، تعليم الفاتحة ومعانيها؛ لأنها أم القرآن، وفيها: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5]، وفيها: اهْدِنَا الصِّرَاطَ الْمُسْتَقِيمَ [الفاتحة:6] هذا من أهم ما يُبَيَّن، معنى الصراط المستقيم ما هو، معنى: إِيَّاكَ نَعْبُدُ وَإِيَّاكَ نَسْتَعِينُ [الفاتحة:5] معنى صِرَاطَ الَّذِينَ أَنْعَمْتَ عَلَيْهِمْ [الفاتحة:7] وهكذا ما في كتاب الله من الأحكام والبيان؛ كُلٌّ على حَسَبه، لطالبات العلم شيء، وللعامة من النساء شيء آخر. ثم تعليم العقيدة: ما معنى لا إله إلا الله، ما معنى شهادة أن محمدًا رسول الله؛ حتى يعرفن الله على بصيرة وحتى يعلمن معنى لا إله إلا الله وأنه لا معبود حَقٌّ إلا الله؛ فيخلصن العبادة لله وحده من صلاة وصوم وصدقة، وغير ذلك كله لله وحده، ثم تعليم الصلاة كيف تصلي، والطهارة كيف تطهر من الجنابة من الحيض من النفاس، كيف الطهارة الصغرى من الأحداث التي توجب الطهارة، كيف تصوم، كيف تزكي مالها وحُلِيَّها، كيف تحج إذا جاء الحج، كيف تطيع والديها، كيف تطيع زوجها وما حق زوجها عليها، إلى غير هذا، ومن الكتب التي تناسب قراءتها ما ألف في أمر النساء وشأن النساء وما في كتاب الله من شأنهن وما جاءت به السنة بشأنهن، في \"بلوغ المرام\" مثلًا كتاب صغير مختصر مفيد، عمدة الحديث في أحاديث الرسول ﷺ، عمدة الفقه للموفق ابن قدامة، \"ثلاثة الأصول\" للشيخ محمد بن عبد الوهاب، \"كتاب التوحيد\"، \"العقيدة الواسطية\"، وما أشبه هذه من الكتب الصغيرة التي تنفعهن وتفيدهن، أو ملخص منها؛ حتى يستفيد منهن العامة والطالبات الصغيرات اللآتي يحتجن إلى ذلك ولم يتعلمن في المدارس.\nأما من يتعلم في المدارس الطيبة فسوف يستفيد من المنهج الذي عنده والمقررات التي عنده، ولكن لا مانع من الزيادة؛ أن تكون الداعية تزيد الطالبة علمًا وتفقيهًا وتوجيهًا، وتعلّم العامية ما يلزمها مما لا يسعها جهله في إخلاص العبادة لله بالصلاة بالطهارة في الزكاة في الصيام كما تقدم، في حق الزوج في حق الوالدين في حق الأقارب في حق الجيران وما أشبه ذلك، ومن أحسن الكتب أيضًا وإن كان مطولا بعض الطول \"زاد المعاد في هدي خير العباد\" لابن القيم فإنه كتاب مفيد ونافع، وهكذا \"فتح المجيد شرح  كتاب التوحيد\" كتاب مفيد أيضًا في العقيدة، وهكذا \"آداب المشي إلى الصلاة\" مختصر مفيد في الصلاة وفي الزكاة وفي الصيام للشيخ الإمام محمد بن عبد الوهاب رحمة الله عليه، هذه كتب مختصرة مفيدة.","link":"https://binbaz.org.sa/fatwas/2964/ما-اهم-الكتب-في-الدعوة-الى-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0027.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":63,"question":"سماحة الشيخ أفيدونا أثابكم الله، من المعلوم أن ديننا وسط، ولكن الإفراط في بعض المسائل، فهل معنى هذا التوسع في الفُتْيا أو التمسك بسد الذرائع والتوسع في الفتيا، والاقتصار على النصوص؟","title":"ما النصيحة لمن يتوسع في الفُتْيا؟","answer":"الجواب: هذا مقام عظيم مقام، مقام....... فالواجب عدم التوسع في الفتيا، الواجب على المؤمن أن يخاف الله ويراقبه، وألا يفتي إلا عن بصيرة وعن نص عَرَفَه، وإذا لم يكن هناك نص فلا بدّ من اجتهاد عند الضرورة وتحرٍّ للحق إذا كان من أهله إذا كان عنده علم بالنصوص من الكتاب والسنة والقواعد الشرعية، فلا بدّ يتحرى الحق عند الضرورة، ويجتهد في الإفتاء عند الضرورة. كان الصحابة  يتدافعون الفتوى بينهم؛ حرصًا منهم على السلامة وحذرًا من خطر الفتوى فينبغي للمؤمن ألا يكون حريصًا على الفتوى، لا سريعًا في الفتوى، وإذا رأى من هو أفضل منه أحال إليه؛ لأنه أقرب إلى الصواب منه، كما فعل الصحابة رضي الله عنهم وأرضاهم؛ فينبغي للمفتي ألا يتوسع في الفتوى، وأن يحرص على تحري الحق بالدليل، وأن يفتي على مقتضى الدليل حسب الطاقة والإمكان، إرشادًا للأمة وتوضيحًا للحق، وإذا كان في المقام إشكال؛ توقف ولم يُفْت حتى يحقق الأمر وحتى يتضح له وجه الصواب وإن كان من أعلم الناس؛ فالصحابة أعلم الناس بعد الأنبياء وكانوا يتوقفون في مسائل كثيرة ويحيل بعضهم على بعض؛ حذرًا من خطر الفتوى، وهكذا الأئمة بعدهم،  ورحمهم.","link":"https://binbaz.org.sa/fatwas/2979/ما-النصيحة-لمن-يتوسع-في-الفتيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0038.mp3","categories":["العالم والمتعلم","أصول الفقه"]},{"id":254,"question":"أنا شابٌّ غير سعوديٍّ، ولقد أنهيتُ دراستي الثانوية، وأريد الرجوع إلى بلدي والالتحاق بمجال عسكري، لكن من شروط هذا المجال حلق اللحية، فهل عليَّ طاعتهم من باب قوله تعالى: وأَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ [النساء:59]، أم ماذا أعمل؟ علمًا بأني أُحبُّ هذا المجال حبًّا شديدًا.","title":"حكم الجندي الذي يُؤمر بحلق اللحية","answer":"الجواب: الآية أَطِيعُوا اللَّهَ ما فيها واو، يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُولِي الْأَمْرِ مِنْكُمْ.\nأيها السائل، إذا كانت العسكريةُ لا تحصل إلا بمعصية الله فلا تدخل فيها، ودعهم، أما إذا تيسر لك الدخول فيها لتُعين على الخير، وتأمر بالمعروف، وتنهى عن المنكر، وتُعلم الجاهل، وتُرشد الضَّال؛ فأنت مشكورٌ ومأجورٌ، لكن إذا لم يحصل هذا إلا بحلق اللّحية، أو بترك الصلاة، أو بغير هذا من معاصي الله فلا، لا طاعةَ لمخلوقٍ في معصية الخالق، إنما الطاعة في المعروف، فليس عليك أن تُطيعهم في ذلك، وليس لك أن تدخل في ذلك إذا أجبروك عليه، بل ابتعد عن هذا، وسيجعل الله لك فرجًا ومخرجًا.\nس: وإذا كان التَّجنيد إجباريًّا؟\nإذا كان التَّجنيد إجباريًّا وأجبروك فأنت معذورٌ، لكن لا تحلقها أنت، إذا حلقوها هم بأيديهم فأنت معذورٌ مُكْرَهٌ، وأما أن تُطيعهم في حلقها فلا تُطعهم.","link":"https://binbaz.org.sa/fatwas/4246/حكم-الجندي-الذي-يومر-بحلق-اللحية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0297.mp3","categories":["أصول الفقه"]},{"id":267,"question":"سماحة الشيخ، إني أحبُّكم في الله، سؤالي هو: المسائل الفقهية المُختلف فيها كثيرة جدًّا:أولًا: هل بالإمكان اجتماع العلماء بالعالم الإسلامي ليتَّفقوا على رأيٍ واحدٍ في أهم المسائل؟ثانيًا: إذا لم يكن ذلك ممكنًا، فمَن نتبع من أقوال الفقهاء؟ مع العلم بأنَّها كلها تستند إلى أدلةٍ، وفقكم الله لما فيه الخير والسَّداد.","title":"كيف يكون التعامل مع المسائل الخلافية؟","answer":"أما جمع العلماء في أقطار الدنيا على قولٍ واحدٍ في مسائل الخلاف التي اختلف فيها العلماءُ الأولون فهذا ليس بممكنٍ، وهو من المُستحيلات؛ لأنَّ كل واحدٍ له رأيه، وله اجتهاده، وله ما يفضله من اتّباع بعض الأئمة، ويقدم بعضهم على بعضٍ، هذا ليس بممكنٍ، فلما لم يجتمع الأولون وهم أكثر الناس إيمانًا، وأكثرهم ورعًا، وأكثرهم تقوى؛ فكيف بحال المُتأخرين؟!\nوما ذاك إلا لأنَّ الاجتهاد يختلف، والأدلة تتنوع، وهذا يخفى عليه دليلٌ، وهذا يظهر له دليلٌ، وهناك مسائل اختلفوا فيها من أجل هذا، في مسائل الفروع: في الفراق، والطلاق، والربا، وفي الجنايات، وفي أشياء أخرى.\nأما مَن تتبع عند الاختلاف؟\nفالعامي يسأل أهلَ العلم في بلده، أو في غير بلده، يتحرى مَن يظنّه أتقى لله، وأعلم بدين الله، فيسأله ويقترن بما يقول له.\nأما العلماء فعليهم أن يدرسوا المسائل المُختلف فيها، وينظروا في الأدلة من الكتاب والسنة، ويأخذوا بأرجحها، فالعالم يستطيع أن يدرس الأدلة، ويتأمَّل، ثم يأخذ بالأرجح، بالدليل، لا بقول فلانٍ وفلانٍ، ولكن ينظر الأدلة، ويأخذ بأرجحها وأقواها في هذه المسألة المعينة، وهذا هو الواجب عليه؛ لأنَّ الله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، ويقول سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10]، هذه القاعدة، ما اختلف فيه الناسُ مردّه إلى الكتاب والسنة، يعني: يُرد إلى حكم الله.\nفالعالم يجتهد ويتحرَّى الحقّ، وينظر في الأدلة، ثم يختار ما هو الأقرب إلى الدليل، وما هو الأرجح في اجتهاده، وما هو الأبعد عن الخطأ.\nوأما عامَّة الناس: فيسألون أهلَ العلم عمَّا أشكل عليهم، وفتواهم تكفيهم، لكن عليه أن يتحرَّى من أهل العلم مَن هو أقرب إلى الخير ممن يظنّه أكثر علمًا، وأكثر تقوى، وأكثر احتياطًا.","link":"https://binbaz.org.sa/fatwas/4263/كيف-يكون-التعامل-مع-المساىل-الخلافية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0312.mp3","categories":["أصول الفقه"]},{"id":271,"question":"السلام عليكم ورحمة الله وبركاته، وبعد: فقد أُدخلتُ المستشفى، ومكثتُ حوالي ثلاثة شهور وأنا لم أصلِّ الصلوات المفروضة؛ وذلك لأني كنتُ في غيبوبةٍ تامَّةٍ، ما حكم ذلك؟ والسلام عليكم ورحمة الله.","title":"حكم الصلاة لمن مكث في غيبوبة طويلة","answer":"الجواب: مَن كان مثلك فهو مرفوعٌ عنه القلم؛ لأنَّ التكليفَ مناطه العقل، فإذا صار الإنسانُ في غيبوبةٍ فقد زال عقلُه، ليس عليك صلاة، ولا صيام لو صادفت رمضان وأنت في هذه الحال؛ لأنَّك معذورٌ، من جنس المعتوه والمجنون، ليس عليهم شيءٌ. فإذا أفاق ابتدأ العمل، فأنت بعدما أفقتَ تبتدئ العمل، وأما مدّة الغيبوبة فليس عليك فيها شيء؛ لأنك لا عقلَ لك تُميز به بين أمر الله ونهيه.","link":"https://binbaz.org.sa/fatwas/4267/حكم-الصلاة-لمن-مكث-في-غيبوبة-طويلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0316.mp3","categories":["أصول الفقه"]},{"id":673,"question":"إذا ورد في الحديث \"رُخِّص\" هل يُفهم منه أن غيرهم يحرم عليهم البقاء أو الذهاب؟","title":"معنى \"رخص لقوم دون قوم\" في الحديث","answer":"الجواب: هذه قاعدة؛ قاعدة \"رخص لقوم دون قوم\": الرخصة تخص مَن رُخص لهم، مثل الترخيص للضعفة.\n(دروس شرح بلوغ المرام، كتاب الحج والعمرة)","link":"https://binbaz.org.sa/fatwas/6711/معنى-رخص-لقوم-دون-قوم-في-الحديث","audio":"https://files.zadapps.info/binbaz.org.sa/maram241 - 01 -  Start.mp3","categories":["أصول الفقه"]},{"id":870,"question":"هل كل عملٍ للرسول ﷺ مُلزِمٌ للمسلمين أن يأخذوا به؟","title":"هل كل ما عمله النبي ﷺ مُلزِمٌ للمسلمين؟","answer":"الجواب: لا، الأعمال لا تلزم، أفعاله ﷺ تدل على السُّنية، إلا ما جاء به الأمر، أو كان تفسيرًا لواجب ما جاء به الأمر، فالأمر أصله للوجوب، أو كان تفسيرًا لواجبٍ: كتفسير إقام الصلاة، تفسير إيتاء الزكاة، فهو واجبٌ؛ لأنه تفسيرٌ لما أوجب الله. أما غير ذلك مثل الأكل بثلاثة أصابع، مثل جلسته مُتوركًا في التشهد الأخير، مُفترشًا في التشهد الأول، كل هذه مُستحبَّة، ليس فيها أمرٌ يدل على الوجوب، بل هي من باب المستحبَّات.","link":"https://binbaz.org.sa/fatwas/20900/هل-كل-ما-عمله-النبي-ﷺ-ملزم-للمسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0695هل كل عمل للرسول صلى الله عليه وسلم ملزم للمسلمين أن يأخذوا به؟ابن باز فتاوى المحاضرات.mp3","categories":["أصول الفقه"]},{"id":922,"question":"هل إذا أفتى الطبيبُ للمريض بأي فتوى يأخذ بها المريضُ أم لا بد من الرجوع إلى عالمٍ في ذلك؟","title":"هل يُؤخذ بفتوى الطبيب دون رجوع للعلماء؟","answer":"الجواب: لا، لابد أن يُراجع العلماء، الأطباء لهم شأنُهم، والعلم له أهله، فلا يعمل بالفتوى إلا بعد مُراجعة أهل العلم، ولو بالتليفون، ولو يُرسل أحدًا منهم، أو بالهاتف، أو يُرسل مَن يسألهم ويرجع يعلمه، والطبيب لا يجوز له أن يُفتي إلا عن علمٍ، الطبيب يسأل، نعم: سألتُ العالم الفلاني ويرى كذا وكذا، فالطبيب يسأل العلماء، العلماء هنا في مكة المكرمة، وفي أي مستشفى، في أي بلدٍ يسأل علماء البلاد وقُضاتهم عمَّا أشكل عليه، حتى يُفتي به المرضى.\nفالطبيب يكفيه أن يسأل، ولا يُفتي من كِيسه؛ لأنه ليس من أهل هذا الشأن، إنما يُفتي عمَّا يتعلق بالطبِّ، أما إذا كان يتعلق بالدين: إذا كان عنده علمٌ بالدين يُفتي بما علم من شرع الله، وإذا لم يكن عنده علمٌ يسأل أهلَ العلم، حتى يكون على بينةٍ، وحتى ينسب الفتوى إلى قائلها: قاله القاضي فلان، والعالم فلان، حتى يطمئنوا إليه، حتى يكون مبنيًّا على الطُّمأنينة.","link":"https://binbaz.org.sa/fatwas/20962/هل-يوخذ-بفتوى-الطبيب-دون-رجوع-للعلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0758هل إذا أفتى الطبيب للمريض بأي فتوى هل يأخذ بها المريض أم لا بدَّ من الرجوع لأهل العلم؟ابن باز.mp3","categories":["أصول الفقه"]},{"id":969,"question":"إذا بلغ شابٌّ الخامسة عشرة ولم تظهر عليه علامات البلوغ، فهل يُعتبر بالغًا؟","title":"ما العلامات التي يُعرف بها البلوغ والتكليف؟","answer":"الجواب: البلوغ يحصل بأحد ثلاثةٍ في حقِّ الرجل: بإكمال خمس عشرة سنة؛ لحديث ابن عمر رضي الله عنهما في \"الصحيحين\": أن الرسول ﷺ لما أكمل ابنُ عمر خمسة عشر أجازه في الجهاد، ولم يُجزه قبل ذلك، قال: \"فأجازني\"، وفي روايةٍ أخرى: \"ورآني قد بلغتُ\"، فدلَّ ذلك على أنه إذا كَمَّل خمسة عشر يكون من الرجال المكلَّفين.\nوالعلامة الثانية: الشعر، إذا أنبت الشعر الخشن حول الفرج، ويُسمَّى: الشِّعْرة، والعانة؛ يكون بالغًا؛ لأن الرسول ﷺ لما نزل بنو قريظة على حكمه قتل مَن أنبت، ولم يقتل مَن لم يُنبت وعَدَّه من الصبيان.\nوالثالث: الإنزال، إذا أنزل المني بالاحتلام أو بالشهوة ولو بغير احتلامٍ؛ صار مُكلَّفًا، كما قال تعالى: وَإِذَا بَلَغَ الْأَطْفَالُ مِنْكُمُ الْحُلُمَ فَلْيَسْتَأْذِنُوا [النور:59]، فإذا بلغ الحُلُمَ يعني: أنزل المني في النوم، أو عند التفكير نزل منه المني، صار بذلك مُكلَّفًا.\nهذه ثلاث علامات للرجل، والمرأة مثله، المرأة كذلك إذا حصلت منها هذه الأمور الثلاثة صارت مُكلَّفةً، تجب عليها الصلوات والصيام والحج إذا كانت مُستطيعةً، وإذا كان مُستطيعًا كذلك.\nوأما الزكاة فتجب على المال، ولو كان ما بلغ، الزكاة تجب في المال عند جمهور أهل العلم ولو كان صاحب المال ما بلغ.\nوالعلامة الرابعة في حقِّ المرأة: الحيض، إذا حاضت المرأةُ صارت بالغةً، هذه خاصَّة بالمرأة، العلامة الرابعة: الحيض، فإذا حاضت صارت من جملة المكلَّفين بالصلاة وغيرها.","link":"https://binbaz.org.sa/fatwas/21013/ما-العلامات-التي-يعرف-بها-البلوغ-والتكليف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0810إذا بلغ شخص الخامسة عشرة ولم تظهر عليه علامات البلوغ فهل يعتبر بالغاً؟ ابن باز فتاوى المحاضرات.mp3","categories":["أصول الفقه"]},{"id":1039,"question":"كثيرٌ من الناس يتركون الكثيرَ من هدي الرسول ﷺ بحجة أنها سنة يُثاب فاعلها ولا يُعاقب تاركها، فهل مع هؤلاء حقّ في قولهم هذا؟","title":"حكم ترك كثير من السُّنن لأنها ليست فرضًا","answer":"الجواب: هذا فيه تفصيلٌ: ما ثبت بالأدلة الشرعية أنه ليس بواجبٍ فلا حرج على مَن تركه، مثل النوافل: سنة الضحى، سنة الظهر، سنة العصر، سنة المغرب، سنة العشاء والوتر، هذه نوافل مَن تركها فلا شيء عليه، ومَن حافظ عليها فهو أفضل وأكمل، ومن أسباب حفظه للفرائض، ومن أسباب أيضًا جبر ما قد يقع من نقصٍ في الفرائض، ومن أسباب التوفيق له في أعماله كلها، ومَن ترك شيئًا منها فلا حرج عليه. لكن مَن ترك الواجبات هذا هو محلّ الاعتراض، ومحل الخطأ والتقصير والمعصية.\nوأما النوافل فأمرها أوسع والحمد لله، لكن ينبغي العناية بها، والمحافظة عليها؛ لما فيها من الخير العظيم، والحسنات الكثيرة، وتكميل الفرائض، ولأنه بها مع الاجتهاد في الخيرات يكون من السَّابقين. مَن اقتصر على الواجبات يكون من الأبرار فقط، أصحاب اليمين، لكن مَن توسَّع في الخيرات، وتوسَّع في الأعمال الصَّالحات، وأخذ بالنَّوافل، وابتعد عن المكروهات، واجتهد؛ صار بهذا من السَّابقين المقرَّبين، وهم أعلى درجة، وأعظم ثوابًا وأجرًا.","link":"https://binbaz.org.sa/fatwas/21086/حكم-ترك-كثير-من-السنن-لانها-ليست-فرضا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0882كثير من الناس يترك كثير من هدي النبي عليه الصلاة والسلام بحجة أنها سنة؟ ابن باز فتاوى المحاضرات.mp3","categories":["أصول الفقه"]},{"id":1256,"question":"هل كان النبيُّ ﷺ يجتهد برأيه في بعض الأمور؟ وإذا كان الجواب: نعم، فكيف نُوفق بين ذلك وبين قول الله تعالى: إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى [النجم:4]؟","title":"هل كان النبيُّﷺ يجتهد في بعض الأمور؟","answer":"الجواب:\nالمعروف أنه ﷺ أوتي القرآن ومثله معه، كما قال ﷺ، فهو يُخبر عن الله وعن شرعه، لا عن رأيه هو: وَالنَّجْمِ إِذَا هَوَى  ۝  مَا ضَلَّ صَاحِبُكُمْ وَمَا غَوَى  ۝  وَمَا يَنْطِقُ عَنِ الْهَوَى  ۝  إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى [النجم:1- 4].\nقد ذكر بعضُ أهل العلم أنه قد يجتهد، كما جرى يوم بدر، ولكن الله يُنبّهه على الخطأ إذا اجتهد، ولكن هذا محلّ نظرٍ، قد يكون هذا في أمرٍ، يعني: ظنَّه من الدين الذي جاء، واعتقد أنه من المشروع، ثم نبّه عليه ﷺ أنه ليس كذلك، وأن الواجب عدم أخذ الفداء، لكن الله أباح لهم ذلك .\nفالحاصل أنَّ القول بأنه له أن يجتهد له محل نظرٍ، وظاهر القرآن الكريم أنه ما كان يقول إلا عن الوحي عليه الصلاة والسلام، ويجتهد في الحكم بين الناس على طريق الشرع، مثلما قال في القضاء: وإنما أقضي على نحو ما أسمع، فهذا قضاء على الوحي؛ لأنه يقضي بالشاهدين واليمين، وهذا من الوحي، من الشريعة.\nفالحاصل أنَّ اجتهاده الذي على تطبيق الشريعة هذا من الوحي، أما اجتهاد ليس على تطبيق الشريعة فظاهر النصِّ خلافه، فظاهر القرآن الكريم خلاف ذلك، وأنه لا يجتهد اجتهادًا ليس مبنيًّا على القواعد الشرعية.\nس: مسألة النخل...؟\nالشيخ: هذا معروفٌ، هذا ما جزم فيه، هذا قال ما ظنّه في مسألة النخل، ما جزم به عليه الصلاة والسلام، فلما أخبروه قال: أنتم أعلم بأمر دُنياكم.","link":"https://binbaz.org.sa/fatwas/21318/هل-كان-النبيﷺ-يجتهد-في-بعض-الامور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/1061هل كان النبي صلى الله عليه وسلم يجتهد برأيه في بعض الأمور؟ابن باز.mp3","categories":["أصول الفقه"]},{"id":1419,"question":"التساهل بكلمة سُنة، نقول له: اترك اللحية يا فلان، قال: هي سُنة، قصر ثوبك، قال: هي سُنة؟","title":"ما حكم التساهل بالسُّنة والجهل بالواجب منها؟","answer":"الجواب:\nالسُّنة عند الفقهاء ضد الواجب، والسُّنة في اصطلاح المحدثين هي سُنة الرسول ﷺ سواء كانت واجبة أو مستحبة. يُعَلَّم الفقيه أنها سنة واجبة، يبين لها أنها فريضة واجب، ما هو مستحب.","link":"https://binbaz.org.sa/fatwas/21514/ما-حكم-التساهل-بالسنة-والجهل-بالواجب-منها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم التساهل بكلمة سنة.mp3","categories":["أصول الفقه"]},{"id":1434,"question":"هل السُّنة المُسْنونة تشمل السُّنة التي أُحييتْ بعدما ماتت سابقًا، والسنة المحياة إحياءً جديدًا؟","title":"ما ضابط إحياء السُّنة وتمييزها عن البدعة؟","answer":"الجواب:\nعام، السُّنة التي أحياها هو، أو ماتت ثم أحياها.  المقصود كونه في بلدٍ أو قريةٍ أو باديةٍ أو هِجرةٍ فيها سنة ميتة فأحياها، مثل: ما يعرفون صلاة الضحى فصار يصلي الضحى، ومثل: ما يصلون قبل العصر؛ فصلى أربع ركعات قبل العصر، ومثل: ما يُعلنون النكاح ولا يحطُّون وليمةً له؛ فأعلن النكاح، وما أشبه ذلك.\nس: هل هناك إنسان يُحيي سنةً جديدةً؟\nج: قد يكون في بعض الجهات سنة جديدة، يعني: قد أُميتت، قد يكون في بعض الجهات أناسٌ ما عرفوا مثلًا صلاة الضحى، أو ما عرفوا مثلًا صفة الحج، وأين الحج: في مكة أو في غير مكة؟ فجاء وعلَّمهم وأحيا لهم السنة، أو ما عرفوا برّ الوالدين، أو ما عرفوا صلة الرحم، أو ما عرفوا الوِتر، وما أشبه ذلك.\nس: هل تُسَمَّى \"جديدة\"؟\nج: هذا إحياء للسُّنن.\nس: لأنه يقول: \"سنة جديدة\"؟\nج: المعنى إحياؤها، ما هي بالبدعة، البدعة الجديدة ما تُسمَّى سُنة، المقصود مَن سَنَّ في الإسلام سنةً يعني: أحياها وأظهرها، هذا الأمر، وإلا إذا ابتدأها تصير بدعةً.","link":"https://binbaz.org.sa/fatwas/21529/ما-ضابط-احياء-السنة-وتمييزها-عن-البدعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ضابط السنة وإحياؤها.mp3","categories":["أصول الفقه"]},{"id":1437,"question":"هل تجب النيةُ في الدلالة على الخير؟","title":"هل تجب النيةُ في الدلالة على الخير؟","answer":"الجواب:\nلا بدّ من النية: إنما الأعمال بالنيات. وإذا لم يَنْوِ لم يحصل له الأجر هذا، إلا بالنية.","link":"https://binbaz.org.sa/fatwas/21533/هل-تجب-النية-في-الدلالة-على-الخير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النية في الدلالة على الخير.mp3","categories":["أصول الفقه"]},{"id":1845,"question":"مَن قال: أنَّ مَن تتبع الرُّخصَ تزندق؟","title":"ما معنى القول: \"مَن تتبع الرُّخصَ تَزَنْدَق\"؟","answer":"الجواب:\nهو قول بعض السلف، يعني: الرُّخَص المخالفة للشرع، حتى لو ما تتبعها، فكونه يأتي رخصةً تُخالف الشرع لا يجوز، لكن إذا زاد وتتبع صار أشدّ وأشدّ.","link":"https://binbaz.org.sa/fatwas/21954/ما-معنى-القول-من-تتبع-الرخص-تزندق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مَن تتبع الرُّخصَ تزندق.mp3","categories":["أصول الفقه"]},{"id":1855,"question":"تحريم الشيء هل يقتضي الفساد؟","title":"هل تحريم الشيء يقتضي الفساد؟","answer":"الجواب:\nج: قد يقتضي الفساد، وقد لا يقتضي الفساد، فالنهي عن البيع يقتضي فساد البيع، والنهي عن الصلاة في وقتٍ مُعينٍ -مثل وقت النَّهي- بدون سببٍ يُبطل الصلاة.\nس: يُبطلها؟\nج: نعم، إذا صلَّى في وقت النهي من دون سببٍ فالصلاة باطلة.\nس: النهي يقتضي الفساد؟ أو التحريم يقتضي الفساد؟\nج: التحريم يقتضي الفساد، إلا ما دلَّ الدليلُ على عدم تحريمه وعدم فساده.","link":"https://binbaz.org.sa/fatwas/21964/هل-تحريم-الشيء-يقتضي-الفساد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/تحريم الشيء هل يقتضي الفساد.mp3","categories":["أصول الفقه"]},{"id":1885,"question":"أيّهما يُقدّم: العالم الفاسق أو العابد الجاهل، لو مثلًا أردت أن أسمع لنصيحةٍ؟","title":"أيهما المُقَدَّم: عالمٌ فاسق أم عابدٌ جاهل؟","answer":"الجواب:\nالعابد ما عنده فائدة، ما عنده إلا التعبد فقط، فالعالم وإن كان فاسقًا، لكن إذا اشتبهت في فتواه اعرضها على غيره وانصحه بعد ذلك، اعرضها على غيره حتى يجتمع لك الخير، لا تعتمد عليه إلا بعد سؤال غيره، إذا وجدتَ غيره، أما العابد فما عنده فائدة، العابد مسكين.","link":"https://binbaz.org.sa/fatwas/21995/ايهما-المقدم-عالم-فاسق-ام-عابد-جاهل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/أيهما المقدم العالم الفاسق أو العابد الجاهل.mp3","categories":["أصول الفقه"]},{"id":1899,"question":"هل من التَّكَلُّف السؤال عن حكمة الأمر أو حكمة النهي في الأوامر والنَّواهي؟","title":"ما حكم السؤال عن حِكمة الأمر والنهي؟","answer":"الجواب:\nلا، ما هو من التَّكَلُّف، فإذا سأل عمَّا يظهر ليزداد علمًا ويزداد بصيرةً؛لا بأس، وإذا خَفِيَ لا يتكلَّف، بل يقول: الله أعلم، والحمد لله.\nس: هل هذا من صفات الجهل؟\nج: التَّكَلُّف من الجهل، ينشأ عن الجهل.\nس: هناك مَن يقول: أنا مجتهد، وربما كان اجتهاده هذا تكلُّفًا؟\nج: إن كان عن علمٍ وبصيرةٍ فلا بأس، أو على قواعد شرعية إذا دعت الحاجةُ إلى ذلك لا بأس، وإلا فهو متكلِّف، الذي ما عنده علمٌ ما يستطيع..... يسأل أهل العلم ولا يتعنت، يقول بالكلام الطيب والفعل الطيب، ولا يُشدِّد على نفسه، لا في فعلٍ، ولا في قولٍ.\nس: بعضهم يقول: أنا عالم؟\nج: يقول عمر: \"مَن قال إنه عالم فهو جاهل، ومَن قال مؤمن فهو كافر، يقول: مؤمن إن شاء الله\"، هذا من كلام عمر ، يُروى عن عمر.","link":"https://binbaz.org.sa/fatwas/22010/ما-حكم-السوال-عن-حكمة-الامر-والنهي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل السؤال عن حكم الأمر أو النهي من التكلف.mp3","categories":["أصول الفقه"]},{"id":1900,"question":"مَن قال أن باب الاجتهاد مقفولٌ في هذه الأزمنة؟","title":"هل باب الاجتهاد مفتوح في هذا الزمان؟","answer":"الجواب:\nما عنده خبر، مقفول عنه وعن أمثاله، مقفول عن أهل الجهل، ما هو مقفول عن أهل العلم، إلى أن يبعث الله الريح الطيبة حتى تقبض أرواح المؤمنين والمؤمنات ولا يبقى إلا الأشرار.\nس: يقول: بناءً على عدم توافر شروط المُجتهد؟\nج: إذا ما توافرت فيه توافرت في غيره، إذا ما توافرت فيه لا يُسَدّ الباب.","link":"https://binbaz.org.sa/fatwas/22011/هل-باب-الاجتهاد-مفتوح-في-هذا-الزمان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل باب الاجتهاد مفتوح في هذا الزمان.mp3","categories":["أصول الفقه"]},{"id":2541,"question":"اجتهاد الأنبياء؟","title":"حكم اجتهاد الأنبياء في شرائعهم","answer":"الجواب: يجتهد النبي فيما يظهر له من الشريعة التي جاء فيها.\nس: داود وسليمان ما كان لهم شريعة؟\nالشيخ: بلى عندهم، لكن ما جاءهم وحي بهذا، هذه اجتهادات مثل ما قال النبي ﷺ: إني أقضي لكم بنحو ما أسمع النبي محمد ﷺ، النبي قد يقضي بالاجتهاد، وقد يقضي بالوحي.\nس: إنْ كان الاجتهاد ما هو صواب...؟\nالشيخ: إن أصاب فله أجران، وإن أخطأ فله أجر، مثل ما قال ﷺ.\nس: إن كان اجتهادهم صوابًا أُقروا من الله على ذلك؟\nالشيخ: نعم.\nس: وإلا نزل الوحي؟\nالشيخ: قد ينزل الوحي، وقد يُقَرُّون على اجتهادهم ويكون لهم أجر الاجتهاد ويفوت أجر الصواب، ما فيه دليل على أنه ينزل الوحي، قد يجتهد.\nس: في قضية مثال؟\nالشيخ: مثل ما قال في حديث أم سلمة في الصحيحين: تختصمون إليّ ولعل بعضكم أن يكون ألحن بحجته من بعض فأقضي له بنحو ما أسمع، فمن قطعت له من حق أخيه شيئًا فإنما أقطع له قطعة من النار فليحملها أو ليذرها هذا معناه الاجتهاد.","link":"https://binbaz.org.sa/fatwas/22672/حكم-اجتهاد-الانبياء-في-شراىعهم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/اجتهاد الأنبياء فيما كان لهم شريعة.mp3","categories":["أصول الفقه"]},{"id":2542,"question":"شَرْعُ مَنْ كان قبلنا إنْ كان وافق شرعنا هل نأخذ به؟","title":"حكم الأخذ بشرع مَنْ قبلنا إنْ وافق شرعنا","answer":"الجواب: نعم، هو شَرْع لنا إذا لم يأت شَرْعُنا بخلافه.","link":"https://binbaz.org.sa/fatwas/22673/حكم-الاخذ-بشرع-من-قبلنا-ان-وافق-شرعنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يتم الأخذ بشرع من كان قبلنا إن وافق شرعنا.mp3","categories":["أصول الفقه"]},{"id":2573,"question":"من قال أن الطب النبوي بالتجربة لا بالوحي؟","title":"هل الطب النبوي بالتجربة أم بالوحي؟","answer":"الجواب: يقول ربك جل وعلا: وَمَا يَنْطِقُ عَنِ الْهَوَى ۝ إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى [النجم:3-4].","link":"https://binbaz.org.sa/fatwas/22706/هل-الطب-النبوي-بالتجربة-ام-بالوحي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الطب النبوي بالتجربة أم بالوحي.mp3","categories":["أصول الفقه"]},{"id":2680,"question":"بالنسبة لقول الصحابي: هل قوله حجة إذا لم يخالف الدليل والنص؟","title":"ما شروط حُجِّيَّة قول الصحابي؟","answer":"الجواب: عند كثير من أهل العلم أنه حجة إذا لم يخالفه غيره، ولم يخالف نصًّا من كتاب ولا من سُنة، ولم يخالفه غيره من الصحابة أيضًا؛ فهو قول قوي أنه يحتج به؛ لأنهم أعلم الناس بعد الأنبياء، رضي الله عنهم وأرضاهم.","link":"https://binbaz.org.sa/fatwas/22818/ما-شروط-حجية-قول-الصحابي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل قول الصحابي حجة إذا لم يخالف الدليل.mp3","categories":["أصول الفقه"]},{"id":2795,"question":"قرأت مقالة يقول أن الاختلاف الذي وقع بين الفقهاء كله من اختلاف التنوع، هل هذه المقالة صحيحة؟","title":"ما صحة أن اختلاف الفقهاء اختلاف تنوع؟","answer":"الجواب: قد تكون صحيحة من وجه، وليست صحيحة من وجه؛ لأنه قد تختلف الأحكام، فإذا اختلفت الأحكام صار متنوعًا، لكن قد لا تختلف الأحكام وتصير الأحكام واحدة لكن تختلف الصفات.\nس: إذًا يكون مقسم قسمين: اختلاف تنوع واختلاف تضاد؟\nالشيخ: قد يكون تنوع، وقد يكون تضاد، نعم.","link":"https://binbaz.org.sa/fatwas/22943/ما-صحة-ان-اختلاف-الفقهاء-اختلاف-تنوع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل الاختلاف الذي وقع بين الفقهاء اختلاف تنوع.mp3","categories":["أصول الفقه"]},{"id":2866,"question":"كيف يُفَرِّق بين كراهة التنزيه وكراهة التحريم؟","title":"ما الفرق بين كراهة التنزيه وكراهة التحريم؟","answer":"الجواب: الأصل في النهي التحريم، هذا هو الأصل، إلا ما دل عليه الدليل، كأنهم أخذوا هذا من باب آداب الدعاء، ليس من الواجبات، كأنهم أخذوه من المعنى يعني، والأصل في الأوامر الوجوب، والأصل في النواهي للتحريم، هذا هو الأصل.","link":"https://binbaz.org.sa/fatwas/23020/ما-الفرق-بين-كراهة-التنزيه-وكراهة-التحريم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الفرق بين كراهة التنزيه وكراهة التحريم.mp3","categories":["أصول الفقه"]},{"id":2873,"question":"فتوى الصحابي أو قوله يُؤخذ به إذا ما وُجِد مُخالف؟ حُجّة يعني؟","title":"ما حكم فتوى وقول الصحابي؟","answer":"الجواب: نعم إذا لم يكن له مخالف من الصحابة ولا في السُّنة ما يخالف، نعم؛ لأنهم أعلم الناس بالشريعة.  عند جَمْع من أهل العلم، قولُه حُجّة إذا لم يخالفه غيره.\nس: يُعدّ إجماعًا؟\nالشيخ: قد يُقال إجماع سكوتي.\nس: لا يُقَدَّم على فتوى الصحابي فتوى عالم أو فتوى تابعي؟\nالشيخ: لا، يُقَدَّم النص، إذا جاء نص ما يخالف، أما فتوى الصحابة فهي مقدّمة على من بعدهم، إلا إذا كان هناك نص مقدم على الجميع، إذا وجد حديث قُدّم على الجميع.","link":"https://binbaz.org.sa/fatwas/23028/ما-حكم-فتوى-وقول-الصحابي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأخذ بفتوى وقول الصحابي.mp3","categories":["أصول الفقه"]},{"id":3100,"question":"هل هناك كتب توصون بها من أراد أن يتعلم أصول الفقه؟","title":"ما الكتب التي يُوصى بها في أصول الفقه؟","answer":"الجواب: فيه للفتوحي، وفيه الورقات، وفيه لصاحب المغني \"روضة الناظر\"، مراجعتها مفيدة.","link":"https://binbaz.org.sa/fatwas/23260/ما-الكتب-التي-يوصى-بها-في-اصول-الفقه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/كتب يستفاد منها في أصول الفقه.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":3115,"question":"فِعْل النبي ﷺ هل يَنْسَخُ  قَوْلَه؟","title":"هل فِعْلُ النبي ﷺيَنْسَخُ قولَه؟","answer":"الجواب: مهما أمكن الجمع لا يُصار إلى النسخ إلا بشرطين: عدم إمكان الجمع، ولا بد أن يكون الجمع غير ممكن. والتاريخ معروف.  هذا من أسباب النسخ؛ إذا عُلم التاريخ ولم يمكن الجمع.  أما إذا أمكن الجمع أو لم يُعلم التاريخ؛ فلا بد من الجمع، ولا يمكن النسخ.\nس: من قال إن الفعل لا يَنسخ القول؛ لأن الفعل...؟\nالشيخ: لأن الفعل تفسير، ما هو ينسخ، الفعل يفسّر.\nس: ربما اقتضى الخصوصية؟\n الشيخ: الفعل يفسّر، نعم.","link":"https://binbaz.org.sa/fatwas/23275/هل-فعل-النبي-ﷺ-ينسخ-قوله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل ينسخ فعل النبي قوله.mp3","categories":["أصول الفقه"]},{"id":3349,"question":"الدابّة تساوي السيارة (من جهة الإفتاء فيها) أم أنها تختلف عنها؟","title":"هل يُفتي المفتي في السيارة والطائرة ونحوها؟","answer":"الجواب: أي نعم، والسيارة كذلك من باب أوْلى، والسيارة، والباخرة، والقطار، والطائرة، حتى الذي في الطائرة يُفتي.","link":"https://binbaz.org.sa/fatwas/23515/هل-يفتي-المفتي-في-السيارة-والطاىرة-ونحوها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/النبي أفتى وهو على الدابة، فهل الدابة تساوي السيارة.mp3","categories":["أصول الفقه"]},{"id":3407,"question":"بعض الأصوليين يقول أن رؤية ابن عمر هذه (للنبي ﷺ يقضي حاجته مستقبل الشام مستدبر الكعبة) كانت خاصة من خواص الرسول ﷺ فلا حجة فيها؟","title":"هل يجوز استدبار الكعبة في قضاء الحاجة؟","answer":"الجواب: لا، ما لهذا الكلام سَنَد، فِعْلُه ﷺ حجة، وقوله حجة: لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب: 21].\nس: إذا تعارض القول مع الفعل؟\nالشيخ: القول مُقَدّم، لكن الفعل يُفَسِّر القول؛ أنه ليس للوجوب: إذا كان في الصحراء وَجَب، وفي البيوت لا، ما يلزم، لكن إذا ترك الاستقبال في البيوت فيكون حسنًا إن شاء الله، مثل ما قال أبو أيوب: ننحرف عنها، ونستغفر الله.","link":"https://binbaz.org.sa/fatwas/23579/هل-يجوز-استدبار-الكعبة-في-قضاء-الحاجة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حديث رأيت النبي يقضي حاجته مستقبل الشام مستدبر الكعبة... خاصة من خواص الرسول؟.mp3","categories":["شروح الحديث","أصول الفقه","رؤيا الهلال"]},{"id":3830,"question":"قول الزهري الآن في البول: (لا يحل شرب بول الناس لشدّة تنزل؛ لأنه رجس) قياس يريد أن نقيسه على المُسكر؟","title":"هل يُقاس شربُ البول اضطرارًا على المُسكر؟","answer":"الجواب: يدل على أنه ما يرى القياس في المحرَّمات، فالمحرمات ليس فيها قياس، الاقتصار على الوارد فيها، ولكن هذا ليس بمسلّمٍ.\nس: الزهري أراد أن يقيس؟\nج: قصده أنه لا يُقاس البول على الميتة، لا يقاس الرخصة بالميتة خاصة.","link":"https://binbaz.org.sa/fatwas/24032/هل-يقاس-شرب-البول-اضطرارا-على-المسكر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/قال الزهري لا يحل شرب بول الناس لشدّة تنزل لأنه رجس.mp3","categories":["أصول الفقه"]},{"id":3953,"question":"الاستدلال بكلام الأمم الأخرى... إذا كان لتوضيح الأمر؟","title":"ما حكم نقل أخبار بني إسرائيل؟","answer":"الجواب: مثل ما كان يقول النبي ﷺ: حدثوا عن بني إسرائيل ولا حرج إذا كانت أشياء لا تصادم الحق يُحَدِّث بها لا بأس، أما ما يصادم الحق فلا؛ لأن أخبار بني إسرائيل وما ينقل عن الأوائل ثلاثة أقسام: قسم يطابق الحق فينقل. وقسم يخالف الحق فلا ينقل بل يرفض. وقسم ليس فيه لا هذا ولا هذا، لم يتضح فيه ما يوافق الحق ولا ما يخالفه؛ فهذا ينقل على سبيل التحدث؛ لقوله ﷺ: حدثوا عن بني إسرائيل ولا حرج وقوله: لا تصدقوهم ولا تكذبوهم؛ فقد يكون حقًا فتكذبوه، وقد يكون باطلاً فتصدقوه. ومراده ﷺ يعني: الشيء الذي لم يتضح أنه حق ولم يتضح أنه باطل، فأما ما اتضح مما ينقل عنهم أنه باطل يُكذّب، وما اتضح أنه حق يُصدّق، وإنما يُتوقف في الشيء المشتبه، هذا هو الذي قال فيه: حدثوا عن بني إسرائيل ولا حرج الشيء المشتبه الذي لم يتضح وجهه، فينقل عنهم؛ لما فيه من العبر والعظات.","link":"https://binbaz.org.sa/fatwas/24176/ما-حكم-نقل-اخبار-بني-اسراىيل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الضابط في نقل أخبار بني إسرائيل.mp3","categories":["أصول الفقه"]},{"id":3977,"question":"هل الأصل فيها الوجوب؟","title":"هل الأصل في الأوامر الوجوب؟","answer":"الجواب: هذا هو الأصل في الأوامر، القاعدة، إلا أن يأتي صارف.","link":"https://binbaz.org.sa/fatwas/24205/هل-الاصل-في-الاوامر-الوجوب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الأوامر الأصل فيها الوجوب.mp3","categories":["أصول الفقه"]},{"id":4017,"question":"في الاحتجاج بشرع من قبلنا؟","title":"حكم الاحتجاج بشرع من قبلنا","answer":"الجواب: مثل ما سمعت أنه: شرع لنا ما لم يأت شرعنا بخلافه، إذا حكاه النبي وأقره صار شرعًا لنا، إلا إذا نهى عنه النبي ﷺ، أو جاء في أحاديث أخرى تنهى عنه أو تخالفه.","link":"https://binbaz.org.sa/fatwas/24253/حكم-الاحتجاج-بشرع-من-قبلنا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الاحتجاج بشرع من قبلنا.mp3","categories":["أصول الفقه"]},{"id":4713,"question":"إذا جاء حديثٌ صحيح مُطلق، وجاء حديثٌ أقل درجة في الصحة منه فقيد هذا الحديث؟","title":"متى يحمل الحديث المطلق على المقيد؟","answer":"الجواب: إذا كان كلاهما صحيحًا؛ فالمطلق يُحمل على المقيد.  أما إذا كان ضعيفًا لا، الضعيف ما يُعمل به، مُقدَّم عليه الصحيح.","link":"https://binbaz.org.sa/fatwas/25005/متى-يحمل-الحديث-المطلق-على-المقيد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في حمل المطلق على المقيد.mp3","categories":["أصول الفقه"]},{"id":4987,"question":"من قال باب الاجتهاد مُقْفَل؟","title":"ما صحة القول بأن باب الاجتهاد مُقْفَل؟","answer":"الجواب: باب اجتهاده هو، باب الجاهل مُقْفَل، أما اجتهاد أهل العلم ما هو مُقْفَل، لكن الجُهَّال مُقْفَل عليهم، لا يجوز لهم.","link":"https://binbaz.org.sa/fatwas/28499/ما-صحة-القول-بان-باب-الاجتهاد-مقفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/ما صحة القول بأن باب الاجتهاد مقفل؟.mp3","categories":["أصول الفقه"]},{"id":5039,"question":"طيب، عمل أهل المدينة ما هو بحجة؟","title":"هل عمل أهل المدينة حجة في الشرع؟","answer":"الجواب: لا، ليس عمل أهل المدينة حجةً، ولا عمل أهل مكة حجة، ولا عمل أهل الشام حجة، ولا عمل أهل نجد حجة، الحجة قال الله، قال رسوله ﷺ.","link":"https://binbaz.org.sa/fatwas/29000/هل-عمل-اهل-المدينة-حجة-في-الشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/هل عمل أهل المدينة حجة في الشرع؟.mp3","categories":["أصول الفقه"]},{"id":5342,"question":"لماذا لم يجتمع علماء الأمة اليوم ويخرجوا للأمة بفقه موحد؟","title":"لماذا لا تجتمع الأمة على فقه مُوَحَّد؟","answer":"الجواب: جمع الناس غير متيسر، جمع الناس متعسر غير متيسر، والفقه والأدلة معروفة، كتبهم موجودة، وطالب العلم كتبه بين يديه، طالب العلم صاحب البصيرة يستطيع يأخذ من كتب الحديث وكتب أهل العلم ما يدعو به إلى الله ويرشد به الأمة وأصل ذلك وأساسه كتاب الله العظيم وسنة رسوله الأمين عليه الصلاة والسلام.[1]","link":"https://binbaz.org.sa/fatwas/31015/لماذا-لا-تجتمع-الامة-على-فقه-موحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aljwab_alkafi 063.mp3","categories":["أصول الفقه"]},{"id":5478,"question":"هل الأمر مناط بالتَّمييز؟","title":"ما ضابط التمييز عند الطفل في سن السابعة؟","answer":"الجواب: نعم، التَّمييز سبع سنين، هذا وصف أغلبي للتَّمييز، وقد يكون ابن سبع وابن ثمانٍ ولا يفهم، بعض الناس كذا، وبعض الناس نابغة، صغير ابن أربع أو خمس سنين وهو يفهم، الأكثر من الناس أهل السبع. ولهذا احتجَّ العلماء بمَن حفظ: كمحمود بن الربيع، عقل مجَّةً مجَّها النبيُّ ﷺ في فمه وهو ابن أربع سنين أو خمس سنين، عقلها وضبطها ورواها بعد الكِبَر. وكثير من الصِّغار يحفظون أشياء وقعت لهم وهم في الخمس والستّ سنين، ويحفظونها ويروونها بعد كِبَرهم.[1]","link":"https://binbaz.org.sa/fatwas/31370/ما-ضابط-التمييز-عند-الطفل-في-سن-السابعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/al tabseir 003.mp3","categories":["أصول الفقه"]},{"id":5496,"question":"الاختلاف في مسألة العذر بالجهل من المسائل الخلافية؟","title":"هل مسألة العذر بالجهل من المسائل الخلافية؟","answer":"الجواب: مسألة عظيمة، والأصل فيها أنه لا يُعذر إنْ كان بين المسلمين، مَن بلغه القرآنُ والسنةُ لا يُعذر، الله جلَّ وعلا قال: هَذَا بَلَاغٌ لِلنَّاسِ [إبراهيم:52]، وقال: وَأُوحِيَ إِلَيَّ هَذَا الْقُرْآنُ لِأُنْذِرَكُمْ بِهِ وَمَنْ بَلَغَ [الأنعام:19]، مَن بلغه القرآن والسنة غير معذورٍ، إنما أُتي من تساهله وعدم مُبالاته. س: لكن هل يُقال أنها مسألة خلافية؟ ج: لا، ما هي بخلافية، إلا في الدَّقائق التي قد تخفى، مثل قصة الذي قال لأهله: أحرقوني.[1]","link":"https://binbaz.org.sa/fatwas/31405/هل-مسالة-العذر-بالجهل-من-المساىل-الخلافية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/kashf alshubuhat 009.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":5633,"question":"كيف نفرق بين فعل النبي ﷺ أنه سُنة أو أنه عادة؟","title":"ما كيفية تمييز السُّنة أو العادة من فعل النبي؟","answer":"الجواب: الأصل أن أفعاله ﷺ سُنة، هذا هو الأصل لَقَدْ كَانَ لَكُمْ فِي رَسُولِ اللَّهِ أُسْوَةٌ حَسَنَةٌ [الأحزاب:21] إلا ما يعرف بالأدلة الأخرى التي..... فيها المؤمن أنها من الأمور العادية التي لم يأمر فيها النبي ﷺ بشيء ولم يواظب عليها، مثل: أنواع الطعام، وأنواع الملابس، وأشباه ذلك التي لا يواظب عليها النبي ﷺ، يدل على أنها أمور عادية، ومثل مسألة تربية الرأس وحلقه، ومثل لبس القميص أو الإزار والرداء. س: من قال إن الفعل الذي لم يترتب عليه أجر أو نهي أو أمر يكون عادة؟ الشيخ: الأصل هو التأسي بالنبي ﷺ إلا ما كان من الأمور العادية التي لا يواظب عليها عليه الصلاة والسلام، تكون عادية تارة يفعلها وتارة يتركها، تكون عادية من جنس اللباس وأشباهها، وأنواع الأكل، وأشباه ذلك. س: والتأتي بهذه العادات يؤجر عليها؟ الشيخ: الله أعلم.[1]","link":"https://binbaz.org.sa/fatwas/31630/ما-كيفية-تمييز-السنة-او-العادة-من-فعل-النبي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/sunan alnisayiy 002.mp3","categories":["أصول الفقه"]},{"id":5669,"question":"في كل بلدٍ من بلدان المسلمين يوجد مُفتٍ رسميّ،  متى تكون فتوى المفتي الرسمي مُلزمة للناس لا تجوز مُخالفتها؟ أفتونا أثابكم الله.","title":"هل فتوى المفتي الرسمي مُلزمة للناس؟","answer":"الجواب: الفتوى الرسمية وغيرها غير مُلزمة، الملزم: قال الله، قال رسوله، فإذا أفتى المفتي أو العالم بما يُخالف الشرع لا تلزم فتواه، المعول على: قال الله، وقال رسوله: الكتاب والسُّنة. أما فتوى الناس فقد تُخطئ، وقد تُصيب، سواء كان مُفتيًا رسميًّا أو غيرها، سواء كان مدرسًا أو غير مُدرسٍ، تُعرض الفتاوى على الكتاب والسُّنة، فما وافقهما قُبِل، وما خالفهما رُدَّ على قائله كائنًا من كان.[1]","link":"https://binbaz.org.sa/fatwas/31706/هل-فتوى-المفتي-الرسمي-ملزمة-للناس","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/aldurus almuhima 015.mp3","categories":["أصول الفقه"]},{"id":5968,"question":"ظهر أحد المفكرين الإسلاميين على شاشة التلفاز وقال: إن عبارة لا اجتهاد مع النص فيها تعسف، وتضييق على الناس في الوقت الحاضر؛ لأن هذه النصوص لا تتمشى في بعض الأحيان مع روح العصر؟","title":"حكم الاجتهاد مقابل النص","answer":"الجواب: هذا مقال خطير، ومنكر ظاهر، والكلام صحيح لا اجتهاد مع النص، قد أجمع العلماء على أن الاجتهاد محله عند عدم النص إذا خفيت النصوص، وصار الناس إلى الاستنباط، والقياس هذا محل الاجتهاد.  وأما إذا وجد النص من كلام الله، أو سنة رسوله -عليه الصلاة والسلام؛ فليس هناك محل للاجتهاد، فالشريعة جاءت في عصر النبي ﷺ ولما بعده من العصور إلى يوم القيامة، مبعوث إلى يوم القيامة إلى الناس، كلهم إلى يوم القيامة، فلا يجوز لأحد أن يخالف النص الصحيح الثابت عن رسول الله ﷺ ولا يجوز أن يقال: إنه لا يتمشى مع روح العصر.  يجب أن تخضع روح العصر لكلام الله، وسنة نبيه، وأما أن يخضع كلام الله، وكلام رسوله للعصر فهذا باطل، هذا منكر، ولا يقوله من يعقل عن الله، ولا يؤمن بالله، واليوم الآخر، فهل يقول لنا إنسان: إذا كان روح العصر ما تخضع لتحريم الأم، أو تحريم البنت، أو تحريم الأخت، ولا يجوز أن ينكح أمه، أو من روح العصر أن يجمع الرجل بين المرأة، وعمتها، وبين المرأة، وخالتها، وأن ينكر النص الذي حرم ذلك من يقول هذا؟ أو النص جاء بالخيار للبيعين، ولا بأس أن يهدر ذلك؛ لأن الحاجة ماسة إلى عدم الخيار، أو ما أشبه ذلك، أو يقول الحاجة ماسة إلى إبطال الرضاع، ولا يشرع الرضاع، ولا يكون له حكم؛ لأن روح العصر تقتضي التوسع في الزوجات، والتوسع في النكاح، وأن ينكح الإنسان رضيعته أخته من الرضاع، وعمته من الرضاع، وأمه من الرضاع من يقول هذا؟ النص حاكم على الناس، ولا يجوز أن يحكم على النص، بقول أحد من الناس، ولا بأقوال الصحابة، حتى الصحابة أفضل الناس إذا خالفوا النص؛ وجب الأخذ بالنص، وترك قول من قال من الصحابة بخلافه، وهم أصحاب الرسول، وأفضل الناس بعد الأنبياء، إذا قال واحد منهم قولًا، والنص يخالفه؛ وجب أن يؤخذ النص الثابت عن رسول الله -عليه الصلاة والسلام- وألا يؤخذ بقول الصحابي؛ لأن قصاراه أنه جهل النص، وخفي عليه، وليس بمعصوم، والنص معصوم؛ فوجب الأخذ بالنص. والحاصل، والخلاصة: أن قول هذا القائل: إن قول العلماء: لا اجتهاد مع النص، أنه كلام ليس على إطلاقه، وأنه لا مانع من مخالفة النص إذا كان لا يتمشى مع روح العصر، فهذا كلام باطل، صاحبه على خطر من الردة عن الإسلام، نعوذ بالله.","link":"https://binbaz.org.sa/fatwas/1335/حكم-الاجتهاد-مقابل-النص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_303.mp3","categories":["أصول الفقه"]},{"id":5978,"question":"يا شيخ، بالنسبة للاجتهاد في فهم النص؛ لأنه ربما يكون يعرض لبعض الناس مجرد نص، دون فهم، قد يكون خاص، أو عام، أو مطلق، أو مقيد، أو ناسخ، ومنسوخ؟","title":"كيفية فهم النصوص","answer":"الجواب: .. النصوص على حسب قواعد العلم، إذا.. النصوص يجب أن يكون على القواعد المعروفة التي قررها أهل العلم من تقييد المطلق بالمقيد، وتخصيص العام بالخاص، الأخذ بالمنسوخ من الناسخ، هذه أمور معروفة في أصولها، لكن قوله: إنه لا اجتهاد مع النص ليس بمستقيم، فهذا غلط!.","link":"https://binbaz.org.sa/fatwas/1349/كيفية-فهم-النصوص","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_306.mp3","categories":["أصول الفقه"]},{"id":6165,"question":"إننا نحن المسلمين نتساءل: لماذا لا يجتمع المسلمون على مذهب واحد، وتحل جميع الاختلافات في بعض الأمور في الدين الإسلامي؟","title":"استحالة اجتماع الناس على مذهب واحد","answer":"الجواب: هذا من المستحيلات -بارك الله فيك- ما اجتمع الصحابة حتى يجتمع من بعدهم، الصحابة أفضل الناس، ولم يجتمعوا على شيء واحد، لا بدّ من خلاف؛ لأن العلم يتفاوت، فهذا يعلم أكثر من هذا، وهذا أكثر من هذا، وفوق كل ذي علم عليم، فاجتماع الناس على شيء واحد من المستحيلات.","link":"https://binbaz.org.sa/fatwas/1625/استحالة-اجتماع-الناس-على-مذهب-واحد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_516.mp3","categories":["أصول الفقه"]},{"id":6228,"question":"اشتغل عند إحدى النساء خادم، ففي يوم من الأيام تقول لي: إذا لم تفعل بي الزنا؛ فسوف أقتلك، وتهددني بالسلاح، وهو في يدها، فماذا أعمل؟ وهل أمتنع، وأرضى بالقتل، وما هو الحل؟","title":"حكم من هدد بالقتل على أن يزني","answer":"الجواب: نسأل الله العافية، والسلامة! هذا سؤال خطير -نسأل الله العافية- والواجب عليه أن لا يخضع لهذا الأمر، وأن يجتهد في الهرب منها، والبعد عنها، وعن خدمتها؛ لأن هذا هو الواجب عليه، البعد عما حرم الله، والتماس أي حيلة يستطيعها في البعد عما حرم الله، ولا يوافقها على فعل الفاحشة. لكن لو فرض أنه ما استطاع، وأنه ليس له خيار إلا الزنا، أو القتل؛ فالصحيح من أقوال العلماء: أنه في حكم المكره في هذه الحالة، فهو مكره، والمكره لا ينتشر، المكره إذا كان صادقًا لا ينتشر، ولا يستطيع الجماع، هذا هو المعروف؛ لأن المكره يختل مزاجه، وتختل نفسه، فلا يستطيع، فلو حاول ذلك لم يستطع، لكن لو قدر أنه ألزم بهذا الشيء، أو القتل؛ لكان هذا أسهل مع التوبة إلى الله، ومع فعل ما يستطيع إذا كان صادقًا.","link":"https://binbaz.org.sa/fatwas/1730/حكم-من-هدد-بالقتل-على-ان-يزني","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_576.mp3","categories":["أصول الفقه"]},{"id":6324,"question":"في أحد المدارس أحد الإخوة المدرسين يقول: إن المذاهب الأربعة كلها يجوز العمل بها، وأن الرسول عمل بها كلها، فهل هذا صحيح؟","title":"حكم القول بجواز العمل بالمذاهب الأربعة كلها","answer":"الجواب: لا، هذا ما يدري، المذاهب الأربعة علماء أربعة لهم أقوال، قد يخطئون في بعضها، فمن أخذ بما وافق الدليل منها أصابها، ومن ترك ما خالف الدليل؛ فقد أصاب، أما الذي يأخذ بما وافق هواه منها، ولو خالف الدليل؛ فهذا مخطئ، وعاص. والرسول ﷺ قبلها، ولا يقال: عمل بها الرسول، قبلها -عليه الصلاة والسلام- وهو المقتدى به -عليه الصلاة والسلام- فما وافق قوله، وسنته، وطريقته؛ فهو الحق، وما خالف ما عليه الرسول؛ فهو باطل. والمذاهب الأربعة معناها: قول العلماء الأربعة، علماء المسلمين، الشافعي، وأبو حنيفة، وأحمد، ومالك، يقال لهم: علماء، ويقال لهم: أصحاب المذاهب الأربعة؛ لأن أصحابهم فرعوا على أقوالهم، وكتبوا في أقوالهم، وآرائهم، فاشتهرت هذه المذاهب، وهم علماء أربعة، يغلب عليهم الخير، ويغلب عليهم الصواب.  وهم علماء حق، وأئمة هدى، لكن قد يقع من بعضهم بعض الأغلاط، بعض الأخطاء، فإذا عرفت أن هذا خطأ من قول مالك، أو أبي حنيفة، أو أحمد، أو الشافعي، إذا عرفه العالم؛ يطرح الخطأ، هم أوصوا، قالوا: نحن نخطئ، أوصوا الناس، أوصوا الذين بعدهم، قالوا: لا تقلدونا، فخذوا الخير من حيث أخذنا، وقالوا: إذا خالف قولنا قول الرسول؛ فاتركوا قولنا، وارموا بعرض الحائط، ولا تأخذوا به، أوصوا الناس -رضي الله عنهم ورحمهم- فما وافق الحق من أقوالهم؛ أخذ به، كل ما خالف الحق؛ ترك، وليست أقوالهم كلها موافقة للرسول ﷺ لا، بل فيها الخطأ، وفيها الصواب، وإن كان الغالب الصواب، ولله الحمد، لكن قد يقع من بعضهم بعض الخطأ. \n..........","link":"https://binbaz.org.sa/fatwas/1869/حكم-القول-بجواز-العمل-بالمذاهب-الاربعة-كلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_660.mp3","categories":["أصول الفقه"]},{"id":6363,"question":"فضيلة الشيخ متى تكلف المرأة بالأحكام الشرعية من عمرها؟","title":"وقت تكليف المرأة بالأحكام الشرعية","answer":"الجواب: المرأة مثل الرجل، تكلف المرأة مثل الرجل، تكلف بأمور ثلاثة، وتزيد رابعًا هي، متى بلغت خمسة عشرة سنة، وأكملتها؛ صارت امرأة مكلفة بالصلاة، وغيرها، والصيام، والحج، ونحو ذلك. وكذلك إذا أنبتت الشعر الخشن، تسمى الشعرة العانة على الفرج؛ صارت مكلفة -أيضاً- كالرجل، وهكذا بالإنزال، إذا أنزلت المني بشهوة عن نظر، وعن تفكير، أو عن احتلام؛ فهي تكون بهذا مكلفة كالرجل، هذه الأمور الثلاثة مشتركة بين الرجال، والنساء. أولاً: بلوغ خمسة عشر سنة على الراجح، إذا أكملت خمسة عشر سنة؛ صارت امرأة مكلفة بأحكام الدين كالرجل، سواء. الثاني: إنبات الشعر الخشن حول الفرج، هذا أيضاً من أسباب التكليف من الرجل، والمرأة جميعاً. الثالث: إنزال المني بشهوة، سواء باحتلام، أو عن تفكير، أو نظر، ونحو ذلك، فمتى أنزلت، أو أنزل المني؛ صارا مكلفين. والأمر الرابع: يختص بها وهو الحيض، فمتى حاضت؛ صارت مكلفة بذلك. هذه الأمور هي التي بها التكليف للمرأة، والرجل جميعاً، وهي ثلاثة مشتركة، والرابع للمرأة خاصة، وهو الحيض.","link":"https://binbaz.org.sa/fatwas/1941/وقت-تكليف-المراة-بالاحكام-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_728.mp3","categories":["قضايا المرأة","أصول الفقه","اللباس والزينة"]},{"id":6427,"question":"إذا كنت على أحد المذاهب كالمذهب الحنبلي مثلًا، هل علي أن آخذ بالرخص في المذاهب الأخرى؟","title":"حكم تتبع رخص الفقهاء","answer":"الجواب: عليك أن تأخذ بالدليل، لا بالرخص، قال بعض السلف: من تتبع الرخص؛ تزندق، كل مذهب يكون فيه بعض الأغلاط، بعض الأخطاء من بعض أتباعه، أو من الإمام الذي هو منسوب إليه أنه غلط في بعض الروايات، وأنه خفي عليه بعض الأحاديث، فطالب العلم لا يتتبع الرخص.  وإذا كان في المسألة خلاف، ما هي بمسألة إجماع، فهناك رسائل بين أهل العلم، فطالب العلم يتحرى الدليل، وينظر في أقرب القولين، أو الأقوى للدليل، فيأخذ بما قام عليه الدليل، لا بتتبع الرخص.","link":"https://binbaz.org.sa/fatwas/2138/حكم-تتبع-رخص-الفقهاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_787.mp3","categories":["أصول الفقه"]},{"id":6491,"question":"هل الأصل في الأموال، والأعراض الحل، أم الحرمة مع الدليل؟","title":"الأصل في الأموال والأعراض الحرمة","answer":"الجواب: الأصل في الأموال، والأعراض الحرمة، الله حرم علينا أموالنا قال: وَلَا تَأْكُلُوا أَمْوَالَكُمْ بَيْنَكُمْ بِالْبَاطِلِ [البقرة:188] قال: وَلَا يَغْتَبْ بَعْضُكُمْ بَعْضًا [الحجرات:12].  والرسول ﷺ قال: إن دماءكم، وأموالكم، وأعراضكم عليكم حرام كحرمة يومكم هذا، في شهركم هذا، في بلدكم هذا خطبهم في يوم النحر في مكة -عليه الصلاة والسلام- فالأصل فيها التحريم في الأموال، والدماء، والأعراض، فلا يحل منها إلا ما أحله الشرع، ما أحله الشرع من دمائنا بالقصاص، ورجم المحصن ... ما أحله الشرع، ومن الأعضاء السرقة، والمحاربة، ومن الأموال أن يأخذ الزكاة إذا أبى ... فلا يحل منها إلا ما أحله الشرع.","link":"https://binbaz.org.sa/fatwas/2236/الاصل-في-الاموال-والاعراض-الحرمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_856.mp3","categories":["أصول الفقه"]},{"id":6550,"question":"لقد سمعت بعض المشايخ في إحدى دروسه التلفزيونية: بأنه لا بأس من عمل مناسبة لمولود، أو مناسبة مضى عليها عام.. جامعة الرياض بمرور مضي خمسة وعشرين عامًا، يعني يتأسى بجامعة الرياض؟","title":"حكم الاحتفال بمناسبة ما دون تكرارها","answer":"الجواب: إذا لم يتخذه مولدًا يتكرر، إذا كانت المناسبة نعمة حدثت، فيجمع الناس لأنه قدم من سفر، أو شفي من مرض، يدعو أقاربه؛ لا بأس، العيد: ما يتكرر؛ يتخذ عادة تتكرر كل سنة، أو كل شهر، هذا العيد، أما إذا أولم وليمة بمناسبة قدوم من سفر، أو بمناسبة ولد له، يذبح فيها العقيقة يوم السابع، ويدعو من شاء من أقاربه، أو بمناسبة شفاه الله من مرض، فيجمعهم، ويقيم وليمة، أو ما أشبه ذلك؛ فليس هذا من الأعياد، بل هذا من باب شكر الله على نعمه، العيد ما يتكرر يدور في بزوال الشهر، أو في بزوال الأسبوع، أو بزوال العام يسمى عيدًا. السؤال: يعني من هذا أعياد الجلاء، وأعياد الوطنية؟ الجواب: هذه تدور، وتتكرر كل عام، أو كل ... هذه تسمى أعيادًا.","link":"https://binbaz.org.sa/fatwas/2368/حكم-الاحتفال-بمناسبة-ما-دون-تكرارها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_902.mp3","categories":["أصول الفقه"]},{"id":6786,"question":"ما رأي فضيلتكم فيما يفعله أكثر الناس من تقليد الآخرين، فإذا نصح قال: يفعله الناس؟","title":"خطورة التقليد الأعمى","answer":"الجواب: أما التقليد للناس هذا غلط، الله ذم المشركين، وعابهم بقوله: إنهم كانوا يقولون للأنبياء: إِنَّا وَجَدْنَا آبَاءَنَا عَلَى أُمَّةٍ وَإِنَّا عَلَى آثَارِهِمْ مُقْتَدُونَ [الزخرف:23] ذمهم الله على هذا، هذا من عمل المشركين والجهلة. فالواجب على المسلم: أن يسأل أهل الذكر الله .. فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ [النحل:43] ما يقلد الدهماء، والعامة .. بل يسأل أهل العلم إذا كان ما عنده علم، وإن كان يستطيع العلم؛ يقرأ القرآن، ويتدبر كلام ربه، ويقرأ السنة، ويحفظ ما تيسر منها؛ حتى يعلم الحق، وإذا كان لا يستطيع نظر أهل العلم، وسأل عن أهل العلم في أي بلد، واستفتاهم عما قاله الله ورسوله، دلوني على شرع الله، دلوني بما قاله الله، ورسوله في هذا الأمر حتى أعمل بشرع الله، وبدين الله، لا يقلد الناس، ويمشي مع الناس في الحق، والباطل، لا، بل لا يمشي مع الناس إلا بالحق بس، لا في الباطل.","link":"https://binbaz.org.sa/fatwas/2643/خطورة-التقليد-الاعمى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1139.mp3","categories":["أصول الفقه"]},{"id":6830,"question":"كثيرًا ما يحدث اختلاف في الفتوى بين عالمين في مكان واحد، ونضرب لذلك مثلًا: وجود عالمين يفتيان في المسجد الحرام، أو المسجد النبوي، فإلى أي الرأيين يأخذ المستفتي؟","title":"موقف المستفتين من اختلاف المفتين","answer":"الجواب:\nهذا يا أخي ليس ببدع، هذا موجود في عهد الصحابة -رضي الله عنهم وأرضاهم- موجود في مسجد المدينة، وفي المدينة المنورة يقع الخلاف في الفتوى في عهد الصحابة -رضي الله عنهم وأرضاهم- ثم من بعدهم ليس بمستنكر، وليس ببدع، ولكن الواجب على أهل العلم أن يجتهدوا في توحيد الفتوى مهما أمكن، وأن يتذاكروا في توحيد الفتوى، والتقارب فيما بينهم مهما أمكن.   فإن لم يتيسر ذلك؛ وجب أن يفتي كل واحد بما ظهر له، وبما اطمأن إليه، والمستفتي يتحرى كما تقدم من هو أقرب إلى الحق، من هو أتقى لله، من هو أورع، يتحرى في ذلك، وإذا كان عنده بعض البصيرة؛ تأمل في أدلة الفتوى حتى يطمئن قلبه.","link":"https://binbaz.org.sa/fatwas/2721/موقف-المستفتين-من-اختلاف-المفتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1221.mp3","categories":["أصول الفقه"]},{"id":6833,"question":"قاعدة: وهي أن الفتوى تختلف باختلاف الزمان، والمكان، وربما يستفتي مستفت عن أمر واحد، ولكن تختلف الفتوى لاختلاف حال المستفتين؟","title":"معنى قاعدة: الفتوى تختلف باختلاف الزمان والمكان","answer":"الجواب: مثل ما تقدم، تختلف بحسب أحوال البلد، وظروفها، واصطلاحاتها، وأعرافها، حكم الله واحد، حكم الله واحد لا يتغير الحكم، لا يكون الشيء محرمًا في زمان، ومباحًا في زمان، لا، الحكم واحد، المحرم محرم، والمباح مباح، والواجب واجب، والسنة سنة، والمكروه مكروه، لكن يتغير ظروف الفتوى، وما ينبغي أن تطبق عليه.  فقد يكون اصطلاح قوم غير اصطلاح الآخرين، فيظن اصطلاحهم مثل اصطلاح الآخرين الذين في مصر، أو في الشام، وهو في بلد أخرى ليست أعرافهم، ولا اصطلاحاتهم في كلماتهم مثل أولئك، فليس عرف أهل الرياض مثلًا، أو أهل بيشة، أو أهل أبها مثل عرف أهل مصر، وأهل الشام في مسائل متعددة، فقد يخطؤون في فهم الكلام؛ فيظن أن مراد هؤلاء هو مراد هؤلاء، وليس الأمر كذلك، فيخطئ من جهة عدم فهم المراد، وعدم معرفة قصد هؤلاء، وقصد هؤلاء، فلا ينطبق الحكم على الوجه الشرعي. فالبصيرة في أحوال الناس، وأعرافهم، واصطلاحاتهم، وما يريدون بكلامهم أمر لا بد منه في حق المفتي كما تقدم، ومثل إنكار المنكر، إنكار المنكر واجب، والأمر بالمعروف واجب، لكن تختلف الأحوال في إنكار المنكر بالنسبة إلى ما يترتب عليه، فقد يكون في بعض الأحيان، أو بالنسبة إلى بعض الناس إذا أنكرت عليه المنكر؛ قد يترتب عليه منكر أكبر، وشر أعظم، فحينئذ تترك إنكاره، لا لأنه غير منكر، بل هو منكر، لكن تترك إنكاره لما قد يترتب عليه مما هو أنكر، وأشد، وقد يترتب على إنكار المنكر منكر مثله؛ فيحار الآمر، والناهي، هل ينكره، أو لا ينكره؟! لأنه يترتب عليه مثله، فينظر، ويتأمل كيف ينكر المنكر هذا. فالحاصل: أن الأشياء قد يترتب عليها أمور لا لأن إنكار المنكر ليس بواجب، بل هو واجب، لكن قد يتوقف عن إنكاره لما يترتب عليه من شر أكبر، أو شر مماثل، ومما يقرب هذا ما جرى للنبي ﷺ وإن كان غير منكر، لكن مما يقرب هذا المعنى، النبي ﷺ قال لعائشة -رضي الله عنها-: لولا أن قومك حديثو عهد بكفر؛ لنقضت الكعبة، وجعلتها على قواعد إبراهيم، وجعلت لها بابين. فترك نقضها، وتنفيذ ما قال -عليه الصلاة والسلام- خوفًا من أن تنكر قلوب الناس ذلك، فترك هذا الخير، وهذه المصلحة؛ خوفًا من شر أكبر، يربو على هذه المصلحة، وهذا يقع كثيرًا في مسائل متعددة.","link":"https://binbaz.org.sa/fatwas/2722/معنى-قاعدة-الفتوى-تختلف-باختلاف-الزمان-والمكان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1222.mp3","categories":["أصول الفقه"]},{"id":6834,"question":"بعض المستفتين يسأل بعض العلماء، وحينما لا تكون الإجابة موافقة لهواهم يقومون بتتبع العلماء؛ حتى يحصلوا على الإجابة التي يريدون،  ما هي الأسباب المانعة من قبول الحق، وما هو السبيل للقضاء على مثل هذه الأسباب؟","title":"وجوب تحري المستفتي الحق","answer":"الجواب: المستفتي قد يطمئن قلبه للفتوى، وقد لا يطمئن، وقد يكون المفتي أهلًا لأن يطمئن إليه لما علم عنه من الاستقامة، وتحري الحق، والسير على المنهج القويم، وقد يكون بحالة لا يطمئن إليه. فإذا كان المستفتي لم يطمئن إلى الفتوى، ولم يظهر له وجهها؛ فإنه لا بأس أن يسأل، ويتحرى أهل العلم، ويجتهد في طلب الحق، لا من أجل هواه، والرغبة في موافقة هواه، لا، ولكن الواجب عليه أن يتحرى الحق، وأن يسأل حتى يطمئن قلبه إلى أن هذا هو الصواب، لا إلى أنه وافق هواه -والله المستعان-.","link":"https://binbaz.org.sa/fatwas/2717/وجوب-تحري-المستفتي-الحق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1216.mp3","categories":["أصول الفقه"]},{"id":6836,"question":"كثير من الشباب -وبالأخص بعض أئمة المساجد- عندما يتعرض لسؤال من أحد مأموميه يجيب، أو يفتي في ذلك، ويدعي بأنه سمع مثل هذا من أحد المشايخ الذين يوثق فيهم، مع العلم أنه لم يبحث عن إجابة لهذه الفتوى في الكتب، وتحري الدقة؟","title":"حكم نقل الفتوى عن أهل العلم","answer":"الجواب: إذا نقل الإنسان عن آخر ذكر العلماء أنه لا بأس، إذا نقل، وكان قد ضبط الكلام إذا قال: أنا سمعت فلانًا يقول، أفتى فلان بهذا الشيء، بأن سأله إنسان إذا شك في الصلاة، هل صلى ثنتين، أم ثلاثا؟ وكان ليس عنده علم الحديث الشريف، ولكن قال: إني سمعت العالم الفلاني يقول: إنه يبني على اليقين إذا شك، هل صلى ثلاثًا، أم أربعًا؟ يجعلها ثلاثًا، وإذا شك هل صلى ثلاثًا، أم ثنتين؛ يجعلها ثنتين، إذا نسبه إلى قائله، فالذي أخبر بهذا مخير إن شاء أخذ بذلك، إذا كان المخبر ثقة، وإن شاء ذهب إلى العالم الذي نقل عنه هذا، وسأله. المقصود: أن كون الإمام في المسجد، أو غيره من الثقات ينقل فتوى لا حرج في هذا، النبي ﷺ قال: فليبلغ الشاهد الغائب هذا معنى فليبلغ الشاهد الغائب، إذا بلغ إنسان آخر، وقال: سمعت فلانًا يقول كذا، وكذا، فأنت حينئذ إذا كنت تثق بهذا الرجل، وأنه ثقة، أنت مخير في الأخذ بهذا، أو مراجعة صاحب الأصل؛ حتى تتأكد من صحة الفتوى.","link":"https://binbaz.org.sa/fatwas/2723/حكم-نقل-الفتوى-عن-اهل-العلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1223.mp3","categories":["أصول الفقه"]},{"id":6837,"question":"أرجو إفادتي، سمعت أنه لا يجوز لأحد أن يفتي إلا إذا حفظ أربعمائة ألف حديث مع القرآن، فما حكم الشخص الذي أفتى بمسألة يعرفها، وتأكد منها، أو لم يتأكد ؟","title":"أهلية المفتي","answer":"الجواب: القول بأن المفتي لا بد يحفظ كذا، ويحفظ كذا، ليس عليه دليل، وإنما قاله بعض أهل العلم عن اجتهاد منهم -رحمة الله عليهم-.  والصواب: أنه لا يتعين في المفتي أن يكون يحفظ كذا مائة ألف، أو أربعمائة ألف، أو أقل، أو أكثر، أو أنه يحفظ القرآن، كل هذا ليس بشرط، وإنما الشرط أن تكون لديه معلومات كافية لاستنباط الأحكام، ومعرفة الصواب، وإن كان بالمطالعة، والقوة، وإن كان لا يحفظ القرآن كله، أو لا يحفظ إلا القليل من الحديث، لكن ما دامت عنده القدرة على البحث، والمراجعة، والاستفادة، والمطالعة؛ فهو أهل لأن يفتي بعد العناية، وبعد المراجعة للقرآن الكريم، وكلام أهل العلم فيما يتعلق بتفسير القرآن، ثم ما يتعلق بالسنة. فالحاصل: أنه ليس هناك شرط في أن يكون المفتي يحفظ كذا من الأحاديث، أو أنه يحفظ القرآن، ليس هذا بشرط على الصواب، وإنما الشرط أن يكون أهلًا للفتوى، إما بحفظه للأدلة، وإما بما أعطاه الله من القوة التي يستطيع بها المراجعة للكتاب، والسنة، ومعرفة الحق بالدليل.","link":"https://binbaz.org.sa/fatwas/2718/اهلية-المفتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1217.mp3","categories":["أصول الفقه"]},{"id":6840,"question":"هناك آراء، واجتهادات على المذاهب الأربعة، ولما كانت المملكة تعمل على مذهب الإمام أحمد، فلو أن مجتهدًا أفتى في قضية من القضايا بأحد المذاهب الأخرى، كمذهب الأحناف، أو غيره إذا ترجح له، فهل له مثل هذا؟","title":"مسائل الخلاف لا يتعين فيها مذهب معين","answer":"الجواب: لا حرج في ذلك، ليس مذهب أحمد متعين على الناس، لا في الرياض، ولا في المملكة، ولا في غيرها، مذهب أحمد -رحمه الله- مثل بقية المذاهب، ما كان فيه من الصواب أخذ به، وما كان فيه من الخطأ؛ وجب تركه، وهكذا مذهب الشافعي، ومالك، وأبي حنيفة، والظاهرية، والثوري، وابن راهوية، وغيرهم، فالمعول على الدليل عند الخلاف. أما في مسائل الإجماع فلا كلام لأحد في مسائل الإجماع، يتعين القول بما دل عليه الإجماع، أما في مسائل اختلف فيها العلماء؛ فالواجب على العالم أن يختار ما يقوم عليه الدليل، سواء كان وافق على مذهب أحمد، أو مذهب مالك، أو الشافعي، أو أبي حنيفة، أو غيرهم. المقصود: هو الأخذ بما، وافق الدليل، وقامت عليه الحجة، وقد أخذ أئمة الدعوة، وهم الحنابلة، الشيخ محمد بن عبدالوهاب، وجماعة، وأتباعه أخذوا بمسائل تخالف مذهب أحمد لما ظهر لهم أن الراجح قول غيره في ذلك. مثل: إسقاط الإخوة بالجد، المشهور عند الحنابلة أنهم لا يسقطون بالجد، بل يشاركونه، والصواب: أنهم يسقطون، وهو مذهب أبي حنيفة، ورواية عن أحمد -رحمه الله- وهو الذي أفتى به الشيخ محمد -رحمه الله- وجماعة من أتباعه، وهو مذهب الصديق -رضي الله عنه وأرضاه- وجماعة من الصحابة بضعة عشر صحابيًا، كلهم يقولون بإسقاط الإخوة بالجد، وأنه أب. وهناك مسائل أخرى ذهب أئمة الدعوة، وغيرهم من الحنابلة إلى مذاهب أخرى إلى مذهب مالك فيها، وإلى أبي حنيفة، أو إلى الشافعي، أو إلى غيرهم؛ لظهور الدليل. فالمقصود: أن مسائل الخلاف لا يتعين فيها مذهب معين، بل الواجب فيها الأخذ بما قام عليه الدليل، مع قطع النظر عن كونه يوافق مذهب فلان، أو فلان.","link":"https://binbaz.org.sa/fatwas/2724/مساىل-الخلاف-لا-يتعين-فيها-مذهب-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1224.mp3","categories":["أصول الفقه"]},{"id":6841,"question":"ما موقف المفتي في مسائل الخلاف، خاصة عند تكافؤ الأدلة، وهل يفتي بما يراه الراجح من هذه المسائل؟","title":"كيفية الإفتاء في مسائل الخلاف","answer":"الجواب: نعم موقف المفتي: أن ينظر في مسائل الخلاف، ويتحرى ما هو الأرجح بالدليل، ثم يفتي نفسه، ويفتي غيره بعدما يطمئن إلى أن ما ظهر له هو الأرجح، سواء كانت المسألة فيها قولان، أو ثلاثة، أو أكثر، ينظر في الأدلة، ويتأمل ما قاله هؤلاء، وما قاله هؤلاء، وما قاله هؤلاء، وما احتج به هؤلاء، وما احتج به هؤلاء.  ثم يعمل بالقواعد المتبعة في ذلك من الجمع بين الأحاديث عند إمكان الجمع، من استعمال النسخ عند توافر شروط النسخ، من الترجيح عند تعذر النسخ، والجمع، يعمل ما قرره أهل العلم، وبينوه من وجوه الاستدلال، واعتماد ما هو الراجح عند الخلاف، هذا يحتاج إلى بصيرة من العالم، ومعرفة بأقوال أهل العلم فيما يتعلق بالخلاف.  وسبق في الكلمة أن قلت: ما قاله أهل العلم: إن الموقف لطالب العلم في مسائل الخلاف تتحرى في أربع مراتب: المرتبة الأولى: أن ينظر في الجمع، وهو المقدم، فإذا كان أمكن الجمع بين الحديثين، أو الأحاديث، أو الآيات، والأحاديث؛ وجب.  فإن لم يمكن الجمع، ولم توافر شروط الجمع، ولم يتيسر؛ انتقل إلى المرتبة الثانية: وهي مرتبة النسخ، فإذا توافرت شروط النسخ، وعلم المتقدم، والمتأخر، نسخ المتقدم من المتأخر، وصار الحكم للمتأخر، مثل ما في القبلة، كانت القبلة أولًا المسجد الأقصى، ثم نسخ بالكعبة المشرفة.  فإن لم يتيسر العلم بالنسخ، ولم تتوافر شروطه؛ انتقل إلى المرتبة الثالثة: وهي الترجيح، فينظر في أدلة الفريقين، أو الفرق، فما كان أرجح؛ أخذ به، فإذا كان بعضهم عنده دليل ضعيف، والآخر عنده دليل قوي صحيح، أو أحد القولين، أو الأقوال أدلتها مرجوحة، والآخر أدلته راجحة؛ أخذ بالأرجح، وقد بين العلماء ذلك، فإذا كان بيد فريق حديث واحد، وبيد الفريق الثاني أكثر من حديث، كلها صحيحة، فإن من معهم الأحاديث الكثيرة أرجح، ويعتبر الحديث الآخر الذي بيد الفريق الثاني شاذ، فإن الأخذ بالأرجح هو الواجب عند تعذر النسخ، والجمع. قال الحافظ ابن حجر -رحمه الله- في النخبة: \"فإن خولف بأرجح، فالراجح المحفوظ، ومقابله الشاذ\". فإن لم يتيسر الترجيح، ولا الجمع، ولا النسخ، انتقل إلى المرتبة الرابعة: وهي التوقف، وعدم البت في هذه المسائل المختلف فيها؛ حتى يتضح له الحكم، وليس معناه أنه يسكت، لا، يعتني، يراجع الأدلة، يبحث، يتأمل، يشاور أهل العلم الذين عنده في قربه، ويتمكن من مراجعته بالكتابة، أو بالبرقية، أو بالهاتف، أو بأي طريق، يشاور أهل العلم، ويبحث معهم لعله يستفيد، فيترجح عنده أحد الأقوال، أو أحد القولين عن الآخر، هكذا أهل العلم.","link":"https://binbaz.org.sa/fatwas/2719/كيفية-الافتاء-في-مساىل-الخلاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1218.mp3","categories":["أصول الفقه"]},{"id":6844,"question":"لا شك أن تصور القضية، والمسألة التي يسأل عنها المستفتي أمر ضروري، فالحكم على الشيء فرع عن تصوره، فما رأي سماحتكم فيمن يقوم بالفتوى في أمر لا يملك التصور الكافي عنه؟","title":"خطر الفتوى دون تصور السؤال تصوراً كافياً","answer":"الجواب: ما يجوز هذا، هذا لا يجوز، المفتي يجب عليه أن يتصور السؤال، ويعرف ما يترتب على السؤال، ثم بعد الطمأنينة إذا فهم السؤال، ولا مانع من أن يعيد السؤال، ويقول للسائل: أعد، حتى يتحقق ما أراده السائل، وحتى يفهم مراد السائل، ولا يعجل في الفتوى؛ حتى يطمئن إلى أنه فهم السؤال، ثم يفتي بعد ذلك.  أما الإقدام على الفتوى من دون نظر، ولا تأمل هذا غلط لا يجوز، بل على المفتي أن يتأمل، ويتدبر حتى يطمئن إلى أنه فهم السؤال.","link":"https://binbaz.org.sa/fatwas/2725/خطر-الفتوى-دون-تصور-السوال-تصورا-كافيا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1225.mp3","categories":["أصول الفقه"]},{"id":6845,"question":"ما موقف المستفتي من اختلاف المفتي،ن وتعارض أقوالهم في بعض الحالات؟","title":"موقف المستفتي عند اختلاف أقوال المفتين","answer":"الجواب: مثل ما تقدم عليه أن يتقي الله، وعليه أن يتحرى من هو أقرب إلى العلم، والفضل، والتقوى، فليس المفتون على حد سواء.  إذا تأمل أحوالهم المستفتي، ونظر في أحوالهم، وما ظهر له من تقواهم، وعلمهم، وما يقوله أهل العلم عنهم، وما يقوله أهل التقوى عنهم، يتحرى، ويأخذ بما هو أقرب إلى الخير، وما هو أقرب إلى طمأنينة قلبه، وانشراح صدره.  والغالب أنه متى اتقى الله، وسأله التوفيق، وأن يشرح صدره للحق، في الغالب أنه يوفق، ويهتدي لما هو الأرجح.","link":"https://binbaz.org.sa/fatwas/2720/موقف-المستفتي-عند-اختلاف-اقوال-المفتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1219.mp3","categories":["أصول الفقه"]},{"id":6846,"question":"قاعدة: وهي أن الفتوى تختلف باختلاف الزمان، والمكان، وربما يستفتي مستفت عن أمر واحد، ولكن تختلف الفتوى لاختلاف حال المستفتين؟","title":"معنى قاعدة: الفتوى تختلف باختلاف الزمان والمكان","answer":"الجواب: مثل ما تقدم، تختلف بحسب أحوال البلد، وظروفها، واصطلاحاتها، وأعرافها، حكم الله واحد، حكم الله واحد لا يتغير الحكم، لا يكون الشيء محرمًا في زمان، ومباحًا في زمان، لا، الحكم واحد، المحرم محرم، والمباح مباح، والواجب واجب، والسنة سنة، والمكروه مكروه، لكن يتغير ظروف الفتوى، وما ينبغي أن تطبق عليه.  فقد يكون اصطلاح قوم غير اصطلاح الآخرين، فيظن اصطلاحهم مثل اصطلاح الآخرين الذين في مصر، أو في الشام، وهو في بلد أخرى ليست أعرافهم، ولا اصطلاحاتهم في كلماتهم مثل أولئك، فليس عرف أهل الرياض مثلًا، أو أهل بيشة، أو أهل أبها مثل عرف أهل مصر، وأهل الشام في مسائل متعددة، فقد يخطؤون في فهم الكلام؛ فيظن أن مراد هؤلاء هو مراد هؤلاء، وليس الأمر كذلك، فيخطئ من جهة عدم فهم المراد، وعدم معرفة قصد هؤلاء، وقصد هؤلاء، فلا ينطبق الحكم على الوجه الشرعي. فالبصيرة في أحوال الناس، وأعرافهم، واصطلاحاتهم، وما يريدون بكلامهم أمر لا بد منه في حق المفتي كما تقدم، ومثل إنكار المنكر، إنكار المنكر واجب، والأمر بالمعروف واجب، لكن تختلف الأحوال في إنكار المنكر بالنسبة إلى ما يترتب عليه، فقد يكون في بعض الأحيان، أو بالنسبة إلى بعض الناس إذا أنكرت عليه المنكر؛ قد يترتب عليه منكر أكبر، وشر أعظم، فحينئذ تترك إنكاره، لا لأنه غير منكر، بل هو منكر، لكن تترك إنكاره لما قد يترتب عليه مما هو أنكر، وأشد، وقد يترتب على إنكار المنكر منكر مثله؛ فيحار الآمر، والناهي، هل ينكره، أو لا ينكره؟! لأنه يترتب عليه مثله، فينظر، ويتأمل كيف ينكر المنكر هذا. فالحاصل: أن الأشياء قد يترتب عليها أمور لا لأن إنكار المنكر ليس بواجب، بل هو واجب، لكن قد يتوقف عن إنكاره لما يترتب عليه من شر أكبر، أو شر مماثل، ومما يقرب هذا ما جرى للنبي ﷺ وإن كان غير منكر، لكن مما يقرب هذا المعنى، النبي ﷺ قال لعائشة -رضي الله عنها-: لولا أن قومك حديثو عهد بكفر؛ لنقضت الكعبة، وجعلتها على قواعد إبراهيم، وجعلت لها بابين. فترك نقضها، وتنفيذ ما قال -عليه الصلاة والسلام- خوفًا من أن تنكر قلوب الناس ذلك، فترك هذا الخير، وهذه المصلحة؛ خوفًا من شر أكبر، يربو على هذه المصلحة، وهذا يقع كثيرًا في مسائل متعددة.","link":"https://binbaz.org.sa/fatwas/2722/معنى-قاعدة-الفتوى-تختلف-باختلاف-الزمان-والمكان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1222.mp3","categories":["أصول الفقه"]},{"id":6847,"question":"بعض المستفتين يسأل بعض العلماء، وحينما لا تكون الإجابة موافقة لهواهم يقومون بتتبع العلماء؛ حتى يحصلوا على الإجابة التي يريدون،  ما هي الأسباب المانعة من قبول الحق، وما هو السبيل للقضاء على مثل هذه الأسباب؟","title":"وجوب تحري المستفتي الحق","answer":"الجواب: المستفتي قد يطمئن قلبه للفتوى، وقد لا يطمئن، وقد يكون المفتي أهلًا لأن يطمئن إليه لما علم عنه من الاستقامة، وتحري الحق، والسير على المنهج القويم، وقد يكون بحالة لا يطمئن إليه. فإذا كان المستفتي لم يطمئن إلى الفتوى، ولم يظهر له وجهها؛ فإنه لا بأس أن يسأل، ويتحرى أهل العلم، ويجتهد في طلب الحق، لا من أجل هواه، والرغبة في موافقة هواه، لا، ولكن الواجب عليه أن يتحرى الحق، وأن يسأل حتى يطمئن قلبه إلى أن هذا هو الصواب، لا إلى أنه وافق هواه -والله المستعان-.","link":"https://binbaz.org.sa/fatwas/2717/وجوب-تحري-المستفتي-الحق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1216.mp3","categories":["أصول الفقه"]},{"id":6848,"question":"إذا برع عالم في أحد جوانب العلم، ولم يتمكن من بقية العلوم، فهل يجوز له الإفتاء فيما علم؟","title":"جواز الإفتاء في ما تخصص فيه فقط","answer":"الجواب: نعم، إذا كان العالم بصيرًا بالفرائض، والمواريث له أن يفتي فيها فقط، وليس له أن يفتي في المسائل الأخرى التي هو يجهلها، فإن العلم يتجزأ، فللعالم أن يفتي فيما علم، دون ما لم يعلم.","link":"https://binbaz.org.sa/fatwas/2732/جواز-الافتاء-في-ما-تخصص-فيه-فقط","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1232.mp3","categories":["أصول الفقه"]},{"id":6855,"question":"ما حكم الفتوى بالتقليد؟ وهل تصح الفتوى بدون استدلال؟","title":"حكم التقليد في الفتوى","answer":"الجواب: لا يجوز ذلك، بل لا بد من الاستدلال، والنظر في الأدلة، اللهم إلا في وقت لا يوجد فيه مجتهد، فقد ذكر العلماء جواز التقليد للضرورة إذا كان في مكان، أو في قرية لا يتمكنوا فيه من العلماء، ولا يوجد فيه عالم إلا عالم بمذهب فلان، مذهب أبي حنيفة، مذهب مالك، مذهب أحمد، فيفتيهم على ما فهم، وليس عنده قدرة على معرفة الدليل، هذا قد يجوز فيما قاله بعض أهل العلم، ولكن مهما أمكن له أن ينظر، ومهما أمكنه أن يتحرى الحق بالدليل، فهذا هو الواجب عليه. المقصود: أن الأصل عدم جواز التقليد. هذا هو الأصل، عدم جواز التقليد لطالب العلم، بل يتحرى، وينظر. أما العامي فيكفيه أن يسأل أهل العلم، ويلزمه أن يأخذ بما أفتوه به؛ لأنه ليس من أهل النظر، وإنما يسأل أهل العلم كما قال الله : فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لَا تَعْلَمُونَ [النحل:43] فعليه أن يسأل، ويتحرى، ويلتزم. أما طالب العلم فالواجب عليه أن يتحرى الأدلة، وألا يرضى لنفسه بالتقليد مهما أمكن.","link":"https://binbaz.org.sa/fatwas/2734/حكم-التقليد-في-الفتوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1234.mp3","categories":["أصول الفقه"]},{"id":6856,"question":"المجتهد في هذا العصر الحاضر قد يصل في بحث بعض المسائل بدون وصول إلى النصوص، وكذا فيقول: أنه قد يفتي في أمور جدت بغير أن يجمع النصوص، فهل يسوغ له أن يفتي بدون أن يجمع أطراف النصوص؟","title":"على المفتي جمع أطراف النصوص للمسألة","answer":"الجواب: مثلما تقدم، الواجب على المفتي ألا يعجل، وأن يجمع النصوص فيما فيه خلاف، واحتمال حتى يتضح له الحق.  وهكذا إذا كانت الفتوى في أمور مختلفة، وفي أمور متشعبة، وقد يترتب عليها خطر، لا يعجل حتى يطمئن إلى ما يفتي فيه، وحتى يعلم أطرافه، وحتى يعرف ما يترتب على هذه الفتوى، هل يترتب عليها أنكر منها، وأخطر منها؟ لا بد يكون عنده بصيرة في هذا الشيء؛ حتى لا يقدم إلا على علم، وبصيرة، وإذا كان يخشى أن يترتب على إنكاره ما هو أنكر، أو على فتواه ما هو مضر؛ فلا يعجل، يتأنى، وينظر حتى تكون الفتوى في محلها.","link":"https://binbaz.org.sa/fatwas/2729/على-المفتي-جمع-اطراف-النصوص-للمسالة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1229.mp3","categories":["أصول الفقه"]},{"id":6860,"question":"الإنسان معرض للفتوى من قبل الناس، وخاصة العوام في أي وقت، وذلك في أمور ظاهرة واضحة، كأحكام الصلاة، فهل للإنسان أن يفتي في مثل هذه الأمور؟","title":"حكم إفتاء العامي في الأمور المعلومة من الدين بالضرورة","answer":"الجواب: نعم، إذا كان الأمر، واضحًا؛ فلا مانع، إذا سألك سائل يقول: الزنا حرام، وإلا حلال؟ تقول له: الزنا حرام منكر بإجماع المسلمين، هذا ما يختلف فيه أحد.  أو يسأل عن الخمر، أو عن المسكرات، أكل الربا حرام بإجماع المسلمين، يسأل عن الغيبة، والنميمة، يسأل عن قطيعة الرحم، عن عقوق الوالدين، الأشياء الواضحة المعروفة من الدين بالضرورة، كل المسلمين يتعاونون في منعها، والقضاء عليها، كل المسلمين عالمهم، وعامتهم. لكن مسائل تحتاج إلى علم، وتحتاج إلى بصيرة، لا يتكلف فيها العامي، ولا يفتي فيها إلا بعد سؤال أهل العلم، لكن أمور ظاهرة معروفة للمسلمين عامتهم، وخاصتهم، هذا لا يجوز للإنسان أن يتساهل في هذا الشيء، أو يتوقف، بل يجب أن يقول ما يعلم مما هو معروف، وظاهر، ومجمع عليه بين المسلمين، ليس فيه نزاع، ولا شبهة.  فلو قال له قائل: ما تقول في الخمر؟ يتوقف؟ لا ما يتوقف، الخمر حرام، ومنكر بإجماع المسلمين، وهكذا إذا سأل عن بر الوالدين، واجب أو ما هو واجب؟ العقوق حرام، أو ما هو حرام؟ كل هذه أمور واضحة.","link":"https://binbaz.org.sa/fatwas/2726/حكم-افتاء-العامي-في-الامور-المعلومة-من-الدين-بالضرورة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1226.mp3","categories":["أصول الفقه"]},{"id":6863,"question":"هل يتحتم أخذ إذن الإمام للتصدر للفتوى؟","title":"حكم أخذ الإذن من ولي الأمر للتصدر للفتوى","answer":"الجواب: ما يتحتم لا، لكن لولي الأمر أن يمنع من يعرف بالتساهل، أو بالجهل، ولي الأمر يمنعه، ويأخذ على يديه، ويتوعده، وله أن يسجنه، وله أن يؤدبه إذا لم يمتثل.  أما إذا كان أهلًا للفتوى؛ فلا يمنع.","link":"https://binbaz.org.sa/fatwas/2730/حكم-اخذ-الاذن-من-ولي-الامر-للتصدر-للفتوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1230.mp3","categories":["أصول الفقه"]},{"id":6865,"question":"إن بعض المفتين يقول: لا ينبغي فعل كذا الشيخ، أو ينبغي فعل كذا، ما معنى هذه العبارة؟","title":"معنى قول المفتي: ينبغي كذا أو لا ينبغي كذا","answer":"الجواب: هذه العبارة قد يتساهل فيها المفتي، يقول: لا ينبغي، ومراده أنه يكره، أو لا يحسن، وقد يريد بها التحريم، لا ينبغي بمعنى لا يجوز، ولكن في الغالب في عرف الناس اليوم  أنه قد يتساهل في ذلك، فيقول: لا ينبغي للشيء المكروه، يعني لا يحسن فعل هذا الشيء، أو ينبغي فعل هذا الشيء ليحسن فعله، ولا يرتقي إلى الوجوب، والتحريم.  هذا فيما يظهر من تصرف الكثير من الناس من أهل العلم في زماننا، وأنا منهم، قد أقول: لا ينبغي كذا في بعض الأحيان، أو ينبغي كذا، وليس قصدي في قولي لا ينبغي أنه محرم، وليس قصدي بقولي ينبغي أنه واجب، ولكن قد يقع على لساني هذا في بعض الأحيان، من باب أن هذا تركه أولى، أو لا يحسن فعله، وينبغي كذا يعني يحسن فعله، والأولى فعله. وهي ألفاظ ينبغي فيها التحرز، وينبغي فيها التوقي؛ لأن شأن لا ينبغي عظيم في كلام الله  وكلام رسوله -عليه الصلاة والسلام- وَمَا يَنْبَغِي لِلرَّحْمَنِ أَنْ يَتَّخِذَ وَلَدًا [مريم:92] فما ينبغي لها شأن في كلام الله، ولكن في عرف الناس الآن قد يتساهلون فيها. وقد يقع فيها إطلاق الكلمات هذه على الشيء المكروهة، لا ينبغي، والشيء المستحسن والذي ينبغي فعله، يعني يحسن فعله، والأولى فعله. فالتحرز في هاتين اللفظتين مهم جدًا، ولا ينبغي أن يؤخذ معناهما من كلام الناس على المعنى الذي قاله الله، ورسوله، بل لا بد من التثبت في ذلك، والتبصر في ذلك ممن أطلقهما، وفق الله الجميع.","link":"https://binbaz.org.sa/fatwas/2736/معنى-قول-المفتي-ينبغي-كذا-او-لا-ينبغي-كذا","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1236.mp3","categories":["أصول الفقه"]},{"id":6866,"question":"هل الفتوى ملزمة للمستفتي، أم له أن يسأل مفتيًا آخر؟","title":"هل الأخذ بفتوى المفتي ملزمة؟","answer":"الجواب: ليست ملزمة، الحاكم هو الملزم، أما المفتي لا يلزم، للمستفتي أن ينظر، ويتأمل، ويستفتي غير من استفتاه أولًا إذا لم يطمئن.","link":"https://binbaz.org.sa/fatwas/2731/هل-الاخذ-بفتوى-المفتي-ملزمة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1231.mp3","categories":["أصول الفقه"]},{"id":6872,"question":"قرأت في كتاب علم أصول الفقه للأستاذ عبدالوهاب خلاف: أن الإنسان يأخذ المطلق على أنه مطلق، والمقيد على أنه مقيد، فمثلًا: فتحرير رقبة؛ تكون أي رقبة، وإن لم تكن مسلمة، فما رأي سماحتكم؟","title":"الإطلاق والتقييد في نصوص الشرع","answer":"الجواب: هذا محل خلاف، والذي عليه الجمهور أن المطلق يقيد بالمقيد، هذه القاعدة الكتاب .. والسنة المطهرة فيهما نصوص مطلقة، وفيهما نصوص مقيدة، والقاعدة عند العلماء في مصطلح الحديث والأصول على أن القول المعتمد: أن المطلق يقيد بالمقيد، فالآية التي فيها إعتاق الرقبة مقيدة بالآية التي فيها الإيمان.  وهكذا في النصوص الأخرى العامة تقيد بالخاصة، ولا تتم الأحكام، وتستقيم الأمور إلا على هذا، فالنصوص يفسر بعضها بعضًا، ويقيد بعضها بعضًا، ويدل بعضها على بعض، فما أطلق في موضع قد يقيد في موضع آخر، وما عم في موضع قد يخص في موضع آخر، فهذا هو الصواب حمل المطلق على المقيد، والعام على الخاص كما في قوله -جل وعلا-: يُوصِيكُمُ اللَّهُ فِي أَوْلَادِكُمْ [النساء:11].  جاءت النصوص على أن المراد بالكافر لا يرث، والقاتل لا يرث، والرقيق لا يرث، هذا من المطلق، والمقيد، أو من العام المخصوص، وهذا كثير مثل قوله ﷺ: يقطع صلاة المرء: المرأة، والحمار، والكلب جاء في اللفظ الآخر: والكلب الأسود فقيد الكلب الأسود دون غيره، وهكذا نصوص كثيرة.","link":"https://binbaz.org.sa/fatwas/2754/الاطلاق-والتقييد-في-نصوص-الشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk5_1246.mp3","categories":["أصول الفقه"]},{"id":6955,"question":"هل تعدد الزوجات مباح فقط، أو هو سنة وردت عن الرسول ﷺ؟","title":"هل تعدد الزوجات مباح فقط أم سنة؟","answer":"الجواب: النص يقتضي أنها سنة، أقل الأحوال أنها سنة: فَانْكِحُوا مَا طَابَ لَكُمْ مِنَ النِّسَاءِ [النساء:3] أمر، لكن بشرط العدل، والاستقامة. وأما إذا خاف ألا يعدل لقلة ماله، أو لشيء يعرفه من نفسه من الضعف؛ فلا يتزوج إلا واحدة.","link":"https://binbaz.org.sa/fatwas/2885/هل-تعدد-الزوجات-مباح-فقط-ام-سنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1333.mp3","categories":["أصول الفقه","تعدد الزوجات"]},{"id":7027,"question":"في عهد الخليفة المتوكل ألزم الإمام أحمد بن حنبل  بعدم الخروج من بيته حتى للصلاة مع الجماعة، فأطاع الخليفة، فكيف نوفق بين هذه الحادثة من هذا الإمام، وبين حديث: لا طاعة لمخلوق في معصية الخالق؟","title":"حكم من أكره على ترك واجب أو فعل محرم","answer":"الجواب:\n\nالإنسان فيما يتعلق بالطاعة على حالين:\n\nحال يطيعه مختارًا: فإذا قال له: اشرب الخمر؛ شرب الخمر، وإذا قال: سب الدين؛ سب الدين، هذا لا عذر له باختياره.\n\nوالحال الثانية: يكون مكرهًا، يقال له: الزم بيتك، ولا تصل في المسجد، وإلا ضربناك، هذا مكره، معذور، أو قالوا له: قل محمد كاذب وإلا قتلناك، وهددوه، هذا مكره إذا تكلم بالكفر، وقلبه مطمئن بالإيمان، لا شيء عليه، يقول الله سبحانه: مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالْإِيمَانِ [النحل:106] لما قالوا لبلال وألزموه بالكفر، قال له النبي ﷺ: إن عادوا فعد، ولكن أبى بلال، فكان يقول: أحد أحد، لما أكرهه الكفار.\n\nفالحاصل: أن الذي يؤمر من جهة ولاة الأمور بالمعصية له حالان: \n\nالحالة الأولى: يطيعهم ولا يبالي حبًا للدنيا، وإيثارًا لها، فهذا ليس بمعذور، إنما الطاعة بالمعروف، فإذا قال الأمير، أو قالت له زوجته، أو قال له أبوه، أو قال له شيخ قبيلته: اشرب الخمر معنا، وأطاعه، هذا ... المعاصي، أو قالوا له افعل الربا معنا، أو قالوا له مثلً:ا عق والديك، أو قالوا له: اقطع أرحامك، هذا يكون مطيعًا في المعصية.\n\nالحال الثانية: أن يقول له ولي الأمير بشرطته، وبجنوده: الزم بيتك، فإن خرجت؛ ضربناك بالقوة؛ فله عذر أن يلزم بيته، تسقط عنه الجماعة، أو مثلًا: صبوا الخمر في فمه غصبًا، قهرًا عليه، وهددوه إن لم يشرب؛ ضربوه وعذبوه، وهم قادرون، ضربوه لإيقاع ذلك به؛ فهو معذور ..، أو قالوا له مثلًا: إن خرجت من هذا المحل، أو تركت هذا المحل؛ فعلنا بك، إن حججت، أو خرجت للحج، أو خرجت للجهاد؛ فعلنا بك، الزم بيتك، فهذا معذور إذا منعوه بالقوة وهو لا يستطيع دفع ذلك، هذا معذور من باب الإكراه.","link":"https://binbaz.org.sa/fatwas/3016/حكم-من-اكره-على-ترك-واجب-او-فعل-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1423.mp3","categories":["أصول الفقه"]},{"id":7033,"question":"ما هو تأثير المذاهب الأربعة على فرقة المسلمين أو جمع كلمتهم، وهل الإنسان ملزم باتباع مذهب معين؟","title":"حكم التزام المسلم بمذهب فقهي معين","answer":"الجواب:\n\nالمذاهب الأربعة مذاهب علماء، أربعة علماء تفقهوا في الدين وعلموا من اتصل بهم، أبو حنيفة النعمان بن ثابت، ومالك بن أنس الأصبحي، ومحمد بن إدريس الشافعي، وأحمد بن محمد بن حنبل الشيباني هؤلاء علماء اشتهروا فصار لهم فقه وصار لهم علم واسع، ولهم أتباع وأصحاب فاشتهروا وسميت المذاهب الأربعة، ولا يلزم من أحد اتباع واحد معين لا، يلزم المسلمين اتباع الحق، اتباع الرسول ﷺ.\n\nوهؤلاء العلماء الأربعة مثل بقية العلماء كإسحاق بن راهوية وسفيان الثوري والأوزاعي وسفيان بن عيينة وغيرهم من أئمة الهدى، على الجميع -جميع المسلمين- أن يكونوا مثلهم يعني يتبعون الحق ويسألون عن الحق وينظرون في الحق ويتعاونون مع علماء زمانهم في اتباع الحق، وهو اتباع ما دل عليه القرآن أو دلت عليه سنة رسول الله عليه الصلاة والسلام، وليس يلزم زيدًا أو عمرًا أن يكون حنبليا أو مالكيا أو شافعيا أو حنفيا أو ثوريا أو أوزاعيا لا، الواجب اتباع الحق أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [النساء:59]، وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7]\n\nولكن يوجد من أتباع هؤلاء الأربعة ومن غيرهم من يتعصب حتى يسبب الفرقة، فالمتعصبون الذين يقولون لا شيء صحيح إلا ما قاله أبو حنيفة، والآخر يقول لا، الصواب مع مالك، والآخر يقول الصواب مع الشافعي، والآخر يقول الصواب مع ابن حنبل، هذا غلط، هذا لأنه هو الذي يسبب الفرقة والتعصب، أما إذا تعاونوا على الخير ونظروا فيما قاله هؤلاء العلماء واتبعوا الحق من أقوالهم وتركوا المرجوح من أقوالهم، هذا هو طريق الهدى، وهذا هو طريق الجماعة، ما يتعصب الحنفي للحنفي، والمالكي للمالكي، والشافعي للشافعي، والحنبلي للحنبلي، والأوزاعي للأوزاعي، والظاهري للظاهري، لا. \n\nيجب أن يكون الهدف اتباع الرسول ﷺ والسير على منهاجه فيما جاء به من العلم والهدى، ويتعاون المالكي والحنفي والشافعي والحنبلي وغيرهم، يتعاونون على فهم كتاب الله وسنة رسوله ﷺ وعلى اتباع الحق ولا يتعصبون، لا يتعصب هذا لشيخه أو هذا لمذهبه أو هذا لفلان أو فلان لا. \n\nالواجب أن يكون الكتاب والسنة فوق الجميع، وأن تكون نيته صالحة، وأن يكون الهدف والحرص على موافقة الحق الذي جاء به كتاب الله وجاءت به سنة رسوله عليه الصلاة والسلام، سواء كان وافق مذهب الشافعي، أو وافق مذهب أحمد، أو وافق مذهب مالك، أو وافق مذهب الحنفية، وهذا كلام الأئمة العلماء أنفسهم يقولون هذا، الأئمة الأربعة يقولون لا تقلدونا وخذوا من حيث أخذنا. \n\nأحمد يقول ذلك، ومالك يقول ذلك، والشافعي يقول ذلك، وأبو حنيفة يقول ذلك، وغيرهم ينهون عن تقليدهم وينهون عن اتباع ما قالوه بغير دليل وبغير حجة، يأمرون أتباعهم أن ينظروا في الأدلة ويتبعوا الأدلة ويأخذوا بالحق ويقولون: إذا خالف قولنا ما جاء في الكتاب والسنة فدعوا قولنا، اتركوا قولنا، خذوا بكتاب الله وسنة رسوله عليه الصلاة والسلام. \n\nهكذا يقولون رحمة الله عليهم، هم نصحوا للناس ولكن بعض الأتباع من جهلهم تعصبوا لهم بغير حجة وبغير دليل حتى فرقوا دينهم وضروا بالناس.\nالسؤال: لو وحدت المذاهب هذه..؟\nالجواب: ما هو ممكن، هذا مستحيل، هذا من المستحيلات.","link":"https://binbaz.org.sa/fatwas/3013/حكم-التزام-المسلم-بمذهب-فقهي-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1420.mp3","categories":["أصول الفقه"]},{"id":7384,"question":"الشريعة الإسلامية صالحة لكل زمان ومكان، فإذا طبقنا الشريعة في قطر غالبيته مسلمة وتوجد أعداد من الكتابيين واللادينين ما حكم تطبيق الشريعة الإسلامية عليهم؟ وإذا ارتكب الكتابي أو الكتابية جريمة حدية، وتوفر كل الشروط لإقامة الحد عليها، هل يمنع من تطبيقه الحد عليها لاختلاف الدين؟ وما الحكم إذا كان فاعل الجريمة لا ديني، أي كافر؟","title":"حكم تطبيق الشريعة الإسلامية على الكفار في بلاد المسلمين","answer":"الجواب: هذا أمر موضح لأهل العلم، ومبين لأهل العلم، إذا كان في الدولة نصارى، أو يهود، أو ناس آخرون من الكفار؛ فعليهم أن يلتزموا حدود الشريعة، وعلى الدولة أن تنفذ فيهم حكم الله  إذا أدوا الجزية، والتزموا بأحكام الدولة -أحكام الإسلام- فيما بينهم؛ فعلى الدولة أن تحميهم من الظلم، وأن لا تدع أحدًا يظلمهم، وأن تعطيهم حقوق الوطنيين التي تخص أمثالهم، وأن تقيم فيهم أمر الله إذا خالفوا شرع الله، وألا يظهروا دينهم ومنكرهم بين المسلمين، بل يكون في داخل بيوتهم، وداخل محلاتهم حتى لا يظهروا شرهم للمسلمين، ولا دينهم للمسلمين. فالحاصل: أن هذه لها أحكام في الحكم الإسلامي، يجب على ولاة الأمور تطبيق الأحكام الإسلامية التي ذكر العلماء على اليهود، على النصارى في بلادهم، وعلى المجوس في بلادهم، والبوذيين في بلادهم، وغيرهم ممن أجاز الشرع إقرارهم. أما من لم يجز الشرع إقراراهم، فهؤلاء يعاملون بما يقتضيه الشرع، إذا كان الشرع يقتضي إبعادهم؛ يبعدوا، إذا كان يقتضي قتلهم؛ قتلوا، لا بد يحكم فيهم أمر الله -جل وعلا- فيما يلزم من جهتهم، ولا بد من حمايتهم من الظلم، وإعطائهم حقوقهم التي تمت عليها الشروط بينهم وبين ولي الأمر، وإذا كانت الشروط التي بينهم وبين ولي الأمر لم ينفذوا لهم أحكامًا أيضًا، هذه أمور غير مهملة، بل لها أحكام مبينة في عقد الذمة، وأحكام أهل الذمة.","link":"https://binbaz.org.sa/fatwas/3458/حكم-تطبيق-الشريعة-الاسلامية-على-الكفار-في-بلاد-المسلمين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1762.mp3","categories":["أصول الفقه"]},{"id":7905,"question":"أيضاً سؤاله الثاني الذي يقول: إني سمعتهما: يقال: لا تفترض واقعة معينة وتستفتي فيها، فإنك ربما ابتليت بها، فهل هذا صحيح؟","title":"حكم افتراض واقعة معينة والاستفتاء عنها","answer":"الجواب: لا حرج في هذا، لكن ترك الافتراضات أولى؛ لأن المسلم يشتغل بالشيء الواقع، ويجتهد في معرفة الواقع حتى يعرف حكم الله فيه، لكن غير الواقع إذا كان يخشى وقوعه وأن هذا الشيء مما يقع بين الناس ويحب أن يعرف حكمه، فلا بأس، أما في عهد النبي ﷺ كان لا ينبغي أن يسأل عن شيء سكت الله عنه، أما اليوم فقد استقرت الشريعة والحمد لله، استقرت الشريعة واستقرت الأحكام فإذا سأل عن حكم الله في مسألة من المسائل يخشى أن تقع به فلا بأس بذلك، ولا حرج في ذلك. نعم.","link":"https://binbaz.org.sa/fatwas/5404/حكم-افتراض-واقعة-معينة-والاستفتاء-عنها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06210.mp3","categories":["أصول الفقه"]},{"id":7913,"question":"أيضاً يقول الأخ المؤمن: هذان سؤالان أعرضهما لأنني سمعتهما من بعض المشايخ الذين قد يفتون للناس، ونظراً لأنني لم أطمأن إليهما سألت عنهما.الأول: يقال: إذا سألت عالماً فأفتاك فنفذ ما قاله لك ولا تستفت غيره، فهل هذا صحيح أو أنني أستطيع السؤال حتى يطمئن قلبي؟","title":"هل إذا سألت عالماً وأفتاني فلا يجوز سؤال غيره؟","answer":"الجواب: ليس هذا بصحيح، بل ينبغي للسائل أن يجتهد في السؤال حتى يطمئن قلبه، ويتحرى الأعلم فالأعلم والأورع فالأورع من أهل العلم حتى يطمئن قلبه إلى أن الفتوى صحيحة وأنها مناسبة وموافقة للشرع، كما قال النبي ﷺ: البر حسن الخلق، والإثم ما حاك في نفسك وكرهت أن يطلع عليه الناس ويقول ﷺ: استفت قلبك، البر ما اطمأنت إليه النفس واطمئن إليه القلب والإثم ما حاك في النفس، وتردد في الصدر، وإن أفتاك الناس وأفتوك.\nفالمؤمن يطلب العلم ويتفقه في الدين ويسأل أهل العلم حتى يطمئن قلبه إلى أن الفتوى موافقة للشرع، حسب اجتهاده وطاقته.\nالمقدم: طيب بالنسبة لطالب العلم إذا أتاه شخص ليستفتيه وعلم منه أن قد استفتى شخصاً قبله، هل له أن يجيبه على هذا الاستفتاء؟\nالشيخ: لا مانع، لكن على المفتي أن يتحرى الأدلة الشرعية، وألا يتساهل، أن يتحرى الكتاب والسنة فيعطي السائل ما يعلمه من شرع الله؛ كتاب الله وسنة النبي ﷺ ولا يتساهل، بل ينبغي له الاجتهاد والتحري حتى لا يفتي إلا عن بصيرة وعن علم.\nوإذا سأله سائل يعلم أنه قد سأل غيره فلا مانع، وإن سأله قال: ماذا قال لك فلان؟ حتى يستطيع بذلك إما أن يوافقه أو يخالفه فلا بأس.\nكان الصحابة قد يفعلون هذا، قد يفعلون هذا يسألون من سألهم: ماذا قال لك فلان؟ يقول: قال فلان، فيقول: هو على فتواه، وقد يخالفه فيقول: الفتوى كذا والفتوى كذا. نعم.\nالمقدم: طيب لو امتنع عن فتواه، هل يعتبر ذلك من كتمان العلم؟\nالشيخ: إن كان يعلم أن الفتوى باطلة يكون من كتمان العلم، أما إذا كان بالاجتهاد والتحري والرأي فلا بأس.","link":"https://binbaz.org.sa/fatwas/5402/هل-اذا-سالت-عالما-وافتاني-فلا-يجوز-سوال-غيره","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_062/06209.mp3","categories":["أصول الفقه"]},{"id":7988,"question":"أيضاً لديه سؤال آخر يقول فيه: هل يجوز لشخص أن يترك المذهب الذي هو عليه ويعتنق مذهب آخر، ومتى يجوز له ذلك إذا كان جائز؟","title":"وجوب اتباع الدليل وإن خالف المذهب","answer":"الجواب: المذاهب الأربعة ليست لازمة للناس، والقول أنه يلزم كل طالب علم أو كل مسلم أن يعتنق واحداً منها قول فاسد، قول غير صحيح، الواجب الالتزام بما شرعه الله، على لسان رسوله محمد عليه الصلاة والسلام، وليس هناك شخص معين يلزم الأخذ بقوله، لا الأئمة الأربعة ولا غيرهم، فالواجب اتباع النبي صلى الله عليه وسلم والسير على منهاجه في الأحكام والتشريع، ولا يجوز أن يقلد أحد بعينه في ذلك، بل الواجب هو اتباع النبي ﷺ، والأخذ بما شرع الله على يده عليه الصلاة والسلام سواء وافق الأئمة الأربعة أو خالفهم، هذا هو الحق.\nفبهذا يعلم أنه لا يتعين أن يلزم مذهباً معيناً فإذا أخذ بقول أحمد في مسألة وانتسب إليه ثم رأى أن ينتقل إلى مذهب الشافعي في هذه المسألة نفسها أو في مسائل أخرى قام الدليل عليها فلا بأس، أو مذهب مالك ، أو مذهب أبي حنيفة ، المهم متابعة الدليل، فإذا كان في مسألة من المسائل على مذهب أحمد ثم رأى أن الدليل مع مالك .. مع الشافعي .. مع أبي حنيفة .. مع الظاهرية.. مع غيرهم من السلف أخذ بذلك، فالعمدة على الدليل، مثلما قال الله جل وعلا: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59] يعني: في مسائل الخلاف.\nأما في مسائل الإجماع فلا كلام، يجب على المسلم أن يأخذ بما قاله العلماء ولا يخالفهم، لكن في مسائل الخلاف والنزاع طالب العلم ينظر في الدليل فإذا ظهر له الدليل مع أحمد أو مع مالك أو مع أبي حنيفة أو مع غيرهم أخذ بالدليل، واستقام عليه. لا متابعة للهوى والشهوة، لا. ولكن متابعة للدليل، أما كون الإنسان يتنقل بين مذهب فلان ومذهب.. لهواه إذا ناسبه المذهب هذا في مسألة ذهب إليه، والآخر في مسألة ذهب إليه اتباعاً لهواه وشهوته، هذا لا يجوز، هذا تلاعب لا يجوز، لكن إذا كان بالدليل ينظر في الدليل وينظر في كلام أهل العلم ويرجح بالدليل لا لهواه بل للأخذ بالدليل فهذا مأجور ومشكور وهذا هو الواجب عليه. نعم.","link":"https://binbaz.org.sa/fatwas/5543/وجوب-اتباع-الدليل-وان-خالف-المذهب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_073/07304.mp3","categories":["أصول الفقه"]},{"id":8070,"question":"محمد سالم من الرياض بعث بهذه الرسالة يقول فيها: هل يجب، أو اختلط علي أمر المذاهب والناس يسألون دائماً من أي مذهب أنت؟ وسؤالي هل يجب على المسلم أن يتقيد بمذهب من المذاهب، وقد علمت بقراءاتي أن في المذاهب خلاف، فمثلاً في الرضاعة وجدت أن المذهبان أبي حنيفة ومالك يحرمان بمجرد الرضعة، بينما الشافعي وأحمد لا يحرمان إلا بخمس رضعات، فكيف يحتكم الإنسان المسلم في هذه الخلافات، إذا أراد شاب أن يتزوج بفتاة رضعت رضعة واحدة من أمه، أفيدوني أفادكم الله؟","title":"المعتبر عند اختلاف أقوال المذاهب الأربعة","answer":"الجواب: المذاهب المعروفة مذاهب حق، مذهب الشافعي و مالك و أبي حنيفة و أحمد كلها مذاهب تدعو إلى الحق، وتلتزم الحق، وهي مذاهب أهل السنة والجماعة لكن قد يقع للعالم بعض الغلط في بعض المسائل، من الأئمة الأربعة وغيرهم، وليس الواحد منهم معصوماً، بعضهم قد تخفى عليه بعض السنة، وقد لا يبلغه الحديث الصحيح من طريق يثبت عنده، فلهذا يقع بعض الغلط في بعض المذاهب، وإذا اختلفت المذاهب فالواجب تحكيم الدليل، فأهل العلم ينظرون في الدليل، ثم يرجحون ما يقتضيه الدليل في مسائل الخلاف، وطالب العلم الذي لا يصل إلى هذا الحد يسأل أهل العلم، وهكذا العامي يسأل أهل العلم عما يقتضيه الشرع المطهر، مثل: الرضاعة إذا وجد من ارتضع من أمك رضعة واحدة أو رضعتين فاسألوا أهل العلم، والصواب في هذا قول من قال بالخمس؛ لأنه دل عليه الحديث الصحيح عن رسول الله عليه الصلاة والسلام، والآية في إطلاق الرضاعة والأحاديث الأخرى التي فيها إطلاق الرضاعة تحمل على المقيد، على القاعدة المتبعة في الأصول، أن المطلق من النصوص يحمل على المقيد، وقد ثبت من حديث عائشة رضي الله عنها: أن النبي ﷺ قال: لـسهلة بنت سهيل: أرضعي سالماً خمس رضعات تحرمي عليه وثبت أيضاً من حديث عائشة رضي الله عنها قالت: كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات وتوفي النبي ﷺ والأمر على ذلك أخرجه مسلم في الصحيح والترمذي وهذا لفظه، هذا هو الحكم عند النزاع، الحكم هو السنة، فإذا صحت السنة في شيء وجب الأخذ به، وترجيح القول الذي يوافق السنة، وفي هذه المسألة من قال بالخمس فقوله هو الموافق للسنة، ومن قال: يكفي رضعة واحدة أو رضعتان أو ثلاث فقوله مرجوح، وهكذا في المسائل الخلافية؛ لأن الله قال: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، وقال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10].\nفإذا اختلف الناس في شيء وجب رده إلى الكتاب والسنة، وأهل العلم هم الذين ينظرون في ذلك، وهم الرادون للكتاب والسنة، فإذا نظروا في الأدلة وجب ترجيح ما قام عليه الدليل، والعامي يسأل، وطالب العلم القاصر الذي لم يبلغ .... درجة المجتهدين والعارفين بدرجات السنة يسأل أهل العلم ويتحرى في أهل العلم من هو أقرب إلى العلم والفضل، وأقرب إلى أهل السنة؛ لأن هذا هو واجبه وهذا جهده، ولا يجب أن يلتزم الإنسان بمذهب معين، بل يتحرى الحق ويسأل عن الحق، فمتى وجد الحق أخذ به، سواءً كان مع مالك أو الشافعي أو أبي حنيفة أو أحمد ، أو غيرهم من أهل العلم في مسائل الخلاف. نعم.","link":"https://binbaz.org.sa/fatwas/5872/المعتبر-عند-اختلاف-اقوال-المذاهب-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_084/08407.mp3","categories":["أصول الفقه"]},{"id":8074,"question":"محمد سالم من الرياض بعث بهذه الرسالة يقول فيها: هل يجب، أو اختلط علي أمر المذاهب والناس يسألون دائماً من أي مذهب أنت؟ وسؤالي هل يجب على المسلم أن يتقيد بمذهب من المذاهب، وقد علمت بقراءاتي أن في المذاهب خلاف، فمثلاً في الرضاعة وجدت أن المذهبان أبي حنيفة ومالك يحرمان بمجرد الرضعة، بينما الشافعي وأحمد لا يحرمان إلا بخمس رضعات، فكيف يحتكم الإنسان المسلم في هذه الخلافات، إذا أراد شاب أن يتزوج بفتاة رضعت رضعة واحدة من أمه، أفيدوني أفادكم الله؟","title":"المعتبر عند اختلاف أقوال المذاهب الأربعة","answer":"الجواب: المذاهب المعروفة مذاهب حق، مذهب الشافعي و مالك و أبي حنيفة و أحمد كلها مذاهب تدعو إلى الحق، وتلتزم الحق، وهي مذاهب أهل السنة والجماعة لكن قد يقع للعالم بعض الغلط في بعض المسائل، من الأئمة الأربعة وغيرهم، وليس الواحد منهم معصوماً، بعضهم قد تخفى عليه بعض السنة، وقد لا يبلغه الحديث الصحيح من طريق يثبت عنده، فلهذا يقع بعض الغلط في بعض المذاهب، وإذا اختلفت المذاهب فالواجب تحكيم الدليل، فأهل العلم ينظرون في الدليل، ثم يرجحون ما يقتضيه الدليل في مسائل الخلاف، وطالب العلم الذي لا يصل إلى هذا الحد يسأل أهل العلم، وهكذا العامي يسأل أهل العلم عما يقتضيه الشرع المطهر، مثل: الرضاعة إذا وجد من ارتضع من أمك رضعة واحدة أو رضعتين فاسألوا أهل العلم، والصواب في هذا قول من قال بالخمس؛ لأنه دل عليه الحديث الصحيح عن رسول الله عليه الصلاة والسلام، والآية في إطلاق الرضاعة والأحاديث الأخرى التي فيها إطلاق الرضاعة تحمل على المقيد، على القاعدة المتبعة في الأصول، أن المطلق من النصوص يحمل على المقيد، وقد ثبت من حديث عائشة رضي الله عنها: أن النبي ﷺ قال: لـسهلة بنت سهيل: أرضعي سالماً خمس رضعات تحرمي عليه وثبت أيضاً من حديث عائشة رضي الله عنها قالت: كان فيما أنزل من القرآن عشر رضعات معلومات يحرمن، ثم نسخن بخمس معلومات وتوفي النبي ﷺ والأمر على ذلك أخرجه مسلم في الصحيح والترمذي وهذا لفظه، هذا هو الحكم عند النزاع، الحكم هو السنة، فإذا صحت السنة في شيء وجب الأخذ به، وترجيح القول الذي يوافق السنة، وفي هذه المسألة من قال بالخمس فقوله هو الموافق للسنة، ومن قال: يكفي رضعة واحدة أو رضعتان أو ثلاث فقوله مرجوح، وهكذا في المسائل الخلافية؛ لأن الله قال: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ [النساء:59]، وقال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10].\nفإذا اختلف الناس في شيء وجب رده إلى الكتاب والسنة، وأهل العلم هم الذين ينظرون في ذلك، وهم الرادون للكتاب والسنة، فإذا نظروا في الأدلة وجب ترجيح ما قام عليه الدليل، والعامي يسأل، وطالب العلم القاصر الذي لم يبلغ .... درجة المجتهدين والعارفين بدرجات السنة يسأل أهل العلم ويتحرى في أهل العلم من هو أقرب إلى العلم والفضل، وأقرب إلى أهل السنة؛ لأن هذا هو واجبه وهذا جهده، ولا يجب أن يلتزم الإنسان بمذهب معين، بل يتحرى الحق ويسأل عن الحق، فمتى وجد الحق أخذ به، سواءً كان مع مالك أو الشافعي أو أبي حنيفة أو أحمد ، أو غيرهم من أهل العلم في مسائل الخلاف. نعم.","link":"https://binbaz.org.sa/fatwas/5872/المعتبر-عند-اختلاف-اقوال-المذاهب-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_084/08407.mp3","categories":["أصول الفقه"]},{"id":8195,"question":"تقول في رسالتها الأخت من سوريا: هل يجب علي أن أكون على مذهب معين؟ وهل أختار أنا هذا المذهب، أم أكون مثل والدي أو والدتي، فوالدي حنبلي ووالدتي حنفية؟ ما الذي نتبع منهما؟","title":"حكم التزام الإنسان بمذهب معين","answer":"الجواب: ليس من اللازم التمذهب، لا من الرجل ولا المرأة، ليس من اللازم أن يكون حنبلياً، أو مالكياً، أو شافعياً، أو حنفياً، أو ظاهرياً، لا ليس لازماً، لا من الرجل ولا من المرأة، ولكن على الجميع تحري الحق، والنظر في الأدلة الشرعية، فإذا كان لا يعرف ذلك؛ لأنه عامي يسأل أهل العلم في بلده، يسأل أهل العلم المعروفين، ويختار المعروفين بالصلاح والاستقامة، والبعد عن الشر، فيسألهم عن أمور دينه؛ لأن الله يقول: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ [النحل:43]، فالجاهل يسأل أهل العلم، وإذا أفاده أهل العلم عمل بذلك، وينبغي أن يسأل العالم عن الدليل، من كلام الله، من كلام رسوله صلى الله عليه وسلم حتى يستفيد أكثر، وإذا كان طالب علم أو كانت المرأة طالبة علم، تنظر في الأدلة، تطالع كتب العلماء في الصلاة، في الزكاة، في الصيام، في المعاملات، في أحكام الحيض، في أحكام النفاس، في غير ذلك، تطالع الكتب، تنظر في الأدلة، وما ظهر لها أنه هو القائم على الدليل تمسكت به، وأخذت به، هذا هو الواجب على المسلمين من الذكور والإناث. نعم.","link":"https://binbaz.org.sa/fatwas/6003/حكم-التزام-الانسان-بمذهب-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_093/09304.mp3","categories":["أصول الفقه"]},{"id":8394,"question":"الواقع سماحة الشيخ، تعددت الفتاوى، وتعدد المفتون في كثير من المجلات والصحف في الداخل والخارج، ولابد لسماحة الشيخ من كلمة توجيهية حول هذا الموضوع، بالنسبة للقراء، وبالنسبة لأولئك الذين يتعاطون الفتوى؟","title":"نصائح قيمة للمفتي والمستفتي","answer":"الجواب: نصيحتي للقراء أن لا ينجرفوا مع كل مفت، وأن يعرضوا فتاوى الناس على كلام الله، وكلام رسوله عليه الصلاة والسلام، وأن يعظموا ما عظمه الله ورسوله، وأن ينتهوا عما نهى الله عنه ورسوله، وأن يسألوا أهل العلم المعروفين بالاستقامة والغيرة الإسلامية والعلم الشرعي، وأن لا ينجرفوا مع كل فتوى، بل عليهم أن يتثبتوا وأن يحذروا؛ حتى لا يقعوا في الباطل.\nأما وصيتي ونصيحتي للمفتين، فعلينا جميعاً تقوى الله، وأن لا نفتي إلا بما يوافق الحق، وأن نحذر التساهل أو الميل إلى أهواء الناس وما يرضيهم، فإن الناس أكثرهم لا يرضيه إلا الباطل، فالواجب على المفتي أن يتقي الله، وأن يخاف الله، وأن يراقب الله، وأن لا يفتي إلا بما يظهر له من كلام الله وكلام رسوله عليه الصلاة والسلام، بعد التثبت، وبعد النظر والعناية، وبعد مراجعة أهل العلم، والاستعانة بما ذكروه في كتبهم، حتى تكون الفتوى على بينة، وعلى بصيرة، نسأل الله للجميع الهداية والتوفيق.","link":"https://binbaz.org.sa/fatwas/6260/نصاىح-قيمة-للمفتي-والمستفتي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11613.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":8395,"question":"سؤال أخير في هذه الحلقة، سماحة الشيخ! بالنسبة لاختلاف المفتين، هل من تعليق عليه؟","title":"اختلاف المفتين وكيفية معالجة هذا الخلاف","answer":"الشيخ: نعم، اختلاف المفتين لا بد منه، ..... من قديم الزمان، الفتوى لا بد من وقوع الاختلاف فيها، كما هو موجود في كتب أهل العلم، لكن الواجب على من ابتلي بأن يفتي الناس، أن ينظر في هذه الفتاوى، وأن يحرص على التماس الدليل الواضح، وأن يحذر التساهل بالفتوى، وإذا استطاع أن ينصح المفتين، وأن يقرب بينهم إذا كانوا في بلاده أو يستطيع مكاتبتهم، حتى تكون الفتوى متقاربة، وحتى تضيق شقة الخلاف، فهذا من أهم المهمات، ونسأل الله للجميع الهداية والتوفيق. نعم.","link":"https://binbaz.org.sa/fatwas/6261/اختلاف-المفتين-وكيفية-معالجة-هذا-الخلاف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_116/11614.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":8812,"question":"يسأل ويقول: الطرائق الأربعة -ولا أدري لعله يقصد المذاهب سماحة الشيخ- فيقول: الطرائق الأربعة الأحمدية و الشافعية و المالكية و الحنفية هل هذه الطرائق صحيحة، وفي أي زمن وجدت؟","title":"صحة المذاهب الأربعة وتاريخ نشأتها","answer":"الجواب: هذه المذاهب الأربعة قصده المذاهب الأربعة، الأحمدية يعني: مذهب أحمد بن حنبل ، والشافعية أتباع الشافعي محمد بن إدريس الشافعي رحمهما الله، والمالكية أتباع الإمام مالك بن أنس رحمه الله، والحنفية أتباع أبي حنيفة النعمان بن ثابت رحمه الله، وهذه مذاهب معروفة انتشرت في القرون المتأخرة في القرن الثالث وما بعده أما مذهب أبي حنيفة فعرف وانتشر في القرن الثاني، وهكذا مذهب مالك في القرن الثاني، وأما مذهب الشافعي و مالك فاشتهرا بعد ذلك، في القرن الثالث وما بعده.\nوهم على خير وعلى هدى وعلى حق  ورحمهم وهم علماء هدى علماء خير، ولكن ليس معناه أن كل واحد معصوم ما يقع منه خطأ كل واحد له أغلاط حسب ما بلغهم من السنة وحسب ما عرفوه من كتاب الله ، فقد يفوت بعضهم شيء من العلم وشيء من السنة، هذا أمر معلوم هم وغيرهم كـالأوزاعي و إسحاق بن راهويه و سفيان الثوري و سفيان بن عيينة و وكيع بن الجراح و إبراهيم الكلبي وغير ذلك من الأئمة المعروفين كل واحد منهم قد يفوته بعض العلم؛ لأن ليس كل واحد يحيط بالسنة ويحيط بالعلم قد يفوته بعض الأشياء لكنهم أئمة هدى ولهم أتباع نظموا مذاهبهم وجمعوا مسائلهم وفتاواهم، وكتبوا في ذلك حتى انتشرت هذه المذاهب وعلمت بسبب أتباعهم الذين ألفوا فيها وجمعوا فيها مسائل هؤلاء الأئمة وما أفتوا به في ذلك، فقد يقع بعض الأخطاء من بعضهم؛ لأنه لم تبلغه السنة في بعض المسائل فأفتى باجتهاده فقد يقع الخطأ من أجل ذلك، والآخر بلغه الحديث وعرف الحديث فأفتى بالصواب، فهذه تقع لكل واحد منهم في مسائل معدودة رحمهم الله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/6967/صحة-المذاهب-الاربعة-وتاريخ-نشاتها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_135/13508.mp3","categories":["أصول الفقه"]},{"id":8814,"question":"جزاكم الله خيراً. لعل لاختيار مذهب معين أو كذا سماحة الشيخ له علاقة بهذا السؤال؟","title":"وجوب الأخذ بالدليل وعدم تقليد أحد","answer":"الجواب: هذا في حق طلبة العلم أهل العلم عليهم أن لا يقلدوا أحداً ولكن إذا انتسب إلى أحد المذاهب من باب الانتساب لأنه رأى قواعده وأصوله توافقه فلا بأس، لكن ليس له أن يقلد زيد أو عمرو لا الشافعي ولا أحمد ولا مالك ولا أبا حنيفة بل عليه أن يأخذ من حيث أخذوا، وعليه أن ينظر في الأدلة فما رجح في الأدلة في مسائل الخلاف أخذ به، وأما ما أجمعوا عليه فالحمد لله، لكن بمسائل الخلاف ينظر في الأدلة، فإذا كان الدليل مع أبي حنيفة أخذه مع مالك أخذه مع الشافعي أخذه مع أحمد أخذه مع الأوزاعي مع غيرهم أخذ الدليل ورجح بالدليل؛ لأن الله يقول سبحانه: فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59] ويقول سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10] فالواجب على أهل العلم أن يعرضوا ما تنازع فيه الناس على الأدلة الشرعية، فما رجح في الدليل وجب الأخذ به، أما العامي يسأل أهل العلم في زمانه يتخير الناس الطيبين العالم الطيب الذي يظهر عليه التأسي بالنبي ﷺ والورع ويظهر منه العلم ويشهد له الناس بالخير، يتحرى ويسأله، ومذهبه مذهب من أفتاه، لا يتكلف، لكن يتحرى أهل العلم ويسأل في بلاده أو غير بلاده عن المعروفين بالعلم والفضل واتباع الحق المحافظين على الصلوات الذين يعرفون باتباع السنة من توفير اللحى وعدم الإسبال والبعد عن مواقف التهم، إلى غير هذا من الدلائل على استقامة العالم، فإذا أرشد إلى عالم ظاهره الخير ومعروف بالعلم سأله عما أشكل عليه والحمد لله فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]. نعم.","link":"https://binbaz.org.sa/fatwas/6969/وجوب-الاخذ-بالدليل-وعدم-تقليد-احد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_135/13510.mp3","categories":["أصول الفقه"]},{"id":9069,"question":"وهذه رسالة وصلت إلى البرنامج من المستمع الحافظ حمة من موريتانيا، ويعمل بالجماهيرية الليبية يقول في رسالته وفي بدايتها:بسم الله الرحمن الرحيم، اللهم صل على سيدنا محمد وعلى آله وأصحابه أجمعين.وبعد: إلى علمائنا الأجلاء الأفاضل في برنامج نور على الدرب، أبلغكم تحياتي، لقد استمعت إلى برنامجكم الطيب والمفيد لجميع المسلمين في أنحاء المعمورة، واستفدت منه كثيراً، وأرجو منكم الإفادة عن سؤالي وهو أنني من أسرة مالكية، وذهبت إلى المملكة العربية السعودية، وتعلمت التجويد على يد أستاذ سعودي، وتحولت قراءتي من ورش إلى حفص، وأخذت بعضاً من الفقه عن طريق كتاب: فقه السنة للسيد سابق، وعندما عدت إلى الوطن انتقد علي بعض الإخوة أشياء كثيرة: أولها: القبض في الصلاة، والتسليمتان بعد الصلاة على اليمين والشمال، وكثيراً من السنن التي يطيل ذكرها ويقولون: إن الإمام مالك لم يأمر بها ولم يذكرها، ولا أطيل عليكم، كل السؤال هو: أني أتبع سنة الرسول ﷺ، فهل يجوز لي أن أتبع أحد الأئمة الأربعة، أم أن أبقى على ما أنا عليه من المذهب المالكي، وتلك هي السنة فقط لا غير، أفيدونا أفادكم الله؟","title":"حكم التقيد بأحد المذاهب الفقهية","answer":"الجواب: أسأل الله لنا ولك التوفيق والهداية لما فيه صلاح الدين والدنيا، اعلم يا أخي! أن الواجب على المسلمين جميعاً في أقطار المعمورة أن يتبعوا ما دل عليه كتاب الله عز وجل وسنة رسوله محمد عليه الصلاة والسلام، وليس عليهم أن يتقيدوا بمذهب مالك أو أبي حنيفة أو الشافعي أو أحمد رحمة الله عليهم جميعاً أو الظاهرية! لا، على العلماء أن يبحثوا ويعتنوا بسنة الرسول ﷺ، وما كان عليه وأصحابه، فما بان لهم أنه هو سنة النبي ﷺ وجب عليهم الأخذ به والتقيد به، والدعوة إليه؛ لأن الله جل وعلا يقول في كتابه العظيم: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] ويقول : يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59] والرد إلى الله هو الرد إلى كتابه العظيم القرآن، والرد إلى الرسول ﷺ هو الرد إليه في حياته عليه الصلاة والسلام، ثم إلى سنته بعد وفاته ﷺ وعلى آله وأصحابه، ويقول سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ [الشورى:10] ويقول سبحانه: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80] فالرسول ﷺ قبض، وثبت عنه هذا في صحيح البخاري من حديث سهل بن سعد أن النبي ﷺ: كان يأمر الرجل أن يضع يده اليمنى على ذراعه اليسرى في الصلاة، وقال أبو حازم الراوي عن سهل: ولا أعلمه إلا ينمي ذلك إلى النبي ﷺ وثبت أيضاً في السنن من حديث وائل بن حجر : أنه رأى النبي ﷺ يقبض يده اليسرى بيده اليمنى يضع يده اليمنى على كفه اليسرى والرسغ والساعد، وجاءت أحاديث أخرى تؤيد ذلك هذا هو السنة، وإن لم يذهب إلى ذلك مالك ، فالسنة أحق بالاتباع ومقدمة على مالك وعلى غير مالك ، فـمالك رحمه الله هو أحد العلماء، وهكذا أبو حنيفة رحمه الله وهكذا الشافعي وهكذا أحمد وهكذا الثوري والأوزاعي وإسحاق بن راهويه وهكذا غيرهم من أهل العلم من الصحابة ومن بعدهم، كلهم تعرض أقوالهم وأعمالهم ومسائل مذاهبهم كلها تعرض على الكتاب والسنة، هكذا يجب على أهل العلم الذين أعطاهم الله بسطة في العلم والبصيرة، وإذا هداه الله إلى شيء من السنة فليتمسك بذلك، وهكذا التسليمتان، ثبت عن الرسول ﷺ أنه كان يسلم تسليمتين والمشروع لنا أن نسلم تسليمتين، وقد ذهب بعض أهل العلم إلى وجوبهما وبعضهم إلى أنهما ركن، والجمهور على تسليمة واحدة، ولكن الأرجح أن يسلم تسليمتين عملاً بالسنة الثابتة عن رسول الله عليه الصلاة والسلام، ونسأل الله لنا ولكم التوفيق.\nونوصيك بالبقاء على ما عرفت من السنة، نوصيك أيها الأخ بالبقاء على ما عرفت من السنة، وأن تنصح إخوانك في موريتانيا وغيرها بأن يعتنوا بالسنة، ولا يجوز أن يكون في قلوبهم شيء بعد الله أعظم من رسول الله ﷺ، لا يجوز للمؤمن أن يكون في قلبه شيء بعد الله  أعظم من رسول الله صلى الله عليه وسلم، فهو قدوة لنا وهو الإمام وهو السيد المتبع عليه الصلاة والسلام، فلا يجوز لعالم أو غير عالم أن يكون في قلبه شيء أعظم من رسول الله ﷺ بعد الله ﷺ، فالله هو المعظم جل وعلا فوق كل أحد، ولكن بعده سبحانه وتعالى أعظم الناس وأولاهم بالاتباع وأولاهم بالتعظيم، الجائز شرعاً هو رسول الله ﷺ، فهو الإمام المتبع عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/7236/حكم-التقيد-باحد-المذاهب-الفقهية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_225/22507.mp3","categories":["أصول الفقه"]},{"id":9102,"question":"السؤال الثالث في رسالة الأخ: شريف خليفة أحمد سوداني مقيم بالرياض يقول فيه: ما هو الفرض والواجب مع التفضل بإعطائي أمثلة على ذلك، أفيدونا أفادكم الله؟","title":"الفرق بين الفرض والواجب","answer":"الجواب: الفرض والواجب شيء واحد، وهو الذي يستحق الثواب فاعله، ويستحق العقاب تاركه، يقال له: فرض، ويقال له: واجب، ولكن بعض أهل العلم يستعملون الفرض فيما قامت الأدلة القوية على وجوبه، وما كانت أدلته أضعف من ذلك يسمونه واجباً، وإلا فالأصل الذي عليه جمهور أهل العلم، أن الفرض والواجب شيء واحد، فيقال للصلاة: فرض، ويقال لها: واجبة، ويقال لصلاة الجماعة: فرض، ويقال لها: واجبة، ويقال للزكاة: فرض، ويقال لها: واجبة، ويقال لصيام رمضان: فرض، ويقال له: واجب، ويقال للحج مع الاستطاعة: فرض، ويقال له: واجب، هذا هو المعروف عند جمهور أهل العلم، وهو الشيء الذي قام الدليل على أنه لازم، يستحق العقاب تاركه، ويستحق الثواب فاعله، هذا يسمى فرضاً، ويسمى واجباً.\nولكن بعض أهل العلم مثلما تقدم قد يتسامحون فيطلقون الفرض على ما قويت أدلته وصارت واضحة جلية معلومة من الدين بالضرورة، فيسمون ذلك فرضاً كالصلاة ... فرض، والزكاة فرض، ويسمون التسبيح في الركوع والتسبيح في السجود يسمونه واجب، يسمون التكبيرات ماعدا الأولى يسمونها واجبة؛ لأن أدلتها أقل من أدلة وجوب الصلاة نفسها، وهكذا يسمون في الحج الرمي رمي الجمار يسمونه واجب، ويسمون المبيت في المنى ومزدلفة واجب، ويسمون الطواف ركن فرض، ويسمون الوقوف بعرفة فرض وركن؛ لأن أدلته أظهر وأعظم، وهكذا أمثلة كثيرة لأهل العلم. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7264/الفرق-بين-الفرض-والواجب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22708.mp3","categories":["أصول الفقه"]},{"id":9104,"question":"السؤال الرابع في رسالة الأخ: شريف خليفة أحمد السوداني -المقيم بالرياض- يقول فيه: ما هو المكروه وما هو المحظور؟ أفيدونا أفادكم الله.","title":"تعريف المكروه والمحظور","answer":"الجواب: المكروه عند أهل العلم هو: الذي ينبغي تركه، ولكن لا يأثم من فعله، لكن يكره فعله، مثل التحدث بعد العشاء، في غير العلم وغير الأمور الضرورية؛ لأنه قد يشغل عن صلاة الفريضة قد يسبب السهر، كان النبي يكره النوم قبلها والحديث بعدها عليه الصلاة والسلام مثل كثرة الحديث في المساجد في أمور الدنيا مكروه وليس محرم، مثل القيل والقال الذي: ليس فيه فائدة مكروه.\nوالمحظور: هو الممنوع المحرم مثل الغيبة والنميمة وشهادة الزور والأيمان الفاجرة، يقال له: محظور، ويقال له: ممنوع، ويقال لها: محرم مثل قطيعة الرحم، مثل عقوق الوالدين، مثل أكل الربا كل هذه يقال لها: محظورة ويقال لها: ممنوعة، ويقال لها: محرمة، وما دون ذلك من الأشياء التي ينبغي تركها، ولكنها ليس في الأدلة ما يحرمها ويمنعها ولكنها مطلوب تركها، يقال لها: مكروه مثلما تقدم، مثل التحدث بعد العشاء-صلاة العشاء- بدون ضرورة أو حاجة، ومثلما تقدم الكلام الكثير في المساجد في أمور الدنيا يكره، ومثل الكلام الذي ليس له فائدة، كونه سيخوض في أشياء مالها فائدة أو يسأل عما لا يعنيه ترك هذا أولى ومكروه وتدخله فيما لا يعنيه. نعم.\nمثل ترك النوافل، ترك سنة الظهر مكروه، ترك سنة المغرب مكروه، ترك سنة الفجر مكروه. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7265/تعريف-المكروه-والمحظور","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_227/22709.mp3","categories":["أصول الفقه"]},{"id":9263,"question":"أخونا يقول: لي أب كبير في السن لا يستطيع الصلاة أو الصيام بل لا يتقن الصلاة ولا يقوى على الصيام هل أصوم عنه أو أطعم عنه كل يوم مسكيناً وهل يصح أن يصوم عنه أولاده منفردين، أي: متقاسمين الشهر، أفيدونا بارك الله فيكم؟","title":"حكم الصلاة والصيام على الكبير الخرف","answer":"الجواب: إن كان عقله قد اختل فليس عليه صلاة ولا صوم، إن كان قد اختل العقل بسبب الكبر صار لا يحفظ الأمور ولا يتقنها بل يظهر عليه التخريف ونقص العقل وعدم ضبطه للأمور فلا شيء عليه لا صلاة ولا صوم؛ لأن هذه الأمور مناطة بالعقل، فإذا اختل العقل سقط التكليف بالصوم والصلاة وغير ذلك سوى الحق المالي من الزكاة فيزكى من ماله إذا كان عنده مال على الصحيح الذي عليه جمهور أهل العلم، أما إن كان عقله باقياً ليس فيه خلل بل يعقل فإنه واجب عليه أن يصلي ولو على جنبه ولو مستلقياً، يصلي بالكلام والنية، وهكذا يصوم إن كان يستطيع الصوم فإن كان لا يستطيع لكبر السن فإنه يطعم عنه عن كل يوم مسكين ولا يصام عنه بل يطعم عنه عن كل يوم مسكين نصف الصاع من قوت البلد، كيلو ونصف تقريباً من قوت البلد، تمر أو أرز أو حنطة أو غير هذا مما يتقوته أهل البلد. نعم.\nالمقدم: أخونا يقول: إن والده لا يتقن الصلاة؟\nالشيخ: معنى هذا الكلام: أنه مختل الشعور فإذا اختل شعوره فلا شيء عليه، أما إذا كان ما يتقن من أجل المرض، يعني: يضعف عن ... يوجه ويرشد حتى يصلي على حسب حاله، إذا كان ما يستطيع على جنب يكون مستلقياً فيكبر ناوياً الصلاة ويقرأ الفاتحة مثلاً ويكبر ناوياً الركوع ويقول: سبحان ربي العظيم، سبحان ربي العظيم، ثم يقول: سمع الله لمن حمده ناوياً الرفع وهو على حاله وهو مستلقي أو على جنب، وهكذا يكبر ناوياً السجود إلى آخره. نعم.","link":"https://binbaz.org.sa/fatwas/7426/حكم-الصلاة-والصيام-على-الكبير-الخرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_154/15401.mp3","categories":["أصول الفقه"]},{"id":9372,"question":"شيخ عبدالعزيز إذا أذنتم.. كفعل الرسول عليه أفضل الصلاة والسلام كأن يأمر بشيء ولا يفعله، أو ينهى عن شيء ويفعله، لعل في هذا مقام يحتاج إلى مزيد من الإيضاح سماحة الشيخ؟","title":"دلالة فعل النبي لما نهى عنه وتركه لما أمر","answer":"الجواب: هذا يقع، فإذا أمر بشيء ثم تركه دل على أنه ليس بواجب، وإذا نهى عن شيء ثم فعله دل على أنه ليس بمحرم؛ ولهذا نهى عن الشرب قائمًا ثم شرب قائمًا، فدل على أن الشرب قائمًا لا حرج فيه ولكن تركه أفضل، إذا تيسر أن يشرب قاعدًا فهو الأفضل وإن شرب قائمًا فلا حرج، وهكذا إذا أمر بشيء ثم تركه عليه الصلاة والسلام فهو يدل على أن هذا المأمور به ليس بواجب، إذ لو كان واجبًا لما تركه عليه الصلاة والسلام.\nفالحاصل: أن أوامره أصلها الوجوب، ونواهيه أصلها التحريم، لكن متى فعل ما نهى عنه دل على أنه ليس بحرام وإنما هو مكروه أو تركه أولى، وإذا أمر بشيء ثم تركه دل على أنه ليس بواجب. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7536/دلالة-فعل-النبي-لما-نهى-عنه-وتركه-لما-امر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_186/18610.mp3","categories":["أصول الفقه"]},{"id":9483,"question":"له سؤالان آخران أصوليان في الحقيقة نود الإشارة إليهما فهو يقول: نسمع أحياناً أن الأوامر الثابتة في الكتاب والسنة تدل على الاستحباب، إلا في حالة ورود قرينة تدل على الوجوب. وهناك من يقول العكس: كل أمر في الكتاب والسنة يدل على الوجوب، ما لم يصرفه صارف إلى الاستحباب. فأي القولين يعتمد عليه عند أهل الأصول؟","title":"دلائل الأوامر والنواهي في الكتاب والسنة","answer":"الجواب: الأصح هو الثاني، الأصح هو أن الأوامر والنواهي على الوجوب والتحريم، هذا هو الأصل، أوامر الله جل وعلا وأوامر الرسول ﷺ كلها تحمل على الوجوب إلا إذا دل دليل على الاستحباب. وهكذا النهي من الله ومن رسوله يحمل على التحريم والمنع إلا إذا جاء ما يدل على الكراهة وعدم التحريم، وهذه قاعدة مستمرة عند أهل السنة وعند أهل الحق من الأصوليين. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7650/دلاىل-الاوامر-والنواهي-في-الكتاب-والسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24111.mp3","categories":["أصول الفقه"]},{"id":9486,"question":"أخيراً يطلب الأخ صالح أبو مروان أن تدلوه سماحتكم على بعض كتب أصول الفقه المبسطة والمحققة؟","title":"أحسن كتب أصول الفقه وأيسرها","answer":"الجواب: من أحسن الكتب فيما نعلم روضة الناظر للموفق ، وكتاب أصول الفقه للشوكاني وابن مفلح رحمه الله، هذه ما عرفنا لا بأس بها، وهناك كتب أوسع منها، لكن طالب العلم ينظر ويتأمل ويفتش الكتب، وينظر ما هو أيسر في الحفظ وأكمل في الفائدة فيعمل بما يظهر له من ذلك، ومجرد الإشارة لا تكفي لا يكفي، بل يجب على طالب العلم أنه يختار لنفسه ما هو أنفع له، وما هو أسهل عليه في الحفظ. نعم.\nالمقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/7653/احسن-كتب-اصول-الفقه-وايسرها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_241/24113.mp3","categories":["أصول الفقه"]},{"id":10133,"question":"تقول: من أقوال النبي الكريم ﷺ: من صلى الفجر جماعة ثم قعد يذكر الله حتى تطلع الشمس، ثم صلى ركعتين كانت له كأجر حجة وعمرة تامة تامة تامة، نعرف أن هذا الحديث يخص الرجال لأنهم يجتمعون في المساجد، فماذا على النساء في هذا الحديث جزاكم الله خيراً؟","title":"هل تدخل المرأة في حديث: «من صلى الفجر في جماعة»؟","answer":"الجواب: نرجو للنساء كذلك فإذا جلست بعد صلاتها في مصلاها تذكر الله تقرأ القرآن تدعو ثم صلت ركعتين بعد ارتفاع الشمس يرجى لها هذا الخير العظيم، النساء كالرجال ما ورد في حق الرجال يعم النساء، وما ورد في حق النساء يعم الرجال إلا بدليل يخص أحد الصنفين وإلا فالأصل العموم، لأنهم كلهم مكلفون وكلهم مشتركون في الأوامر والنواهي، فما ثبت من تحريم أو تحليل أو وجوب أو فضل فهو يعم الجميع، إلا ما خصه الدليل. \nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8306/هل-تدخل-المراة-في-حديث-من-صلى-الفجر-في-جماعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_305/30512.mp3","categories":["أصول الفقه"]},{"id":10255,"question":"يسأل ويقول: هل هناك ضرر في اتباع أكثر من مذهب من المذاهب الإسلامية المعروفة، فإذا اتبعت المذهب الحنفي في بعض الأمور واتبعت الشافعي في غيرها هل ذلك جائز أفتونا جزاكم الله خيرًا؟","title":"حكم التنقل بين المذاهب الفقهية","answer":"الجواب: إذا كان الإنسان طالب علم واتبع المذهب الحنفي في مسائل، ظهر له أنها صحيحة وأن مذهبه أولى من غيره، ثم اتبع مذهب الشافعي أو مالك أو أحمد في مسائل أخرى ظهر أن مذهبهم فيها هو الصحيح حسب الأدلة فلا بأس بهذا؛ لأن المؤمن حسب ما أعطاه الله من العلم يتبع الدليل وينظر في الدليل، فما قام عليه الدليل وجب الأخذ به، سواء وافق مذهب الشافعي أو أبي حنيفة أو مالك أو أحمد أو غيرهم من أهل العلم، المهم أن يوافق الدليل، وأن يدل عليه آية أو حديث شريف صحيح عن رسول الله عليه الصلاة والسلام، أما بالتشهي والهوى فلا، كونه يتلاعب تارةً كذا وتارةً.. هذا لا يجوز، ولكن عليه أن يحرص على معرفة الدليل وسؤال أهل العلم عما يشكل عليه، فإذا عرف بالدليل إذا كان طالب علم عرف بالدليل أن هذا المذهب في هذه المسألة أرجح وذاك في المسألة الأخرى أرجح فلا بأس، وإلا فعليه أن يسترشد بالعلماء ويستفتيهم ويعمل بما يرشدونه إليه من العلم. \nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8426/حكم-التنقل-بين-المذاهب-الفقهية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_336/33608.mp3","categories":["أصول الفقه"]},{"id":10644,"question":"هذا السائل أحمد كشوقة من الأردن عمان يقول: سماحة الشيخ: إذا اختلفت أقوال العلماء في حكم مسألة ما، فمنهم من قال: مكروه، ومنهم من قال: حرام، ومنهم من قال: لا يجوز، فهل أحسن القول في هذه الأحكام هو الحرام؟ وهل هذا دائمًا؟ وإذا اختلفوا على مسألة بأنها جائزة مستحبة لا بأس بها فهل الأحسن القول هو الاستحباب؟ وهل هذا دائمًا، وجهونا بهذا مأجورين؟","title":"موقف المستفتي إذا اختلفت أقوال المفتين","answer":"الجواب: هذا فيه تفصيل على المستفتي أن ينظر في الأمر، ويتحرى من هو أقرب إلى الخير والعلم والفضل وأقرب إلى إصابة الحق حتى يأخذ بفتواه، وإذا احتاط والمسألة: هذا يقول: حرام، وهذا يقول: ليس بحرام، واحتاط وترك ذلك فهذا حسن؛ لقول النبي ﷺ: دع ما يريبك إلى ما لا يريبك من اتقى الشبهات فقد استبرأ لدينه وعرضه ولكن إذا تيسر له أن يتحرى حتى يعرف من هو أكثر علمًا، ومن هو أكثر ورعًا، ومن هو أقرب إلى الصواب حتى يأخذ بقوله، حتى يطمئن قلبه، مثلما قال ﷺ: استفت قلبك البر ما اطمأنت إليه النفس واطمأن إليه القلب، إذا اختلفت عليه الفتاوى، إذا اختلفت الفتوى فالمؤمن ينظر ويتأمل ولا يعجل، يتحرى من هو أقرب إلى الناس للإصابة من أهل العلم والبصيرة والورع والذي يرجح في قلبه أنه أقرب إلى الخير وأقرب إلى إصابة الحق، وهكذا في الاستحباب إذا اختلفوا هذا سنة أو مباح يتحرى، فإذا غلب على قلبه واطمأن قلبه إلى قول من قال: إنه مستحب، عمل عمل المستحب، وإذا اطمأن قلبك إلى أنه مباح فقط عامله معاملة المباح.\nوالمقصود من هذا كله أن المستفتي أو السامع ينظر ويتأمل ولا يعجل، وينظر حال المفتين وأحوالهم، وينظر ما هو أقرب إلى الخير من جهة ورعهم ومن جهة تحريهم الحق، ومن جهة سمعتهم الحسنة، إلى غير ذلك.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/8821/موقف-المستفتي-اذا-اختلفت-اقوال-المفتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_285/28506.mp3","categories":["أصول الفقه"]},{"id":10743,"question":"هل المسلم ملزم باتباع مذهب معين من المذاهب الأربعة أم لا؟","title":"حكم اتباع مذهب من المذاهب الأربعة","answer":"الجواب: ليس ملزماً بل سائغ إذا أراد أن يتبع مذهب من المذاهب سائغ، إذا كان ما يعرف الدليل ليس بطالب علم يعرف الأدلة وسار على مذهب من المذاهب الأربعة لا حرج عليه، ولكن ينبغي له بل يجب عليه أن يتحرى في ذلك سؤال أهل العلم المتبصرين الذين هم في نظره وفي رأيه أقرب من غيرهم إلى الورع والعلم والفضل حتى يتحرى لدينه، ولا بأس سواءً كان شافعياً أو مالكياً أو حنبلياً أو حنفياً لا حرج في ذلك، أما العالم الذي يعرف الأدلة الشرعية فالواجب أن يتحرى الأدلة ويأخذ بالدليل ولا يقلد غيره، هذا هو الواجب عليه، إلا عند الحاجة والعجز فيقلد من هو في رأيه واجتهاده أعلم من غيره وأقرب إلى الحق من غيره.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8928/حكم-اتباع-مذهب-من-المذاهب-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34611.mp3","categories":["أصول الفقه"]},{"id":10748,"question":"هل المسلم ملزم باتباع مذهب معين من المذاهب الأربعة أم لا؟","title":"حكم اتباع مذهب من المذاهب الأربعة","answer":"الجواب: ليس ملزماً بل سائغ إذا أراد أن يتبع مذهب من المذاهب سائغ، إذا كان ما يعرف الدليل ليس بطالب علم يعرف الأدلة وسار على مذهب من المذاهب الأربعة لا حرج عليه، ولكن ينبغي له بل يجب عليه أن يتحرى في ذلك سؤال أهل العلم المتبصرين الذين هم في نظره وفي رأيه أقرب من غيرهم إلى الورع والعلم والفضل حتى يتحرى لدينه، ولا بأس سواءً كان شافعياً أو مالكياً أو حنبلياً أو حنفياً لا حرج في ذلك، أما العالم الذي يعرف الأدلة الشرعية فالواجب أن يتحرى الأدلة ويأخذ بالدليل ولا يقلد غيره، هذا هو الواجب عليه، إلا عند الحاجة والعجز فيقلد من هو في رأيه واجتهاده أعلم من غيره وأقرب إلى الحق من غيره.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/8928/حكم-اتباع-مذهب-من-المذاهب-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_346/34611.mp3","categories":["أصول الفقه"]},{"id":11007,"question":"يسأل عن سن التكليف فيما يبدو شيخ: عبدالعزيز فيقول: ما هي السن التي لا حساب فيها، هل هي ما قبل الخامسة عشرة، أو أقل أو أكثر، جزاكم الله خيرًا؟!","title":"سن التكليف","answer":"الجواب:  سن التكليف خمسة عشر، إذا أكمل الرجل، أو المرأة خمسة عشر سنة فقد دخل في التكليف بالصلوات الخمس، وصوم رمضان، وحج البيت مع الاستطاعة، وسائر التكاليف. أما الزكاة فيلزمه الزكاة في ماله، ولو كان صغيرًا؛ لأنها حق المال، فيخرج الزكاة عنه وليه، وإن كان صغيرًا، وهكذا النفقات اللازمة في المال، يخرجها الولي عن الصغير، إذا كانا عاقلين، أما المجنون والمعتوه فليس عليه تكليف ولو بلغ مائة سنة، إذا كان عقله زائلًا، سواء سمي جنونًا، أو عتهًا فلا تكليف عليه، وهكذا كبير السن إذا زال عقله، إذا كبرت سن الإنسان حتى خرف، وزال عقله ارتفع عنه التكليف، سواءً كان رجلًا أو امرأة ... بسبب اختلال العقل لكبر السن، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9191/سن-التكليف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36607.mp3","categories":["أصول الفقه"]},{"id":11014,"question":"يسأل عن سن التكليف فيما يبدو شيخ: عبدالعزيز فيقول: ما هي السن التي لا حساب فيها، هل هي ما قبل الخامسة عشرة، أو أقل أو أكثر، جزاكم الله خيرًا؟!","title":"سن التكليف","answer":"الجواب:  سن التكليف خمسة عشر، إذا أكمل الرجل، أو المرأة خمسة عشر سنة فقد دخل في التكليف بالصلوات الخمس، وصوم رمضان، وحج البيت مع الاستطاعة، وسائر التكاليف. أما الزكاة فيلزمه الزكاة في ماله، ولو كان صغيرًا؛ لأنها حق المال، فيخرج الزكاة عنه وليه، وإن كان صغيرًا، وهكذا النفقات اللازمة في المال، يخرجها الولي عن الصغير، إذا كانا عاقلين، أما المجنون والمعتوه فليس عليه تكليف ولو بلغ مائة سنة، إذا كان عقله زائلًا، سواء سمي جنونًا، أو عتهًا فلا تكليف عليه، وهكذا كبير السن إذا زال عقله، إذا كبرت سن الإنسان حتى خرف، وزال عقله ارتفع عنه التكليف، سواءً كان رجلًا أو امرأة ... بسبب اختلال العقل لكبر السن، وفق الله الجميع. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9191/سن-التكليف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_366/36607.mp3","categories":["أصول الفقه"]},{"id":11350,"question":"يسأل عن الاجتهاد سماحة الشيخ، فيقول: ما هي الشروط الواجب توفرها في المجتهد، وما هي مراتب الاجتهاد؟ جزاكم الله خيرًا.","title":"تعريف المجتهد، والشروط الواجب توافرها في المجتهد","answer":"الجواب:  المجتهد هو الذي عنده العلم بما يجتهد فيه، المعلومات الكافية في أحكام البيع والشراء، في أحكام النكاح، في أحكام الطلاق وفي غير ذلك، في العقيدة فيتكلم عن علم وبصيرة فيقال له: مجتهد، الذي عنده معرفة بالأدلة الشرعية يقال له: مجتهد، يجتهد في معرفة الأحكام بالأدلة الشرعية هذا هو المجتهد، بخلاف الذي لا يعرف وإنما يأخذ كلام العلماء فهذا يقال له: مقلد، يأخذ كلام العلماء ويتكلم فهذا يسمى مقلدًا. أما الذي يعرف الأدلة قال الله قال رسوله عنده علم وعنده بصيرة فهذا هو المجتهد، نعم. المقدم: بارك الله فيكم، وجزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/9527/تعريف-المجتهد-والشروط-الواجب-توافرها-في-المجتهد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_378/37804.mp3","categories":["أصول الفقه"]},{"id":11394,"question":"السائل أشرف محمد يقول في هذا  سمعت من بعض إخواني يتحدثون عن الناسخ والمنسوخ في القرآن، فما هو الناسخ، وما هو المنسوخ؟ جزاكم الله خيرًا.","title":"معنى الناسخ والمنسوخ في نصوص الشرع","answer":"الجواب:  الناسخ الحكم الأخير، والمنسوخ الحكم الأول، فالمنسوخ من أمثلة ذلك: كان الناس يستقبلون بيت المقدس في الصلاة حتى هاجر النبي ﷺ ومضى عليه ستة عشر شهرًا، أو سبعة عشر شهرًا، ثم أنزل الله الناسخ، وهو قوله -جل وعلا-: قَدْ نَرَى تَقَلُّبَ وَجْهِكَ فِي السَّمَاءِ فَلَنُوَلِّيَنَّكَ قِبْلَةً تَرْضَاهَا فَوَلِّ وَجْهَكَ شَطْرَ الْمَسْجِدِ الْحَرَامِ وَحَيْثُ مَا كُنتُمْ فَوَلُّوا وُجُوهَكُمْ شَطْرَهُ [البقرة:144]، فهذا هو الناسخ لما كانوا يفعلون من استقبال بيت المقدس، أنهم أمروا أن يستقبلوا الكعبة أينما كانوا، نعم.  المقدم: بارك الله فيكم.","link":"https://binbaz.org.sa/fatwas/9569/معنى-الناسخ-والمنسوخ-في-نصوص-الشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_293/29314.mp3","categories":["أصول الفقه"]},{"id":11466,"question":"كيف يحاسب الإنسان على أمور لا يملكها، مثل الكره والحب، والحسد، وما إلى ذلك؟","title":"حكم من أكره على فعل محرم","answer":"الجواب:  لا يُكَلِّفُ اللَّهُ نَفْسًا إِلَّا وُسْعَهَا [البقرة:286]، فَاتَّقُوا اللَّهَ مَا اسْتَطَعْتُمْ [التغابن:16]، الشيء الذي فعله مكرهًا إكراهًا شرعيًا، يعني: أكره بالقوة مع طمأنينة قلبه بالإيمان، أكره على شرب الخمر، أكره على الكفر بالضرب، والوعيد من قادر على فعله، من يغلب على ظنه أنه يفعل؛ لا يضره ذلك، إذا كان قلبه مطمئنًا بالإيمان، ثابت على الحق لقول الله سبحانه مَنْ كَفَرَ بِاللَّهِ مِنْ بَعْدِ إِيمَانِهِ إِلَّا مَنْ أُكْرِهَ وَقَلْبُهُ مُطْمَئِنٌّ بِالإِيمَانِ [النحل:106]. فلو أكره على أن يسب الدين، أو يسب الرسول ﷺ بالضرب، أو بالوعيد بالقتل، يظن أن المكره يفعله، فإنه عذر أن يتكلم، ولكن مع ثبات القلب على الإيمان، مع إيمانه بقلبه أنه على الحق، وأن هذا الإكراه هو الذي حمله على ما .... فهو قاله باللسان دون القلب. وهكذا لو أكره على شرب الخمر، صب في فمه، أو أعطي إياه قال: إما أن تشرب، وإلا ضربناك، أو قتلناك، يكون الإثم عليهم، ولا عليه شيء إذا كان قلبه مطمئن بتحريمه، وأنه إنما فعله من أجل دفع الشر، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9647/حكم-من-اكره-على-فعل-محرم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_381/38121.mp3","categories":["أصول الفقه"]},{"id":11674,"question":"إذا استفتى الإنسان، وأفتي هل يجب عليه الرضا بما سمع من تلكم الفتوى، أم لكم توجيه آخر شيخ عبدالعزيز؟","title":"ضابط قبول فتوى المفتي والرضا بها","answer":"الجواب:  عليه التثبت إذا استفتى، إذا كان المفتي من أهل الفتوى من المعروفين بالعلم والفضل والبصيرة؛ فالحمد لله يقنع، أما إذا كان عنده شك في المفتي، هل هو أهل، أو ليس بأهل؟! فلا يعجل حتى يسأل غيره من المفتين الذين يطمئن إليهم المستفتي، لعلمهم وفضلهم، ولا يستفتي من هب ودب، لا يستفتي إلا من عرف بالعلم والفضل والإفتاء في مثل ما يسأل عنه. نعم.  المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/9857/ضابط-قبول-فتوى-المفتي-والرضا-بها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_390/39006.mp3","categories":["أصول الفقه"]},{"id":12127,"question":"تقول: أسمع في بعض الفتاوى بعض علمائنا يقولون: هذا حرام، وبعضهم يقول: لا يجوز، فهل هناك فرق بين اللفظين؟","title":"الفرق بين مصطلاح (حرام) و(لا يجوز)","answer":"الجواب: لا فرق بينهما، لا يجوز، أو حرام، كله معناه واحد، لا يجوز أو منكر أو حرام المعنى متقارب واحد، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10312/الفرق-بين-مصطلاح-حرام-ولا-يجوز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_438/43812.mp3","categories":["أصول الفقه"]},{"id":12410,"question":"سماحة الشيخ! هناك أناس يأخذون بعض الأحاديث، ولا يلتفتون إلى البعض الآخر، وأيضًا يفعلون ذلك حتى في الآيات القرآنية، هل من كلمة حول هذا الموضوع؟","title":"حكم الأخذ ببعض الآيات والأحاديث وترك البعض الآخر","answer":"الجواب:  هذا من الجهل، لا يجوز ضرب كتاب الله بعضه ببعض، ولا ضرب السنة بعضها ببعض، لابد أن ينظر في النصوص كلها، ويجمع بين الوارد في المسألة من الكتاب والسنة؛ حتى يكون الحكم على بينة، وعلى وضوح في الأدلة الشرعية. أما الجاهل الذي يأخذ دليلًا، ويدع دليلًا، أو يحتج بآية، ويضيع آية في المعنى، أو حديثًا في المعنى، هذا غلط، من القول على الله بغير علم، لابد أن المفتي والحاكم يتتبع الأدلة، ويجمع بين الأدلة؛ حتى يأخذ حكم المسألة منها جميعًا؛ لأن الأحاديث يفسر بعضها بعضًا. وهكذا الآيات يفسر بعضها بعضًا، ويشهد بعضها لبعض؛ فلا بد من جمع بين الأدلة في المسائل التي قد تشتبه، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10617/حكم-الاخذ-ببعض-الايات-والاحاديث-وترك-البعض-الاخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_402/40205.mp3","categories":["أصول الفقه"]},{"id":12762,"question":"هل يجوز أن أفتي الناس بما أسمعه من فتاوى عبر برنامج نور على الدرب؟","title":"حكم من أفتى بما سمعه من برنامج نور على الدرب","answer":"الجواب:  نعم لك أن تفتي الناس بما سمعته وأنت ضابط له، تقول: عن فلان، تنسبه إلى صاحبه، ما هو بعنك، تقول: سمعته في برنامج من كلام فلان، أن الحكم كذا وكذا، هذا من باب التبليغ \"تبليغ العلم\" إذا كنت ضابطًا لما سمعت، أما إذا كنت عند شك؛ فلا، لكن إذا ضبطت الكلام، وحفظته جيدًا، فتنقله إلى غيرك تقول: سمعت فلانًا في نور على الدرب، عني، أو عن مثل الشيخ صالح الفوزان، الشيخ عبدالله بن غديان، الشيخ محمد بن عثيمين، الشيخ صالح الفوزان؛ تنقل عنه الشيخ صالح بن غصون، لا تنسب لنفسك، تنقل عنهم كما سمعت حرفًا بحرف، لا تزد، ولا تنقص، ولا تغير شيئًا، وأنت مشكور، ومأجور. أما أن تنقل، ولا تنسب لا؛ لأنهم قد لا يثقون بك، وقد تزيد، أو تنقص، لكن انقل عن العالم نفسه الذي سمعت كلمته، تنقلها بحروفها؛ لعل الله ينفع بها، نعم. المقدم: اللهم آمين، جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10976/حكم-من-افتى-بما-سمعه-من-برنامج-نور-على-الدرب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41911.mp3","categories":["أصول الفقه"]},{"id":13122,"question":"هل يمكن أن أختار أحد العلماء الأربعة مثلًا المشهورين لكي أعمل على طريقتهم دون الآخرين، وأقرأ له لكي أتمكن من التطبيق فعلًا؟","title":"حكم تقليد عالم من العلماء مطلقًا كأحد الأئمة الأربعة","answer":"الجواب:  ليس لك أن تقلد واحدًا مطلقًا، بل عليك أن تسأل أهل العلم عما أشكل عليك، والتقليد لا يجوز، بل يجب على طالب العلم أن ينظر في الأدلة الشرعية، ويختار ما تقتضيه الأدلة، سواء وافق الأئمة الأربعة، أو لم يوافقهم. وإذا كان عاميًا؛ فإنه لا يقلد أحدًا من هؤلاء، بل يسأل أهل العلم في زمانه، أهل العلم بالسنة، أهل البصيرة، يسألهم عما أشكل عليه، ويعمل بما يفتى به؛ لأن مثله لا يعرف يميز بين الصحيح والسقيم من أقوال العلماء، لا يعرف الحق من الباطل، فالعامي يحتاج إلى من يقوده إلى الحق، ويدله عليه من علماء السنة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11345/حكم-تقليد-عالم-من-العلماء-مطلقا-كاحد-الاىمة-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_473/47317.mp3","categories":["أصول الفقه"]},{"id":13187,"question":"على بركة الله نبدأ هذا اللقاء بسؤال من أحد الإخوة المستمعين يقول في هذا  قال رسول الله ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد وقال أيضًا: عليكم بسنتي وسنة الخلفاء الراشدين من بعدي وقد كان في زمان الخليفة عثمان  أذان واحد، ثم زاد الأذان الثاني لصلاة الجمعة، هل هذه الزيادة تعتبر من البدع، أم من السنة؟ وما هي البدع؟ وما هي أقسامها مأجورين؟","title":"الحث على اتباع سنة الخلفاء الراشدين","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذه الأحاديث التي ذكرها السائل أحاديث صحيحة، يقول النبي ﷺ: من أحدث في أمرنا هذا ما ليس منه؛ فهو رد متفق على صحته من حديث عائشة -رضي الله عنها- وفي لفظ: يقول ﷺ: من عمل عملًا ليس عليه أمرنا؛ فهو رد أخرجه مسلم في صحيحه، ويقول ﷺ: إياكم ومحدثات الأمور، فإن كل محدثة بدعة، وكل بدعة ضلالة. والبدعة: هي التي يحدثها الناس في الإسلام في الطاعات والقربات، يقال لها: بدعة، ما أحدثه الناس في التعبد يقال له: بدعة، مثل: بدعة الاحتفال بالمولد، مثل: بدعة البناء على القبور، واتخاذ المساجد على القبور والقباب، وما أشبه ذلك مما يحدثه الناس، ومعنى الرد: يعني: مردود. لكن ما فعله عثمان من الأذان الثاني في خلافته، ليس من البدع؛ لأن الرسول ﷺ قال: عليكم بسنتي وسنة الخلفاء الراشدين المهديين من بعدي وهو من الخلفاء الراشدين، وقد أحدث الأذان الثاني، وهو الأول للمصلحة، لمصلحة المسلمين حتى ينتبهوا للجمعة، ولهذا أقره الصحابة في زمانه، وعمل به المسلمون بعده؛ لأنه داخل في قوله ﷺ: عليكم بسنتي، وسنة الخلفاء الراشدين المهديين من بعدي، تمسكوا بها، وعضوا عليها بالنواجذ. وهكذا ما فعل في عهده من جمع المصحف، كان الناس يحفظون القرآن في صدورهم، وفي زمانه؛ خافوا على الناس أن يضيع منهم القرآن، فاجتمع رأي من الصحابة على أنه يكتب في المصاحف؛ حتى يبقى بين أيدي المسلمين، وحتى يحفظ، وكان هذا من الأعمال الطيبة التي وفق الله الصحابة لها. وهكذا ما فعله عمر  من جمع الناس على إمام واحد في التراويح في رمضان، وكانوا في عهد النبي ﷺ يصلون أوزاعًا في المسجد، كل يصلي لنفسه، أو يصلي مع اثنين، أو ثلاثة، أو أربعة، أو أكثر، ثم جمعهم عمر على إمام واحد؛ لأنه رأى أن هذا أولى من تفرقهم، وتأسى بالنبي ﷺ حين صلى بالناس في رمضان عدة ليالي جماعة في رمضان، ثم قال: أخاف أن تفرض عليكم صلاة الليل، فأمرهم أن يصلوا في بيوتهم. فلما توفي النبي ﷺ انقطع الوحي، وأمن فرضها؛ فلهذا جمعهم عمر، وصارت سنة أولية جمع الناس على إمام واحد في رمضان في التراويح، والقيام، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11442/الحث-على-اتباع-سنة-الخلفاء-الراشدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_512/51201.mp3","categories":["البدع والمحدثات","أصول الفقه"]},{"id":13249,"question":"هل الصحيح رفع اليدين في كل تكبيرة في صلاة الجنازة، أم يكبر بدون رفع اليدين، وكذلك في صلاة العيدين؟","title":"حكم رفع اليدين في تكبيرات صلاتي الجنازة والعيدين","answer":"الجواب:  الأفضل الرفع، وإن لم يرفع؛ فلا بأس، والأفضل الرفع؛ لأن الرسول ﷺ كان يرفع في تكبيرات الجنازة، ومثلها تكبيرات العيد، السنة الرفع؛ لأنها تكبير عن قيام، فأشبه تكبير الاستفتاح، وتكبير الركوع، يرفع في الصلوات كلها، إذا كبر رفع، وإذا كبر للركوع رفع، فالأفضل في التكبير للجنازة أن يرفع، وبعض أهل العلم قال: يرفع في الأولى فقط.  والصواب: أن الأفضل يرفع في الجميع في جميع تكبيرات الجنازة، وتكبيرات العيد. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11534/حكم-رفع-اليدين-في-تكبيرات-صلاتي-الجنازة-والعيدين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_513/51314.mp3","categories":["أصول الفقه","صلاة العيدين","الصلاة على الميت"]},{"id":13372,"question":"له سؤال ثانٍ علي مطلق من الكويت يقول: سماحة الشيخ! نسمع كثيرًا ممن يتكلم فيقول: لابد من العالم أن يكون عنده فقه بالواقع؛ لكي يفتي، والحقيقة -يا سماحة الشيخ- بأنه أصبح عندي تناقض؛ لأن الدين ثابت على مر الأزمان؛ لأنه دين سماوي من رب العالمين، فهل هذا الكلام صحيح شرعًا؟ وجهونا في ضوء هذا السؤال مأجورين.","title":"علاقة الفتوى بفقه الواقع","answer":"الجواب: هذا فيه تفصيل، الواجب على المفتي أن يعرف موضع الفتوى، ولا يفتي إلا على بصيرة، حتى يطبق الحكم على الواقع، وهكذا شأن العلماء عندما يفتون إذا عرفوا الواقع، فإذا سأله سائل عن الطلاق يستفصل: كيف الطلاق؟ كيف وقع الطلاق طلقة أو طلقتين؟ وكيف حال المرأة، هل كانت في حيض أو نفاس؟ يستفصل حتى يطبق أحكام الله كما شرع الله، لابد أن يكون عنده بصيرة، وإذا سأله السائل قال: إنسان قتل آخر. يستفصل كيف قتله؟ قصاصًا، أو دفاعًا عن نفسه.. صال عليه؟ كيف قتله؟ إن كان دفاعًا عن نفسه، قد صال عليه، ودافعه، لم يستطع السلامة إلا بدفعه عن النفس ما يضمنه؛ لأن الصائل يدفع بالأسهل فالأسهل، إن كان قتله في حد مع القاتلين مثل: الزاني، فأمر ولي الأمر بإقامة الحد عليه، فقتله مع الناس، فرجمه مع الناس، هذا معذور، مشروع ما عليه شيء، رجمه مع الناس بإقامة الحد. سئل عن النفقة: كيف النفقة على الزوجة والأولاد؟ يسأل: كم الأولاد؟ وايش عادة البلاد؛ حتى يعلم بالنفقة، يخبرهم بالنفقة الواجبة، ينفق عليها النفقة المعروفة بالمعروف، حتى يعطيهم الحجة واضحة، والفتوى واضحة، يعتمد على الدليل، ويستفصل حتى تكون الفتوى في محلها. كذلك السلم، إذا أراد أن يسلم في شيء؛ يسأل، فلابد يكون مضبوط السلم، إن كان في طعام؛ يكون شيئًا معلومًا، وشيئًا مضبوطًا، حبًا .. رزًا .. شعيرًا يكون مضبوطًا، يفهم الواقع، وايش هو؟ سأله عن القصاص مثلاً: القصاص في اليد .. القصاص في الرجل، كيف محل القصاص؟ القصاص في الأصبع، القصاص في الشجة، في الرأس، يبين كيف القصاص على ما بين أهل العلم، يوضح لهم حتى تكون الفتوى على طبق الواقع. وهكذا فعل العلماء يفهمون الواقع، هذا شيء تحصيل حاصل، المفتي هكذا يكون، من عهد الصحابة إلى يومنا هذا، المفتي لابد يعرف موضع الفتوى، ويكون على بصيرة في الفتوى، حتى لا تقع الفتوى في غير محلها، لا يتسرع في الفتوى على غير بصيرة، لابد يعرف السؤال، ويكون على بصيرة في السؤال، ومحل السؤال؛ حتى تكون الفتوى مطابقة للواقع. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ على هذا التوجيه المبارك.","link":"https://binbaz.org.sa/fatwas/11661/علاقة-الفتوى-بفقه-الواقع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_515/51505.mp3","categories":["أصول الفقه"]},{"id":13390,"question":"هذا السائل الذي رمز لاسمه بـ (م. ص. ش) يمني من جدة، مقيم في المملكة العربية السعودية، يقول: هل المذاهب الأربعة المعروفة تأخذ بالسنة النبوية، وهل جميع ما جاء فيها مطابق للسنة النبوية الشريفة؟ وجهونا في ضوء هذا السؤال سماحة الشيخ.","title":"هل المذاهب الأربعة تأخذ بالسنة؟","answer":"الجواب: الأئمة الأربعة من خيرة العلماء -رحمة الله عليهم- وهم أبو حنيفة النعمان بن ثابت، ومالك بن أنس، ومحمد بن إدريس الشافعي، وأحمد بن محمد بن حنبل، هؤلاء الأربعة هم الأئمة الأربعة، وهناك أئمة آخرون في زمانهم، وقبلهم وبعدهم، كالأوزاعي، وسفيان الثوري، وسفيان بن عيينة، وعبدالله بن المبارك .. وغيرهم من أئمة الإسلام؛ يحيى بن سعيد القطان، عبدالرحمن بن مهدي، وإسحاق بن راهويه .. وغيرهم، هم أئمة يتلمسون الحق، ويتلمسون السنة، يعتنون بذلك، وفتاواهم مدارها على الكتاب والسنة، قال الله وقال رسوله، ويتحرون الأصول التي دل عليها الكتاب والسنة، وعلى ما ثبت عن الصحابة  من الفتاوى، فمدار فتاواهم على القرآن العظيم، والسنة المطهرة، والأصول المستنبطة من الكتاب والسنة، وعلى فتاوى الصحابة -رضي الله عنهم وأرضاهم- وكل واحد يخطئ ويصيب، ليس أحد منهم معصومًا، كل واحد يخطئ ويصيب، كل واحد له أخطاء، له أغلاط لم تطابق السنة، وهكذا غيرهم من الأئمة له أخطاء، وله صواب. فالواجب عرض أقوالهم إذا اختلفوا على الكتاب والسنة، أما إذا أجمع العلماء؛ فالإجماع حجة، والإجماع لا يكون إلا عن نص، فإذا اختلفوا؛ فالواجب على طالب العلم، وعلى الفقيه أن يعرض المسألة المختلف فيها على الأدلة الشرعية، وأن يجتهد، ويتحرى ما يقوم عليه الدليل؛ فيأخذ به، عليه أن يتحرى ما يرجحه الدليل من القرآن العظيم، والسنة المطهرة، أو من فتاوى الصحابة؛ حتى يطمئن إلى أرجح القولين، أو أرجح الأقوال، ثم يأخذ به. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11680/هل-المذاهب-الاربعة-تاخذ-بالسنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_525/52510.mp3","categories":["أصول الفقه"]},{"id":13463,"question":"سماحة الشيخ! تساهل بعض الناس بالفتوى بغير علم، هل من كلمة توجيهية؟","title":"نصيحة للمتساهلين في الفتوى بغير علم","answer":"الجواب: نعم، لا يجوز لأي مسلم أن يتساهل بالفتوى، يجب أن يتحرى الحق، وأن يكون عنده أهلية لهذا الأمر، وإلا فليمسك ولا يقول على الله بغير علم، الله يقول سبحانه: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [الأعراف:33] جعله في القمة، القول على الله بغير علم فوق الشرك؛ لعظم الخطر. وقال عن الشيطان: إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ [البقرة:169]، الشيطان يأمرنا أن نقول على الله بغير علم، فالواجب الحذر من ذلك. لا يجوز للمسلم أن يفتي بغير علم، بل لابد أن يكون عنده علم وبصيرة بما قاله الله ورسوله، وإلا فليسأل، يسأل أهل العلم، نعم.  المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11766/نصيحة-للمتساهلين-في-الفتوى-بغير-علم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_517/51711.mp3","categories":["أصول الفقه"]},{"id":13532,"question":"السائلة أم عثمان من اليمن تقول في هذا  سماحة الشيخ! إذا تعارضت أقوال الأئمة في مسألة ما، كاختلاف الأئمة مثلًا في زكاة الحلي، فالبعض يوجب زكاة الحلي مطلقًا، الملبوس والمكنوز والمستعمل وغير ذلك، والبعض يوجب زكاة الحلي المكنوز فقط دون المستعمل، فبأيهما نأخذ يا سماحة الشيخ، بالأحوط أم بالأيسر، أو يكون لنا الخيار؛ لأن البعض يقول: يجب أن نأخذ بالأحوط اتقاء الشبهة، والبعض من الناس يقول: نأخذ بالأيسر؛ لأن الله يريد بنا اليسر، ولا يريد منا العسر. وجهونا في ضوء هذا السؤال الذي اختلف على كثير من الناس سماحة الشيخ عبدالعزيز .","title":"هل يؤخذ في زكاة الحلي بالأحوط أم الأيسر؟","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فهذه المسألة وأشباهها من مسائل الخلاف بين العلماء، الواجب عرضها على الكتاب والسنة، والحكم فيها بالدليل؛ لقول الله -جل وعلا-: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ[الشورى:10] ولقوله : فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِنْ كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الآخِرِ ذَلِكَ خَيْرٌ وَأَحْسَنُ تَأْوِيلًا [النساء:59]. فالواجب على أهل العلم أن يردوا مسائل النزاع إلى الأدلة الشرعية، وإذا كان المكلف قد خفي عليه الأمر، ولم تتضح له الأدلة؛ فإنه يأخذ بالأحوط، والأبعد عن الشبهة؛ لقوله ﷺ: دع ما يريبك إلى ما لا يريبك .. من اتقى الشبهات؛ فقد استبرأ لدينه وعرضه. العامي وهو من تشتبه عليه الأدلة يأخذ بالأحوط، وهو ترك المشتبه، والاستبراء لدينه؛ لهذين الحديثين: دع ما يريبك إلى ما لا يريبك والحديث الثاني: من اتقى الشبهات؛ فقد استبرأ لدينه وعرضه. وهذه المسألة -مسألة الحلي- الصواب فيها: أن فيها الزكاة؛ لأنه جاء فيها نص يدل على وجوب الزكاة في الحلي من الذهب والفضة، سواء كانت تستعمل، أم لا تستعمل، الحكم واحد؛ لأنه ﷺ قال لامرأة عليها بعض الحلي: أتؤدين زكاة هذا؟ قالت: لا، قال: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟ فألقتهما وقالت: هما لله ولرسوله، فأخبر أنها إذا لم تزك؛ فهي معرضة للنار. وقالت أم سلمة وعليها أوضاح من ذهب: يا رسول الله! أكنز هذا؟ قال ﷺ: ما أديت زكاته فليس بكنز فدل على أن الحلي كنز إذا لم تؤد زكاته، وهذا إشارة إلى قوله -جل وعلا-: يا أَيُّهَا الَّذِينَ آمَنُوا إِنَّ كَثِيرًا مِنَ الأَحْبَارِ وَالرُّهْبَانِ لَيَأْكُلُونَ أَمْوَالَ النَّاسِ بِالْبَاطِلِ وَيَصُدُّونَ عَنْ سَبِيلِ اللَّهِ وَالَّذِينَ يَكْنِزُونَ الذَّهَبَ وَالْفِضَّةَ وَلا يُنفِقُونَهَا فِي سَبِيلِ اللَّهِ فَبَشِّرْهُمْ بِعَذَابٍ أَلِيمٍ [التوبة:34]. الحديث يدل على أنها كنز لا بد أن تؤدى زكاته، فالحلي التي تبلغ النصاب من الذهب والفضة إذا لم تؤد زكاته؛ فهو كنز، هذا هو الأرجح من قولي العلماء في هذه المسألة أن الحلي من الذهب والفضة، سواء كان أسورة، أو كانت قلائد، أو غير ذلك إذا بلغ النصاب إحدى عشر جنيهًا، ونص من الذهب؛ هذا فيه الزكاة، وهو عشرون مثقالًا، أو من الفضة بلغ مائة وأربعين مثقالًا، ستة وخمسين ريالًا فضة، يعني: فضة غير العملة الورقية، إذا بلغ قيمة ستة وخمسين من الفضة، هذا نصاب من الفضة. والحاصل: أنه إذا بلغ الذهب والفضة نصابًا؛ وجب فيه الزكاة وإن كان حليًا تلبس، هذا هو الأرجح من قولي العلماء. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11848/هل-يوخذ-في-زكاة-الحلي-بالاحوط-ام-الايسر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53201.mp3","categories":["زكاة النقدين","أصول الفقه"]},{"id":13623,"question":"في آخر أسئلة هذا السائل يقول: سماحة الشيخ! ما هي الشروط الواجبة للاجتهاد الشرعي؟","title":"شروط الاجتهاد الشرعي","answer":"الجواب: لابد أن يكون ذا علم وبصيرة، يستطيع أن يجتهد، يكون عنده علم بالأدلة الشرعية... علم القرآن والسنة، والعلم بأقوال العلماء، يكون عنده بصيرة، وعنده علم حتى يستطيع يرجح الراجح، ويزيف الزائف، لابد أن يكون عنده علم وبصيرة ... بصير ينظر، أو يطالع الكتب، يقرأ عليه من ينظر، ويسمع الكتب .. ويسمع الأحاديث .. يسمع كلام العلماء .. يتدبر القرآن، يكون عنده آلة .. عنده علم .. عنده علم بأصول الفقه، ومصطلح الحديث .. عنده علم بالأحاديث .. بالمطالعة، وبالحفظ، وتدبر القرآن حتى يفهم الراجح من المرجوح. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11973/شروط-الاجتهاد-الشرعي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_534/53406.mp3","categories":["أصول الفقه"]},{"id":13659,"question":"تقول السائلة: هل يجوز أن تفتي المرأة إذا ما سئلت عن فتوى قد سمعتها، أو قرأتها؟","title":"حكم إفتاء المرأة بما سمعت أو قرأت","answer":"الجواب: نعم، إذا كان عندها علم تفتي، كان أزواج النبي ﷺ يفتين -رضي الله عنهن- وهكذا جملة من الصحابيات، ومن أهل العلم بعد الصحابة، إذا كان عندها علم من كتاب الله، وسنة رسوله ﷺ تفتي، تعلم الناس، أو تنقل لهم من فتوى. تقول: أفتاني فلان، أو سمعت في الإذاعة في برنامج نور على الدرب كذا، إذا كانت حافظة للشيء تنقل لهم ما سمعت، أو من كتاب معروف من كتب أهل السنة، عرفت معناه، وهي طالبة علم عرفت بالمعنى، تنقل ما عرفت من المعنى لغيرها، كل هذا من باب التعاون على البر والتقوى، كل هذا من باب أيضًا نقل العلم، والتواصي بالحق. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11993/حكم-افتاء-المراة-بما-سمعت-او-قرات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_529/52902.mp3","categories":["أصول الفقه","قضايا المرأة"]},{"id":13727,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة وقع في نهايتها أبو عبدالعزيز عبدالله، يسأل ويقول: هل يجوز أن أقول مثلًا: أنا على المذهب الشافعي، أو الحنفي، أو غير ذلك؟","title":"حكم التمذهب بمذهب من المذاهب الأربعة","answer":"الجواب: نعم إذا كان يعني: يسير على منهج هذا المذهب وقد درس في كتبه، وعلى أهله، وصار يسير على هذا المذهب، لا بأس أن يقول: أنا على المذهب الشافعي، أو الحنبلي، أو المالكي، أو يرى أن هذا المذهب أصوله وما سار عليه أقرب إليه ويرجحها؛ فلا بأس أن ينتسب إليه، إما لكونه عاش على تعليم أهله من المشايخ والعلماء، أو لأنه رأى أن هذا المذهب أصوله وما بني عليه المذهب أنها أقرب إلى الحق، فسار عليه؛ فلا بأس أن ينتسب إليه، لكن لا يجوز له أن يتعصب ويقول: إن الحق معهم لا مع غيرهم، ولو خالفوا الدليل لا، ما يتعصب، عليه أن يتبع الدليل. فإذا كان الدليل مع غيرهم؛ وجب عليه الانتقال من مذهبه إلى المذهب الآخر الذي معه الدليل، ولا يجوز أن يتعصب لمذهبه في الحق والباطل، أما الانتساب إليه إذا كان يسير على أصوله، أو درس على مشايخ، وصار يسير على ما قالوا له، فلا بأس أن ينتسب إليه، لكن لا يجوز له أبدًا أن يتعصب له، ويقول: إنها على الحق مطلقًا، أو ينكر على من خالفه، أو يترك الدليل لأجله، كل هذا لا يجوز، بل لا بأس أن ينتسب إليه، ولكنه متى ظهر له الحق متى بان له الحق اتبع الحق، وترك المذهب. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12098/حكم-التمذهب-بمذهب-من-المذاهب-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48113.mp3","categories":["أصول الفقه"]},{"id":13736,"question":"يقول: ما حكم الاختلاف في بعض المسائل الفقهية؟ مع العلم أن هذه المسائل تسبب مشاكل كثيرة؟ أفيدونا جزاكم الله خيرًا.","title":"حكم الاختلاف في مسائل الفقهية؟","answer":"الجواب: ينبغي لأهل العلم الجد في التقارب، والاتفاق، والحرص على عدم الخلاف بأن كل واحد يجتهد؛ حتى يعرف الحق بدليله، وحتى يستقيموا على الدليل، ويتفقوا عليه؛ حتى لا يكون بينهم خلاف مهما أمكن.... الواجب على العلماء أن يحرصوا كثيرًا على جمع الكلمة، وأن تكون الكلمة واحدة؛ حتى لا يلتبس الأمر على العامة. أما لو لم يتيسر ذلك؛ لأن هذا يرى أن الحق معه، وهذا يرى أن الحق معه، فإن المؤمن يجتهد، ويتبع من هو أولى بالحق عنده، من هو أقرب إلى الورع والعلم، فإذا اشتبهت عليه الأمور يقلد من هو أقرب عنده إلى العلم، والفضل، والورع، والعلم بالدليل، يقلده؛ لأن العامي شيخه هو مذهبه، فالعامي يسأل ويتبصر، وإذا اشتبه عليه الأمر، واختلف عليه الاثنان، أو أكثر؛ اعتنى بمن هو أقرب إلى الصواب في اعتقاده، فعمل بقوله. نعم.. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12108/حكم-الاختلاف-في-مساىل-الفقهية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48117.mp3","categories":["أصول الفقه"]},{"id":13879,"question":"السائل يقول: عندي أخت من أمي مرضت عند ولادتها حيث إنها أصبحت لا تأكل مثل الناس، ولا تتكلم مع أحد، ودائمًا تفكر في الدنيا مثل الناس، وهي لا تصلي، فماذا علينا تجاهها؟ هل تسقط عنها التكاليف؟","title":"الواجب تجاه من يظهر أنها فقدت عقلها","answer":"الجواب: لا. تعلم وتنصح وتوجه لعلها تهتدي، لعل هذا عارض، توجه وإن كان ثبت أن عقلها معها تؤدب حتى تستقيم حتى تصلي، أما إن ثبت واتضح أن عقلها قد ذهب فرفع عنها القلم، صارت مثل المجانين المرفوع عنهم القلم، لكن يعالج موضوعها، تختبر حتى يتبين أمرها، إن كانت عاقلة تؤدب تضرب حتى تصلي، فإن كانت ليست عاقلة أو اتضح أن عقلها قد ذهب حكمها حكم المجنون والمعتوه، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12274/الواجب-تجاه-من-يظهر-انها-فقدت-عقلها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_506/50609.mp3","categories":["أصول الفقه"]},{"id":14057,"question":"شيخ عبد العزيز ! كثير من إخواننا المستمعين لهذا البرنامج يتمنون أن لا يكون هناك خلاف في الفتاوى بين العلماء، فأختنا أيضًا في رسالتها تقول: إنني سمعت في البرنامج أنه ليس هنالك زكاة على الحلي المعد للزينة، وقال المفتي في تلكم الحلقة: إن هذا معمول به في المملكة، وهنالك كتاب يتحدث عن زكاة الحلي، مستدلًا بأحاديث وآثار صحيحة، وأقوال علماء من الحاضرين، وسؤالي مرة أخرى: هل للحلي المعد للزينة زكاة، وما رأيكم في الكتاب الذي يتحدث عن زكاة الحلي؟ جزاكم الله خيرًا.","title":"أسباب اختلاف العلماء في الفتوى وحكم زكاة الحلي","answer":"الجواب: الاختلاف لا بد منه في بعض المسائل الفرعية، ولا تمكن السلامة من ذلك، فقد كان موجودًا في عهد الصحابة  ومن بعدهم، بسبب اختلاف الفهم، وبسبب خفاء الأدلة على بعض أهل العلم، فلهذا يقع بعض الخلاف؛ فإن بعض أهل العلم قد يبلغه الحديث عن رسول الله ﷺ وقد لا يبلغ الآخر، وكذلك قد يفهم من الآية ومن الحديث فهمًا لم يفهمه الآخر في بعض المسائل، فلهذا تقع الخلافات بين أهل العلم في بعض المسائل الفرعية.\nأما العقائد والأمور الأصولية؛ فالحمد لله ليس فيها خلاف بين أهل العلم، وإنما تقع الخلافات في مسائل فرعية قد يخفى فيها الدليل على بعض أهل العلم، وقد يختلف فيها الفهم، فعلى طالب العلم وعلى السائل وعلى المستفيد أن يتحرى، ويجتهد في الاستيضاح من أهل العلم؛ حتى يطمئن قلبه إلى ما وقع فيه الخلاف، وحتى يعرف الصواب، ومن ذلك: مسألة الخضاب بالسواد -كما تقدم في السؤال السابق-.\nومن ذلك: مسألة الحلي هل فيها زكاة أم لا؟ فإن جماعة من أهل العلم قالوا: ليس فيها زكاة؛ لأنها تستعمل، فأشبهت الإبل التي تستعمل والبقر التي تستعمل وليست سائمة؛ فلا زكاة فيها، وقال آخرون: بل فيها الزكاة؛ لأنها داخلة في عموم الذهب والفضة، الذين أوجب الله فيهما الزكاة؛ ولأنه ليس هناك دليل يخص الحلي باستثنائها من وجوب الزكاة، ولأنه قد ورد في أحاديث تدل على أن الحلي فيها الزكاة، مثلما رواه أبو داود والنسائي بإسناد صحيح عن عبد الله بن عمرو بن العاص رضي الله تعالى عنهما: أن امرأة أتت النبي ﷺ وفي يد ابنتها سواران ضخمان من الذهب، -وفي رواية: مسكتان غليظتان من الذهب- فقال: أتعطين زكاة هذا؟ قالت: لا. قال عليه الصلاة والسلام: أيسرك أن يسورك الله بهما يوم القيامة سوارين من نار؟؛ فألقتهما، قالت: هما لله ولرسوله.\nوثبت من حديث أم سلمة رضي الله عنها أنها كانت تلبس أوضاحًا من ذهب، فقالت: يا رسول الله! أكنز هذا؟ فقال عليه الصلاة والسلام: ما بلغ أن يزكى فزكي؛ فليس بكنز، ولم يقل: ليس عليك فيه زكاة، ولم يقل: ليس في الحلي زكاة؛ فدل ذلك على أن الواجب أداء الزكاة عن الحلي إذا بلغت النصاب، وقد كتبنا في هذا رسالة أوضحنا فيها الأدلة، وكتب بعض أهل العلم في ذلك أيضًا.\nفالمقصود: أن الصواب هو القول بأن الزكاة واجبة في الحلي من الذهب والفضة، إذا بلغت النصاب -وهو عشرون مثقالاً- ومقداره أحد عشر جنيهًا وثلاثة أسباع جنيه من الجنيه السعودي، أحد عشر جنيه وثلاثة أسباع، يعني: نص، أحد عشر جنيه ونص؛ لأن الكسر يسير بين الثلاثة الأسباع والنصف، فالمقصود: أنه إذا بلغ إحدى عشر جنيه ونصفًا؛ فإن الحلي فيه الزكاة، وهو يقارب اثنين وتسعين غرام، فإذا كانت الحلي أقل من ذلك؛ فلا زكاة فيها والحمد لله.\nوالمؤمن يذهب إلى ما هو أحوط لدينه، وأقرب إلى سلامته في كل شيء، إلا إذا وضح الدليل في أن هذا الشيء ليس فيه شيء فالحمد لله، ومادام أن هناك شبهة وهناك خلافًا، ولم يتضح للمؤمن ما يبرئ ذمته؛ فإنه يحتاط، ويأخذ بالفتوى التي فيها السلامة والحيطة، والخلوص من الواجب، والله ولي التوفيق. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12489/اسباب-اختلاف-العلماء-في-الفتوى-وحكم-زكاة-الحلي","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_608/60808.mp3","categories":["زكاة النقدين","أصول الفقه"]},{"id":14143,"question":"ننتقل إلى رسالة السائل الذي رمز لاسمه بـ (أ. أ) يقول: ما الفرق يا سماحة الشيخ بين الجواز والإباحة، وأيهما يأخذ به الإنسان؟","title":"الفرق بين الجواز والإباحة","answer":"الجواب: كلها مترادفة: هذا يجوز، هذا يباح، هذا لا بأس به، هذا لا حرج فيه، كلها معان متقاربة معناها: المباح مستوي الطرفين.. ليس بسنة ولا بواجب ولا بمحرم ولا مكروه، هذا لا بأس به.. هذا مباح.. هذا لا حرج فيه.. هذا يجوز كلها مترادفة. نعم.","link":"https://binbaz.org.sa/fatwas/12584/الفرق-بين-الجواز-والاباحة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_546/54608.mp3","categories":["أصول الفقه"]},{"id":14217,"question":"هذا سائل للبرنامج لم يذكر الاسم في هذه الرسالة وكتب بخطه أو بأسلوبه يقول في سؤاله الأول: سماحة الشيخ! هل يجوز للمسلم أن يأخذ الأحكام الفقهية من جميع المذاهب للأئمة الأربعة؛ مثلًا يأخذ حكم في مسألة فقهية في الصلاة من الشافعي، ويأخذ مسألة أخرى في الصلاة من المذهب الحنبلي أو المالكي أو الحنفي أي: لا يتقيد بمذهب معين، فيأخذ من هذا ما يستطيع القيام به ويأخذ من الآخر كذلك؟ أفتونا مأجورين.","title":"حكم الأخذ من المذاهب الفقهية حسب الهوى","answer":"الجواب: ليس له هذا، بل عليه أن يتحرى الحق ويعمل بالحق، وإذا أشكل عليه يسأل أهل العلم، أما أن يتنقل في المذاهب على هواه لا، يلزمه أن يتحرى الحق، فإذا اتضح له أن الحق ما قاله الشافعي أو مالك أو أحمد أو أبو حنيفة أو غيرهم أخذ بالحق الذي قام عليه الدليل، وإذا أشكل عليه سأل أهل العلم حتى يستقر على عمل مضبوط ما يتنقل ويتلاعب بل يسأل أهل العلم عما أشكل عليه حتى يستقر في قلبه ما هو الأرجح. نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12668/حكم-الاخذ-من-المذاهب-الفقهية-حسب-الهوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_548/54818.mp3","categories":["أصول الفقه"]},{"id":14294,"question":"تقول السائلة: ما الفرق بين المحرم والجائز والمكروه؟","title":"الفرق بين المحرم والجائز والمكروه","answer":"الجواب: المحرم: الممنوع، والجائز: المباح اللي إن شاء فعله وإن شاء تركه، والمكروه: اللي تركه أفضل، هذا المكروه، عدم فعله أفضل هذا يقال له: المكروه، يعني: جاء فيه ما يدل على أن تركه أفضل وأولى.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12756/الفرق-بين-المحرم-والجاىز-والمكروه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_549/54923.mp3","categories":["أصول الفقه"]},{"id":14349,"question":"هذه السائلة تقول سماحة الشيخ: يقول العلماء في كلامهم: درء المفاسد مقدم على جلب المصالح، وغيرها من القواعد، فما المقصود بهذه القواعد؟ ومن هو الذي وضعها؟ هل هو النبي ﷺ أم العلماء استنبطوها؟","title":"معنى قاعدة: (درء المفاسد مقدم على جلب المصالح)","answer":"الجواب: استنبطها العلماء من الأدلة، من الأدلة الشرعية، فكون الإنسان يدرأ المفسدة أعظم من كونه يجلب المصلحة التي يتخيلها ويظنها، فإذا كان اجتماعه بزيد أو بعمرو يترتب عليه شر، فيترك هذا الاجتماع الذي يخشى منه شر، وإن كان يرجو فيه مصلحة بأنه يعطيه فلوسًا، أو يدعو له، أو ما أشبه ذلك، لكن إذا كان يترتب عليه سوء ظن، أنه يظن به شر أن هذا الرجل الذي يحب أن يجتمع به مشهور بالشر، أو بشرب المسكر، أو بتعاطي ما حرم الله من اللواط، أو ما أشبه ذلك، يبتعد عن ما يظن به السوء من أجله.\nوكذلك إذا كان تعاطيه بسلعة معينة يجر عليه شرًا، يبتعد عنها، وهكذا إذا كان ذهابه إلى حارة من الحارات يجر شرًا يبتعد، ولو كان فيها مصلحة.... يزور مريضًا، أو يتصدق على أحد ما دام دخول هذه الحارة داخلها يتهم بالشر والفساد لا يذهب، درء المفسدة مقدم على المصلحة، وهكذا، ما أشبه ذلك.","link":"https://binbaz.org.sa/fatwas/12816/معنى-قاعدة-درء-المفاسد-مقدم-على-جلب-المصالح","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_550/55018.mp3","categories":["أصول الفقه"]},{"id":14922,"question":"المستمع: محمد عبدالله الغامدي، من الدمام، بعث رسالة ضمنها أربعة أسئلة، يسأل في سؤاله الأول يقول: بم تدرك الركعة، الجماعة، الجمعة، صلاة العيد، صلاة الجنازة؟","title":"بم تدرك صلاة الجمعة والجماعة والعيد والجنازة؟","answer":"الجواب: أما صلاة العيد، وصلاة الجمعة، وصلوات الأوقات الخمسة؛ تدرك بركعة، كما قال النبي ﷺ: من أدرك ركعةً من الصلاة فقد أدرك الصلاة والحديث الثاني: من أدرك ركعةً من الجمعة؛ فليضف إليها أخرى، وقد تمت صلاته. أما إذا أدرك أقل من ركعة؛ فإنه لا يدرك الجمعة، يصلي ظهرًا، ولا يدرك فضل الجماعة بذلك، إلا أن يكون معذورًا بمرض، أو شيءٍ آخر حال بينه وبين الحضور للجماعة، بغير اختياره، فله فضل الجماعة لعذره الشرعي، كما قال النبي ﷺ: من مرض أو سافر كتب الله له ما كان يعمل وهو صحيح مقيم يعني: بسبب العذر، وقال -عليه الصلاة والسلام- في غزوة تبوك: إن في المدينة أقوامًا ما سرتم مسيرًا، ولا قطعتم واديًا إلا وهم معكم قالوا: وهم في المدينة؟ قال: وهم في المدينة، حبسهم العذر وفي اللفظ الآخر: إلا شركوكم في الأجر فالمعذور حكمه حكم الحاضر في الأجر. أما إن كان تساهل وفرط، فإنه يفوته فضل الجماعة، وعليه أن يصلي في بيته، أو في المسجد الصلاة التي فاتته، نعم. أما الجنازة فتدرك ولو بالتكبيرة الأخيرة، إذا أدرك التكبيرة الأخيرة يكبرها، ويقرأ الفاتحة، ثم يكبر، ويصلي على النبي، وهو مستعجل، اللهم صل على رسول الله، ثم يكبر ويقول: اللهم اغفر له، ثم يكبر ويسلم، قبل أن ترفع بسرعة، نعم. المقدم: جزاكم الله خيرًا، والركعة بم تدرك لو تكرمتم؟ الشيخ: بالركوع، إذا أدرك الركوع فقد أدرك الركعة، وسقطت عنه الفاتحة؛ لأنه لم يدرك القيام، ويدل على هذا أنه ﷺ لما دخل أبو بكرة، وهو راكع -عليه الصلاة والسلام- ركع دون الصف، ثم دخل في الصف، فلما سلم النبي ﷺ قال له: زادك الله حرصًا، ولا تعد لا تعد للركوع دون الصف، يعني: ولم يأمره بقضاء الركعة، اللهم صل عليه، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13415/بم-تدرك-صلاة-الجمعة-والجماعة-والعيد-والجنازة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_640/nour_64005.mp3","categories":["أصول الفقه","صلاة العيدين","الصلاة على الميت"]},{"id":15396,"question":"السائلة أختكم في الله (مريم . م) من المملكة العربية السعودية، تقول سماحة الشيخ: ما الفرق بين الصحيح والجائز، فبعض الأحكام يقولون بأنها جائزة والبعض بأنه صحيح؟ ما الفرق بين ذلك؟","title":"الفرق بين الصحيح والجائز","answer":"الجواب: الصحيح ضد الفاسد، كأن يقال: هذا البيع صحيح أو فاسد، والجائز معناه: غير محرم، الجائز ليس بمحرم، كأن يقال: بيع كذا، بيع طعام بالشروط الشرعية، بيع الأرض بالشروط الشرعية جائز، أما بيع ما حرمه الله كبيع الخمر فإنه غير جائز، بيع الدخان غير جائز، فالجائز ضد المحرم.  أما الصحيح ضد الباطل، ضد الفاسد يعني، يقال: هذا العقد صحيح، هذا العقد فاسد وهكذا، مثلًا: باعه بيعًا فيه غرر يقول: هذا بيع فاسد، باع بيعًا صحيحًا يقول: هذا بيع جائز طيب، تامة شروطه، جائز صحيح، نعم.","link":"https://binbaz.org.sa/fatwas/13897/الفرق-بين-الصحيح-والجاىز","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_567/56719.mp3","categories":["أصول الفقه"]},{"id":15474,"question":"السائل (ن. س. القحطاني) يقول في سؤاله: يقول البعض من الناس بأن الواجب موجود فقط في القرآن، وأن ما قال الرسول ﷺ سنة فقط ليست إلزامية، ماذا نرد عليهم يا سماحة الشيخ؟","title":"هل الوجوب يأخذ من السنة؟","answer":"الجواب: الوجوب والسنة تؤخذ من كلام الرسول ﷺ، ومن كلام الله -جل وعلا-؛ لأن الله يقول: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] ويقول -جل وعلا-: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80] ويقول: وَأَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ [المائدة:92] فما أوجبه الرسول ﷺ وإن لم يأت في القرآن وجب الأخذ به، مثل قوله ﷺ: لا يجمع بين المرأة وعمتها هذا ما هو في القرآن لا يجمع بين المرأة وعمتها، ولا بين المرأة وخالتها قد أجمع المسلمون على هذا، الذي في القرآن: وَأَنْ تَجْمَعُوا بَيْنَ الأُخْتَيْنِ [النساء:23] فجاءت السنة بالنهي عن الجمع بين المرأة وعمتها، والمرأة وخالتها، وأجمع المسلمون على ذلك، وهكذا كل ما جاء في السنة الصحيحة وجب الأخذ به، وإن لم يذكر في القرآن الكريم. هكذا تحريم كل ذي ناب من السباع، وكل ذي مخلب من الطير، هذا لم يأت في القرآن، جاءت به السنة، تحريم السباع كالأسد والنمر ونحوه، كل ذي ناب من السباع، والكلب ونحو ذلك، وتحريم كل ذي مخلب من الطير كالعقاب والباز والصقر، هذه جاءت به السنة عن النبي ﷺ.","link":"https://binbaz.org.sa/fatwas/13997/هل-الوجوب-ياخذ-من-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56818.mp3","categories":["أصول الفقه"]},{"id":15508,"question":"السائلة أم عبدالرحمن تقول: جدتي -يا سماحة الشيخ- مصابة في شلل نصفي، وفي بعض الأحيان يصعب علينا أن نوجهها للقبلة، ونأمرها أن تشير في يديها إلى القبلة، وهي في الصلاة تتكلم وتنسى أنها في الصلاة، ونرى أنها لا تؤدي الصلاة على أكمل وجه، فماذا نفعل معها؟","title":"ما يلزم مع من يخل بالصلاة لكبر سنه؟","answer":"الجواب: ما دامت قد تغير عقلها، ولم تحفظ الصلاة، فإنها لا تكليف عليها؛ لأن من شرط وجوب الصلاة العقل، فإذا كان قد تغير عقلها لكبر سنها، أو لمرض أصابها، فلا شيء عليها، أما إذا كان عندها عقل، ولكن تنسى تتعلم، يجب تعليمها وتوجه إلى القبلة، وتعلم إذا نسيت، تعمل ما يلزم من البناء على اليقين إذا نسيت، هل صلت ثنتين أو ثلاث تجعلها ثنتين، إذا نسيت فصلت ثلاثًا أو أربعًا في الظهر أو العصر أو العشاء تجعلها ثلاث، وإذا نسيت هل قرأت الفاتحة أم لا؟ تقرأ الفاتحة، تتعلم الأمور الشرعية، هذا إن كان معها عقل، أما إذا كان عقلها قد تغير، ولا تضبط شيئًا، فليس عليها تكليف، نعم. المقدم: أحسن الله إليكم يا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14045/ما-يلزم-مع-من-يخل-بالصلاة-لكبر-سنه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_569/56911.mp3","categories":["أصول الفقه"]},{"id":15865,"question":"السائل (ن. س. القحطاني ) يقول في سؤاله: يقول البعض من الناس بأن الواجب موجود فقط في القرآن، وأن ما قال الرسول ﷺ سنة فقط، ليست إلزامية، ماذا نرد عليهم يا سماحة الشيخ؟","title":"وجوب الأخذ بما جاء في السنة","answer":"الجواب: الوجوب والسنة تؤخذ من كلام الرسول ﷺ، ومن كلام الله -جل وعلا-؛ لأن الله يقول: وَمَا آتَاكُمُ الرَّسُولُ فَخُذُوهُ وَمَا نَهَاكُمْ عَنْهُ فَانْتَهُوا [الحشر:7] ويقول -جل وعلا-: مَنْ يُطِعِ الرَّسُولَ فَقَدْ أَطَاعَ اللَّهَ [النساء:80]، ويقول: أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ[النساء:59]. فما أوجبه الرسول ﷺ -وإن لم يأت في القرآن- وجب الأخذ به، مثل قوله ﷺ: لا يجمع بين المرأة وعمتها هذا ما هو في القرآن: لا يجمع بين المرأة وعمتها، ولا بين المرأة وخالتها قد أجمع المسلمون على هذا، الذي في القرآن: وَأَنْ تَجْمَعُوا بَيْنَ الأُخْتَيْنِ [النساء:23] فجاءت السنة بالنهي عن الجمع بين المرأة وعمتها، والمرأة وخالتها، وأجمع المسلمون على ذلك. وهكذا كلما جاء في السنة الصحيحة وجب الأخذ به، وإن لم يذكر في القرآن الكريم، هكذا تحريم كل ذي ناب من السباع، وكل ذي مخلب من الطير؛ هذا لم يأت في القرآن، جاءت به السنة، تحريم السباع كالأسد والنمر ونحوه، كل ذلك كل ذي ناب من السباع والكلب ونحو ذلك، وتحريم كل ذي مخلب من الطير كالعقاب والباز والصقر، هذه جاءت به السنة عن النبي ﷺ. المقدم: شكر الله لكم سماحة الشيخ، ونفع الله بكم وبعلمكم الإسلام والمسلمين.","link":"https://binbaz.org.sa/fatwas/14456/وجوب-الاخذ-بما-جاء-في-السنة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57627.mp3","categories":["أصول الفقه"]},{"id":15972,"question":"يقول: ما هو الفرق بين الألفاظ التالية: راتبة، نافلة، مؤكدة؟","title":"الفرق بين الراتبة والنافلة والسنة المؤكدة","answer":"الجواب: الراتبة: التي أخبر النبي ﷺ أو فعل ما يدل على أنها راتبة يداوم عليها ﷺ مثل سنة الظهر والمغرب والعشاء والفجر، هذه يقال لها: رواتب؛ سنة الجمعة؛ لأن الرسول ﷺ راتب عليها -عليه الصلاة والسلام-، وواظب عليها.\nوالنافلة: هي التي غير الفريضة تطلق على كل عبادة غير واجبة؛ الصوم والصلاة والصدقات ونحو ذلك، يقال لها: نافلة؛ كل عبادة غير واجبة يقال لها نافلة، كسنة الضحى والرواتب التي مع الصلوات، سنة الوتر، صوم الإثنين والخميس، صوم ست من شوال، هذه يقال لها نوافل، الصدقة بالمال غير الواجبة يقال لها: نافلة.\nأما المؤكدة: فهي السنة المؤكدة التي ليست مطلقة، بل مؤكدة، مثل الرواتب سنة مؤكدة، الوتر سنة مؤكدة، صلاة الضحى سنة مؤكدة، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14583/الفرق-بين-الراتبة-والنافلة-والسنة-الموكدة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_746/nour_74621.mp3","categories":["أصول الفقه"]},{"id":16164,"question":"تقول: رجل كبر في السن، وأصبح لا يعي من الحياة أي شيء، حتى من هم أبناؤه، وأصبح لا يصوم، ولا يصلي، ولا يعرف معنى ذلك، والآن توفي، فهل يجب على أبنائه قضاء صوم رمضان؟ جزاكم الله خيرًا.","title":"حكم قضاء الصوم على الرجل الخرف","answer":"الجواب: إذا كان الرجل كما ذكر فليس عليه شيء؛ لأنه اختل صار في حكم غير المكلفين، لما زال شعوره؛ صار من جنس المجانين، والمعاتيه؛ بسبب الهرم، فلا شيء عليه، لا صلاة، ولا زكاة، ولا غير ذلك، رفع عنه القلم، الله المستعان، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/14857/حكم-قضاء-الصوم-على-الرجل-الخرف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_805/nour_80510.mp3","categories":["أصول الفقه"]},{"id":16176,"question":"تقول: ما الفرق بين الجزاء والإجزاء؟","title":"ما الفرق بين الجزاء والإجزاء؟","answer":"الجواب: الجزاء: عقوبة ما فعل الإنسان، جزاؤه أو ثوابه، يقال: ثواب من فعل الصدقة الأجر عند الله والحسنات.. ثواب من فعل الصوم الأجر.. ثواب من كان يصلي الأجر عند الله، وهو موعود بالجنة.. ثواب من أعطاك مالًا، أو أهداك مالًا أن تكافئه بالمال، هذا هو الجزاء. أما الإجزاء: معناه الصحة، يقال: أجزأت الصلاة يعني: صحت.. أجزأ الصوم؛ صح الصوم، أجزأ الكلام هذا ... حصل به الكفاية، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/14835/ما-الفرق-بين-الجزاء-والاجزاء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_750/nour_75012.mp3","categories":["أصول الفقه"]},{"id":16395,"question":"الرسالة التالية من إحدى الأخوات المستمعات وقعت في نهايتها بقولها: أختكم في الله (س. م. ص) من الأردن، عرضنا جزءًا من أسئلتها في حلقة مضت، وفي هذه الحلقة بقي لها بعض الأسئلة في أحدها تقول: هل الصلاة، والصوم، وغيرها من العبادات فرض على الأولاد الذين لم يبلغوا، أم لا؟ وهل يعاقبون على ترك الصلاة مثلًا؟ جزاكم الله خيرًا.","title":"حكم العبادات على من كان دون سن التكليف","answer":"الجواب: من شرط الوجوب التكليف، أن يبلغ الحلم الرجل والمرأة، والحلم يكون بإكمال خمسة عشر سنة للذكر والأنثى، أو إنبات الشعر الخشن حول الفرج -الشعرة- أو إنزال المني بالاحتلام، أو بالنظر، أو بغير هذا من أسباب نزول المني، إذا نزل المني بأي سبب عن شهوة؛ صار الرجل مكلفًا، وصارت البنت مكلفة، هذه أمور ثلاثة يحصل بها البلوغ للرجل، والمرأة. الأول: إكمال خمسة عشر سنة هجرية. الثاني: إنبات الشعرة التي حول الفرج، يعني: الشعر الذي حول الفرج، ويسمى الشعرة، والعانة، للرجل والمرأة. الثالث: إنزال المني عن شهوة باحتلام، أو بغيره. وهناك رابع في حق المرأة: وهو الحيض، إذا حاضت، ولو بنت تسع، أو عشر؛ تكون امرأة مكلفة، تجب عليها الصلاة، والصوم، صوم رمضان، والحج مع الاستطاعة، وهكذا الرجل. فالمقصود: أن بهذه الأمور الثلاثة في حق الرجل والمرأة، يجب عليهما الصلوات الخمس، وصوم رمضان، وحج البيت مع الاستطاعة، وعلى المرأة إذا حاضت كذلك، يجب عليها الصلوات الخمس، وصوم رمضان، والحج مع الاستطاعة. أما من قبل البلوغ ما يجب عليه، لكن يشرع له إذا بلغ سبعًا يؤمر بالصلاة، ويؤمر بالصوم إذا أطاق ذلك يأمره وليه بالصلاة والصوم، وهكذا ابن عشر، وما فوقه حتى يبلغ، حتى يعتاد الخير، حتى يعتاد الصلاة، حتى يعتاد الصوم يأمره وليه، ويأمرها وليها بهذا، وإذا بلغ الرجل عشرًا، والمرأة عشرًا؛ فللولي أن يضربهما إذا تخلفا؛ لأن النبي  قال: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر والأولاد يشمل الذكر والأنثى.  وفرقوا بينهم في المضاجع فإذا بلغ الذكر عشرًا، والأنثى عشرًا، فالرجل مأمور بأن يضربهما، ويؤدبهما إذا تخلفا عن الصلاة، وهكذا الصوم، صوم رمضان حتى يتمرنا، ويعتادا فعل هذا الواجب، فإذا بلغا فإذا هما قد اعتاداه، وصار من سجيتهما وخلقهما. وهكذا وليهما يزجرهما عن المعاصي، عن الغيبة والنميمة، والسب والشتم، وغير ذلك من المعاصي التي نهى الله عنها ورسوله، الولي ينهاهما عنها قبل البلوغ وبعده، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15098/حكم-العبادات-على-من-كان-دون-سن-التكليف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81106.mp3","categories":["أصول الفقه"]},{"id":16396,"question":"سماحة الشيخ يعتقد البعض أنكم تقفون عند مذهب معين، هل تتفضلون بقول كلمة في هذا المقام؟","title":"توجيه حول التقيد في الفتوى بمذهب معين","answer":"الجواب: الفتاوى الصادرة مني لا أقف فيها، ولا أعتمد فيها على مذهب أحد، لا أحمد، ولا غيره، إنما عمدتنا في ذلك تحري ما قاله الله ورسوله ﷺ، سواء كان في مذهب أحمد، أو مذهب الشافعي، أو مالك، أو أبي حنيفة، أو الظاهرية، أو بعض السلف المتقدمين. المقصود: تحري ما يدل عليه الكتاب والسنة، هذا هو الذي نعتمد عليه، لا نعتمد على مذهب أحمد، ولا على غيره، إنما نعتمد على ما قاله الله ورسوله ﷺ، وما دل عليه الكتاب والسنة، في الأحكام؛ لأن هذا هو الواجب على كل طالب علم، نعم. المقدم: جزاكم الله خيرًا. الشيخ: نسأل الله للجميع التوفيق، والهداية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15105/توجيه-حول-التقيد-في-الفتوى-بمذهب-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81109.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":16401,"question":"سماحة الشيخ يعتقد البعض أنكم تقفون عند مذهب معين، هل تتفضلون بقول كلمة في هذا المقام؟","title":"توجيه حول التقيد في الفتوى بمذهب معين","answer":"الجواب: الفتاوى الصادرة مني لا أقف فيها، ولا أعتمد فيها على مذهب أحد، لا أحمد، ولا غيره، إنما عمدتنا في ذلك تحري ما قاله الله ورسوله ﷺ، سواء كان في مذهب أحمد، أو مذهب الشافعي، أو مالك، أو أبي حنيفة، أو الظاهرية، أو بعض السلف المتقدمين. المقصود: تحري ما يدل عليه الكتاب والسنة، هذا هو الذي نعتمد عليه، لا نعتمد على مذهب أحمد، ولا على غيره، إنما نعتمد على ما قاله الله ورسوله ﷺ، وما دل عليه الكتاب والسنة، في الأحكام؛ لأن هذا هو الواجب على كل طالب علم، نعم. المقدم: جزاكم الله خيرًا. الشيخ: نسأل الله للجميع التوفيق، والهداية، نعم. المقدم: اللهم آمين.","link":"https://binbaz.org.sa/fatwas/15105/توجيه-حول-التقيد-في-الفتوى-بمذهب-معين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_811/nour_81109.mp3","categories":["أصول الفقه","العالم والمتعلم"]},{"id":16526,"question":"يقول: إذا سألني شخص عن مسألة، وكنت قد سمعت من الراديو فتوى عن مثلها تمامًا؛ فهل لي أن أفتيه بما سمعت؟","title":"الضابط في نقل الفتوى","answer":"الجواب: نعم، تنسبها إلى صاحبها تقول: سمعت فلانًا في نور على الدرب، أو في أي إذاعة تقول: سمعت فلانًا أفتى بكذا إذا كنت قد علمت ذلك يقينًا، وحفظته، وفهمته، وعندك فيه بصيرة تقول: سمعت فلانًا، الشيخ فلان أفتى بكذا حتى تؤدي الواجب على بصيرة، وحتى تخرج من العهدة. أما إن كان عندك شك، أو ما حفظتها جيدًا، أو عندك تردد، أو كذا فلا، لا تفتي أحدًا إلا بعلم إلا عن علم عندك عن الله، وعن الرسول -عليه الصلاة والسلام- واحذر فإن الفتوى بغير علم خطرها عظيم، وإثمها كبير، نسأل الله السلامة. المقدم: نسأل الله السلامة، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15270/الضابط-في-نقل-الفتوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_757/nour_75708.mp3","categories":["أصول الفقه"]},{"id":16673,"question":"من القصيم رسالة بعثت بها إحدى الأخوات المستمعات رمزت إلى اسمها بالحروف (أ. ح) لها جمع من الأسئلة في أحدها تقول: هل القيام بأمور الدعوة، والأمر بالمعروف، والنهي عن المنكر، وصلة الأرحام واجبة على المرأة كما هي واجبة على الرجل، ومن من رحمها تصل؟ جزاكم الله خيرًا.","title":"حكم الدعوة وصلة الرحم في حق المرأة","answer":"الجواب: نعم الأحكام عامة للرجال، والنساء، والواجب على الرجل هو الواجب على المرأة، والواجب على المرأة هو الواجب على الرجل، إلا ما خصه الدليل يقول الله سبحانه: وَالْمُؤْمِنُونَ وَالْمُؤْمِنَاتُ بَعْضُهُمْ أَوْلِيَاءُ بَعْضٍ يَأْمُرُونَ بِالْمَعْرُوفِ وَيَنْهَوْنَ عَنِ الْمُنكَرِ وَيُقِيمُونَ الصَّلاةَ وَيُؤْتُونَ الزَّكَاةَ وَيُطِيعُونَ اللَّهَ وَرَسُولَهُ أُوْلَئِكَ سَيَرْحَمُهُمُ اللَّهُ إِنَّ اللَّهَ عَزِيزٌ حَكِيمٌ [التوبة:71] فسوى بينهم جميعًا بين المؤمنين والمؤمنات، وأخبر أن هذه الأمور لازمة لهم، وهي من صفاتهم، وأخلاقهم الواجبة العظيمة المفروضة عليهم، ويقول -جل وعلا-: إِنَّ الْمُسْلِمِينَ وَالْمُسْلِمَاتِ وَالْمُؤْمِنِينَ وَالْمُؤْمِنَاتِ وَالْقَانِتِينَ وَالْقَانِتَاتِ وَالصَّادِقِينَ وَالصَّادِقَاتِ وَالصَّابِرِينَ وَالصَّابِرَاتِ وَالْخَاشِعِينَ وَالْخَاشِعَاتِ وَالْمُتَصَدِّقِينَ وَالْمُتَصَدِّقَاتِ وَالصَّائِمِينَ وَالصَّائِمَاتِ وَالْحَافِظِينَ فُرُوجَهُمْ وَالْحَافِظَاتِ وَالذَّاكِرِينَ اللَّهَ كَثِيرًا وَالذَّاكِرَاتِ أَعَدَّ اللَّهُ لَهُمْ مَغْفِرَةً وَأَجْرًا عَظِيمًا [الأحزاب:35] عشرة أصناف من الرجال، والنساء، عشرة، كلهم داخلون في الإسلام والإيمان، كل هؤلاء الأصناف، لكن نوعها بسبب الأعمال تنوع الأعمال.  إن المسلمين والمسلمات المسلم: الذي دخل في الإسلام، وانقاد لدين الله، ووحد الله، وآمن بالله ورسوله، وصدق الله في أخباره، وصدق الرسول ﷺ وآمن بكل ما أخبر الله به ورسوله، يقال له: مسلم، فإذا استكمل الدين، واستقام على دين الله؛ صار مؤمنًا كاملًا، وإذا كان يديم الطاعات، ويجتهد في الطاعات يسمى قانتًا، وإذا كان من أهل الصدقة والإحسان صار متصدقًا، وإذا كان من الصبر على طاعة الله، والصبر عن المعاصي يسمى صابرًا، وإذا كان يؤدي الأعمال بخشوع، وحضور قلب، وطمأنينة يسمى خاشعًا.  وهكذا إذا كان يكثر الصيام، يصوم رمضان، يصوم؛ فهو من الصائمين، والصائمات، وهكذا حفظ الفرج عن الزنا من الرجل والمرأة داخل في قوله: والحافظون فروجهم والحافظات وهكذا الذكر إذا كان من أهل الذكر، يكون من الذاكرين الله كثيرًا والذاكرات، الرجل والمرأة جميعًا. فعليك أن تجتهدي في طاعة الله ورسوله، وأن تحرصي على القيام بالواجب: كالدعوة إلى الله، والأمر بالمعروف، والنهي عن المنكر، والمسارعة إلى الخيرات، والاجتهاد في الطاعات، والصدق في العمل والقول، هكذا المؤمن والمؤمنة، هذه الصفات العشر من صفات المؤمنين والمؤمنات من عرب وعجم، وجن وإنس. فكل واحد يجتهد أن يكون من هؤلاء، والمسلم ينبغي له أن يجتهد أن يكون من هؤلاء، وهكذا كل مسلمة عليها أن تجتهد حتى تتصف بهذه الأخلاق العظيمة، ويقول -جل وعلا-: فَاسْتَجَابَ لَهُمْ رَبُّهُمْ أَنِّي لا أُضِيعُ عَمَلَ عَامِلٍ مِنْكُمْ مِنْ ذَكَرٍ أَوْ أُنْثَى بَعْضُكُمْ مِنْ بَعْضٍ [آل عمران:195]. فأعمالهم كلها محفوظة، لا يضيع الله منها شيئًا، الذكور والإناث، ثم يجازيهم عليها  ويقول : مَنْ عَمِلَ صَالِحًا مِنْ ذَكَرٍ أَوْ أُنثَى وَهُوَ مُؤْمِنٌ فَلَنُحْيِيَنَّهُ حَيَاةً طَيِّبَةً وَلَنَجْزِيَنَّهُمْ أَجْرَهُمْ بِأَحْسَنِ مَا كَانُوا يَعْمَلُونَ [النحل:97] الجميع، لكن ما خصه الدليل بالرجل فهو للرجل؛ كأن ينكح أربع زوجات، والمرأة ليس لها إلا زوج واحد، ديته مائة من الإبل، وديتها خمسون من الإبل المرأة، المرأة يصيبها الحيض والنفاس، وليس الرجل كذلك، تحمل وهو لا يحمل، أشياء تخص، بينهم أشياء افترقا فيها بينها الكتاب والسنة. والمقصود: أن الأصل أنهما سواء، هذا هو الأصل، الأحكام واحدة على الرجال والنساء، إلا ما خصه الدليل، وفق الله الجميع.  المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15426/حكم-الدعوة-وصلة-الرحم-في-حق-المراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_760/nour_76005.mp3","categories":["أصول الفقه","قضايا المرأة"]},{"id":16708,"question":"يقول صاحب هذه الرسالة: أنا من الذين يستمعون إلى هذا البرنامج يوميًا، فمثلًا يا سماحة الشيخ! إذا سألني أحد سؤالًا، وأنا قد سمعت الإجابة عن مثله في هذا البرنامج، فأجبته، هل أكون محسنًا؟ أو بماذا توجهونني؟ جزاكم الله خيرًا.","title":"توجيه لمن يفتي بما يسمع من فتاوى العلماء","answer":"الجواب: نعم تكون محسنًا إذا بلغته، تقول سمعت في برنامج نور على الدرب كذا وكذا، وإذا بينت له المفتي يكون أحسن، تقول لفلان: سمعت فلانًا نور على الدرب، سئل عن هذا، فقال كذا وكذا، بعد التأكد، والضبط؛ لئلا تقول على أصحاب البرنامج ما لم يقولوا، يعني لابد أن تكون ضابطًا للشيء، حافظًا له، متيقنًا له، تنقله لمن سألك، تقول: سمعت فلانًا قال كذا وكذا، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/15443/توجيه-لمن-يفتي-بما-يسمع-من-فتاوى-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_718/nour_71803.mp3","categories":["أصول الفقه"]},{"id":16815,"question":"سماحة الشيخ! يدور على ألسنة بعض المثقفين هذا القول: السنة يثاب فاعلها، ولا يعاقب تاركها، هل لسماحتكم من تعليق على هذا القول؟","title":"توضيح مقولة أن السنة يثاب فاعلها ولا يعاقب تاركها","answer":"الجواب: نعم مرادهم بذلك السنة في اصطلاح الفقهاء، وهي التي دون الواجب. المقدم: دون الواجب. الشيخ: عند الفقهاء ... يسمون النافلة سنة، مثل صلاة الضحى، مثل الوتر، مثل الرواتب مع الصلوات، يقال لها: سنة، ومثل بدء السلام، وتشميت العاطس، يسمى سنة، فالسنة هي التي دون الواجب، ولكنها مأمور بها مشروعة. وتطلق السنة على طريق النبي ﷺ وما جاء به من الهدى، وهذا فرض، اتباع النبي ﷺ والسير على منهاجه في توحيد الله، وطاعة الأوامر، وترك النواهي هذا هو فرض لا بد منه، لكن مراد الفقهاء إذا قالوا: سنة يثاب فاعلها، ولا يعاقب تاركها، مرادهم النوافل، مرادهم العبادة التي هي نافلة، مثل سنة الضحى، مثل الرواتب مع الصلوات، مثل التهجد بالليل، كل هذه يقال لها: سنة غير فريضة، نعم. المقدم: جزاكم الله خيرًا، إذًا لا بد من فهم واعٍ لهذه القاعدة. الشيخ: نعم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15564/توضيح-مقولة-ان-السنة-يثاب-فاعلها-ولا-يعاقب-تاركها","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_763/nour_76308.mp3","categories":["أصول الفقه"]},{"id":16895,"question":"يسأل سؤالًا شبيهًا بسؤال في حلقات مضت يقول: هل الإنسان الذي هو غير مكلف، والذي هو مختل الشعور، هل يؤاخذ على تركه للفرائض، والنوافل، أم لا؟ جزاكم الله خيرًا.","title":"هل يؤاخذ مختل الشعور على ترك الفرائض؟","answer":"الجواب: إذا كان مختل الشعور؛ لا يؤاخذ بشيء، يقول النبي ﷺ: رفع القلم عن ثلاثة، عن النائم حتى يستيقظ، والمجنون حتى يفيق، والصغير حتى يبلغ فالنائم لو تكلم في نومه بالسب، والشتم ما يؤاخذ، أو طلق؛ ما يقع طلاقه؛ لعدم العقل، هكذا المجنون، والمعتوه الغير مضبوط العقل، أو تكلم في حال جنونه، في حال حضور الجنون، والصرع، كل هذا لا يلتفت إليه، وهكذا إذا كان معتوهًا، ولو ما فيه جنون، معتوه العقل لصغر سنه، أو لأنه خلقة، أصابه خلل في عقله، لا يحسن التصرف؛ فلا يؤخذ بشيء؛ لأنه مرفوع عنه القلم. وهكذا الصغير قبل أن يبلغ لا يؤاخذ، وإنما يؤاخذ بعد البلوغ، لكنه يعلم، ويؤمر، وينهى، يؤمر بالصلاة، ويؤمر بالصيام إذا استطاع الصيام، وينهى عن الفحش، والكلام السيئ، ويؤدب على ذلك، لكنه لا يؤاخذ بذلك من جهة الرب  وإنما وليه يؤدبه، ويعلمه حتى يعتاد الخير، وحتى يتجنب الشر؛ لقول النبي ﷺ: مروا أولادكم بالصلاة لسبع، واضربوهم عليها لعشر حتى يعتادوا الخير، حتى يتمرنوا عليه، حتى يبتعدوا عن الشر. ولما أخذ الحسن، أو الحسين -رضي الله عنهما- تمرة من الصدقة؛ قال النبي ﷺ للحسن: دعها كخ كخ دعها، أما علمت أنها لا تحل لنا الصدقة وهو صغير الحسن، ابن سبع سنين وأشهر حينما أتى النبي ﷺ والحسين أقل من ذلك. فالحاصل: أن تعليم الصبيان للخير، وتحذيرهم من الشر، أمر مطلوب، ولكن لا إثم عليهم لو ماتوا على ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15656/هل-يواخذ-مختل-الشعور-على-ترك-الفراىض","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_765/nour_76514.mp3","categories":["أصول الفقه"]},{"id":16962,"question":"لماذا كان الاختلاف بين العلماء، وما هو موقف الإنسان في هذا الأمر؟","title":"أسباب الاختلاف بين العلماء","answer":"الجواب: أسباب الاختلاف ذكرها العلماء -رحمهم الله- في كتبهم؛ وذلك لأن المسألة قد يكون فيها أدلة كثيرة، يخفى بعضها على بعض الناس، وقد تكون مسألة ليس فيها إلا أدلة قليلة، تخفى على بعض الناس، فيختلفون في الأحكام، على حسب علمهم، فهذا يبلغه الدليل، ويقول: إنها واجبة، أو مشروعة، والآخر ما بلغه الدليل، فيقول: إنها غير مشروعة، أو غير واجبة، فأسباب الاختلاف: هو بلوغ الدليل، وعدمه، واختلاف الفهم أيضًا، قد يفهم الإنسان من النص ما لا يفهمه الآخر من العلماء، وكل من اجتهد، وتحرى الحق؛ فهو على خيرٍ عظيم، إذا كان من أهل العلم، إن أصاب فله أجران، وإن أخطأ فله أجر، إذا تحرى الحق، وهو من أهله من أهل العلم والبصيرة، واجتهد؛ فهو بين أجرين وأجر، إن أصاب فله أجران، وإن أخطأ فله أجر. فأسباب الاختلاف: هو اختلاف الفهم، ثم الاختلاف في الاطلاع على الأدلة، وبلوغ الأدلة، هذا قد يبلغه شيء، والآخر لا يبلغه شيء، فيختلف الحكم عنده بسبب ذلك، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15760/اسباب-الاختلاف-بين-العلماء","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_828/nour_82818.mp3","categories":["أصول الفقه"]},{"id":17104,"question":"سماحة الشيخ! من أسئلة هذا السائل يقول: هل الشيء الحسن بدعة، مثل: الموالد التي فيها ذكر الله، ومثل إقامة مولد كل سنة لمن مات أبوه، أو قريبه، وكذلك الجلوس في المقبرة ثلاثة أيام يذكرون الله فيها إلى روح الميت؟","title":"بيان أن العبادات تكون بالشرع لا بالاستحسان","answer":"الجواب: العبادات تكون بالشرع ما هو بالرأي والاستحسان، العبادات تكون بشرع الله؛ ما قاله الله ورسوله، وما شرعه الله ورسوله، أما ما أحدثه الناس فهو بدعة، لقوله ﷺ: من عمل عملًا ليس عليه أمرنا فهو رد وقوله ﷺ: من أحدث في أمرنا هذا ما ليس منه فهو رد والله يقول سبحانه: أَمْ لَهُمْ شُرَكَاءُ شَرَعُوا لَهُمْ مِنَ الدِّينِ مَا لَمْ يَأْذَنْ بِهِ اللَّهُ [الشورى:21] فالاجتماع للموالد بدعة، لا مولد النبي ﷺ ولا غيره، الاجتماع للموالد، والاحتفال بالموالد هذا من البدع التي أحدثها الناس، وهكذا كونه يحيي بدعة لأبيه، مولدًا لأبيه أو لأمه بدعة لا يجوز. وهكذا الجلوس عند القبور للدعاء، أو القراءة بدعة لا يجوز، بل من وسائل الشرك. والقاعدة: أن العبادة ما شرعه الله، توقيفية، لا يكون شيء عبادة إلا إذا شرعه الله، أو شرعه رسوله ﷺ، أما إحداث الناس لا، يقول ﷺ: من أحدث في أمرنا يعني: في ديننا هذا ما ليس منه فهو رد يعني: فهو مردودٌ عليه، ويقول -عليه الصلاة والسلام-: إياكم ومحدثات الأمور .نعم.  المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/15895/بيان-ان-العبادات-تكون-بالشرع-لا-بالاستحسان","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_589/58903.mp3","categories":["البدع والمحدثات","أصول الفقه"]},{"id":17257,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من بريدة القصيم، باعث الرسالة المستمع حمد بن أحمد العيَّاف له جمع من الأسئلة يقول في أحدها: هل الإنسان الذي هو غير مكلف، ومختل الشعور، هل له صلاة إذا صلى، وصيام إذا صام، وزكاة إذا زكى؟ وهل عليه حرج إن لم يفعل ذلك؟ جزاكم الله خيرًا.","title":"من أحكام المجنون والطفل","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه، أما بعد.  فالذي ليس له شعور، بل قد زال عقله لا يسمى مكلفًا، المكلف هو البالغ العاقل، هذا الذي يسمى مكلفًا، سواء كان رجلًا، أو امرأة، أما من كان غير بالغ، أو كان قد بلغ الحلم، ولكنه زائل العقل بجنون، أو غيره من أسباب زوال العقل؛ فإنه لا يكون مكلفًا، وليس عليه صلاة، ولا صوم، ولا غيرهما من الواجبات، إلا الواجب المالي، فالواجب المالي كالزكاة يجب على وليه أن يخرجه، فإذا حال الحول على مال الصبي، أو المجنون؛ وجب على وليه أن يخرج زكاته، وهكذا لو أتلف شيئًا على الناس؛ وجب قيمة المتلف في ماله؛ لأن هذا ليس له نية، فيستوي فيه المكلف، وغير المكلف، وفق الله الجميع. نعم. المقدم: اللهم آمين، جزاكم الله خيرًا لا زال أخونا يعقب على نفس الموضوع، فيقول: وهل إذا عق أحد والديه وهو في هذه الحالة مختلًا مثل الشتم، أو الضرب، هل يعاقب من الله  أم ماذا؟ جزاكم الله خيرًا.  الشيخ: ليس عليه شيء، فلا ثواب، ولا عقاب لفقد العقل، فما يقع منه من بعض المعاصي ليس فيها إثم عليه؛ لعدم تكليفه لعدم عقله، فلو سب، أو شتم، أو فعل شيئًا من المحرمات الأخرى فليس عليه إثم؛ ما دام مسلوب العقل لقول النبي ﷺ: رفع القلم عن ثلاثة: عن النائم حتى يستيقظ، وعن الصغير حتى يبلغ، وعن المجنون حتى يفيق فالنائم لو سب في النوم، أو شتم، أو فعل شيئًا غير ذلك من الأمور الأخرى: كالطلاق، أو العتاق ما يعتبر ما يفعله في النوم، لا يعتبر لا من إيجاب، ولا من سلب، لا من معصية، ولا من طاعة؛ لأنه غير مكلف في هذه الحالة، ليس له عقل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16099/من-احكام-المجنون-والطفل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76801.mp3","categories":["أصول الفقه"]},{"id":17273,"question":"بمناسبة الفتوى والاستفتاء سماحة الشيخ؛ كثير من إخواننا يسأل عن موضوع واحد أكثر من طالب علم، ولربما وجد اختلافًا في القول، فما هو توجيهكم لأولئك الذين يسألون، هل يكتفون بسؤال شخص واحد؟ أم يسألون هذا، وذاك حتى يصلوا إلى مبتغاهم؟","title":"حكم سؤال أكثر من عالم لاتباع المستفتي هواه","answer":"الجواب: إذا كان السائل لم يطمئن قلبه للفتوى، وهو قصده الخير، وقصده العلم، قصده الورع؛ فلا حرج، يسأل حتى يطمئن قلبه للدليل، وأن هذا هو الحكم الشرعي، أما إذا كان يقصد الهوى هذا لا يجوز، إذا كان يطلب ما يوافق هواه هذا لا يجوز، لكن عليه أن يجتهد في أن يعرف الحق بدليله؛ حتى يطمئن قلبه للفتوى، ويتحرى من يظنهم أقرب إلى الخير، وأقرب إلى العلم من أهل الفتوى يعني: يستفتي من يطمئن قلبه إلى أنه أقرب إلى معرفة الحق، يتحرى في أهل العلم، وفي استفتائهم من يظن، ويغلب على ظنه أنه أقرب إلى إصابة الحق، فهو يهتم بالطمأنينة، وإصابة الحق لا بما يوافق هواه، فالذي يسأل هذا وهذا لينشرح صدره، وليطمئن إلى الفتوى بدليلها؛ نرجو أن لا حرج عليه؛ لأن هذا من باب التثبت في الحق. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/16116/حكم-سوال-اكثر-من-عالم-لاتباع-المستفتي-هواه","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_768/nour_76809.mp3","categories":["أصول الفقه"]},{"id":17812,"question":"هذا السائل من الطائف أبو أحمد (أ. أ) الحوية، يقول سماحة الشيخ: ما موقف المسلم من اختلاف الفتوى، وكيف يأخذ بإحدى الفتوى؟","title":"موقف المسلم من اختلاف الفتوى","answer":"الجواب: يتوخى العلماء وينظر أقربهم إلى الخير وأعلمهم بالسنة في اعتقاده، وأخيرهم ورعًا، ويسأل يتحرى من يطمئن إلى فتواه من أهل العلم؛ حتى يحتاط لدينه. نعم.\nالمقدم: جزاكم الله عنا وعن المسلمين خير الجزاء.","link":"https://binbaz.org.sa/fatwas/16801/موقف-المسلم-من-اختلاف-الفتوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_597/59718.mp3","categories":["أصول الفقه"]},{"id":18104,"question":"نعود إلى رسالة الأخ محمود أحمد الدوسة من العراق بغداد الزعفرانية، أخونا بعث بأسئلة كثيرة إلى هذا البرنامج وقد عرضنا جزءًا كبيرًا من أسئلته، وها نحن أيضًا نعرض بعضًا منها في هذه الحلقة، فيسأل ويقول: جاء في بعض الأحاديث أن رسول الله ﷺ نهى عن عمل كذا من الأعمال، فهل النهي هو التحريم أو أن النهي يعني الكراهية؟","title":"حكم النهي في الأحكام الشرعية","answer":"الجواب: هذا هو الأصل، الأصل أن النهي للتحريم، يقول النبي ﷺ في الحديث الصحيح: ما نهيتكم عنه فاجتنبوه وما أمرتكم به فائتوا منه ما استطعتم هكذا قال ﷺ: فإنما هلك من كان قبلكم بكثرة مسائلهم واختلافهم على أنبيائهم، فما نهيتكم عنه فاجتنبوه وما أمرتكم به فائتوا منه ما استطعتم . فالأصل في النهي هو التحريم هذا هو الأصل، ولا ينقل عن التحريم إلى الكراهة إلا بدليل يدل على ذلك، فإذا نهى عن شيء ثم فعله دل على أنه نهي للكراهة، مثلما نهى عن الشرب قائمًا ثم شرب قائمًا في بعض الأحيان دل على أنه ليس للتحريم وأنه يجوز الشرب قاعدًا وقائمًا ولكنه إذا شرب قاعدًا يكون أفضل وأحسن، مثلما أمر بالقيام للجنازة قال: إذا رأيتم الجنازة فقوموا ثم جلس في بعض الأحيان، دل على أن الأمر ليس للوجوب في هذه الحال. فالقاعدة أنه متى نهى عن شيء ثم فعله دل على أن النهي ليس للتحريم، بل للكراهة وترك الأولى، وإذا أمر بشيء، ثم تركه دل على أنه ليس للوجوب، وإلا فالقاعدة أن الأوامر للوجوب والنهي للتحريم، هذا هو القاعدة. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17139/حكم-النهي-في-الاحكام-الشرعية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_904/nour_90404.mp3","categories":["أصول الفقه"]},{"id":18193,"question":"رسالة وصلت إلى البرنامج من أحد الإخوة المستمعين، لم يصرح باسمه بدأها بقوله: أسرة برنامج نور على الدرب: أحييكم بتحية الإسلام، السلام عليكم ورحمة الله وبركاته، وبعد:فإني من المداومين على سماع برنامجكم هذا، والذي أرجو من الله أن يديمه علينا لما فيه من فائدة كبيرة في تبيان أمور الدين وإرشاد الناس لما فيه الخير في الدارين الأولى والآخرة، وأسئلتي هي:السؤال الأول: قرأت في أحد كتب الحديث حديث الأعرابي الذي بال في طائفة المسجد، المروي عن أنس بن مالك  عن النبي ﷺ، وذكر من فوائد الحديث دفع أعظم المفسدتين باحتمال أيسرهما، وتحصيل أعظم المصلحتين بترك أيسرهما، أرجو تبيان العلاقة بين هذه القاعدة وبين الحديث المذكور ولكم الأجر من الله تعالى.","title":"فوائد من حديث الأعرابي الذي بال في المسجد","answer":"الجواب: نعم هذا الحديث ثابت في الصحيحين «أن رجلًا أعرابيًا دخل المسجد فبال في طائفة المسجد فزجره الناس، فقال النبي ﷺ: لا تزرموه ورواه أيضًا البخاري من حديث أبي هريرة  عن النبي عليه الصلاة والسلام أنه قال: لما هموا به قال: لا تزرموه، ونهاهم أن يتعرضوه وقال: إنما بعثتم ميسرين ولم تبعثوا معسرين، فلما فرغ الأعرابي من بوله أمر النبي ﷺ أن يصب على بوله سجل من ماء يعني: دلو من ماء واكتفى بذلك». فدل ذلك على فوائد منها: الرفق بالجاهل وعدم العجلة عليه، وأن المسلمين بعثوا ميسرين لا معسرين، وأن الرفق بالجاهل من التيسير وأن الشدة عليه من التعسير. وفيه من الفوائد: أن الماء يزيل النجاسة بمجرد إراقته على النجاسة إذا كانت لا جرم لها ليس لها جسم، فالماء إذا أريق عليها وهو أكثر منها كفى، كالدلو على بول الأعرابي كفت وأنه لا حاجة إلى أن يحجر على ذلك أو إلى أن ينقل التراب بل يكفي صب الماء عليه ويطهر بذلك. ومن فوائد ذلك: أن المفسدة الكبرى تدفع بارتكاب اليسرى، وأن المصلحة العظمى تحصل ولو فاتت الدنيا كما سأل عنها السائل، ووجه ذلك: أنهم لو ألزموه بالكف عن ذلك لربما تطاير من بوله قطع في أماكن كثيرة فربما نجس نفسه ونجس بدنه وثيابه وبدنه، وربما نفر من الإسلام وكره الدخول في الإسلام، هذه مفاسد كبيرة، وكونه يكمل بوله ثم يصب عليه ماء أسهل كونه يكمل البول ثم يصب عليه الماء ويعلم بالرفق هذا أنفع وأسهل، أقل نجاسة وأقل ضرر وأقرب إلى تأليف قلبه وإلى محبته لإخوانه المسلمين وإلى دخوله في الإسلام ورغبته في الإسلام، فصارت المفسدة العظمى هي ما يحصل بالشدة عليه والعنف عليه، هذا شيء ينفره من البقاء في الإسلام ومحبة المسلمين. وهكذا يترتب على ذلك مفسدة من جهة تشتت النجاسة في المحل وكثرتها وتبددها، وكذلك ما قد يصيبه هو في نفسه أو في ثيابه من النجاسة، فاتضح أن المصلحة العظمى في عدم تنفيره وتأليفه وفي تقليل النجاسة مقدمة على المصلحة الدنيا وهي الاستعجال في كفه عن البول ومنعه من البول، وكذلك المفسدة العظمى التي تترتب على الشدة عليه وتنفيره من الإسلام وتنفيره من إخوانه المسلمين وتعدد النجاسة هذه مفسدة عظمى تركت بارتكاب الدنيا وهي تركه يكمل بوله، هذه مفسدة صغرى تركت وارتكبت لأن ذلك أسهل من العنف عليه والشدة عليه كما تقدم. نعم. المقدم: جزاكم الله خيرًا! هل من أمر يتعلق بالصحة العامة حول هذا الموضوع شيخ عبد العزيز؟ الشيخ: نعم، ذكر بعض أهل العلم أن هذا قد يضره أيضًا لأنه: إذا قطع عليه بوله قد يضره من جهة الصحة، فمن المصلحة أن يكمل بوله ولا يقطع عليه لأنه قد يضره من حيث الصحة. نعم. المقدم: جزاكم الله خيرًا ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/17228/فواىد-من-حديث-الاعرابي-الذي-بال-في-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_907/nour_90702.mp3","categories":["أصول الفقه"]},{"id":18360,"question":"يسأل هذا السائل ويقول: ما معنى القاعدة: الضرورات تبيح المحظورات، سماحة الشيخ؟","title":"شرح قاعدة: الضرورات تبيح المحظورات","answer":"الجواب: هذه قاعدة معروفة؛ إذا وجدت الضرورة مثلما يباح للمرأة أن تكشف عورتها للطبيب عند الحاجة، تكشف وجهها عند الحاجة، ويباح للرجل أن يكشف عورته عند الحاجة للطبيب، ومثلما يأكل الميتة عند الضرورة. نعم. المقدم: حفظكم الله.","link":"https://binbaz.org.sa/fatwas/17422/شرح-قاعدة-الضرورات-تبيح-المحظورات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_913/nour_91326.mp3","categories":["أصول الفقه"]},{"id":18578,"question":"سماحة الشيخ! تساهل بعض الناس في الفتوى لبعض الإخوان، ما توجيهكم لمثل هؤلاء يا شيخ؟","title":"توجيه إلى المتساهلين في الفتوى","answer":"الجواب: الواجب على المفتي أن يحذر مغبة الفتوى، وأن يتقي الله، وأن لا يفتي إلا عن علم، يتقي الله، ويحرص أن لا يقول إلا عن علم، الفتوى أمرها عظيم، وخطرها كبير، يروى في حديث مرسل عن النبي ﷺ أنه قال: أجرأهم على الفتيا أجرأهم على النار والله يقول سبحانه: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ[الأعراف:33]، فجعل القول على الله بغير علم فوق مرتبة الشرك؛ لعظم الخطر. وقال عن الشيطان: إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ[البقرة:169] فأخبر أن الشيطان يأمرنا بالقول على الله بغير علم. فالواجب على طالب العلم أن يحذر القول على الله بغير العلم، وأن يتقي الله في فتواه، ولا يقدم إلا عن علم، وعن بصيرة فيما يفتي به. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17691/توجيه-الى-المتساهلين-في-الفتوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_786/nour_78618.mp3","categories":["أصول الفقه"]},{"id":18648,"question":"من المستمع يوسف صالح الحاج من إصلاحية الحائر رسالة مطولة يقول فيها: كثيرًا ما أسمع من بعض أصحاب الفضيلة المشايخ الذين يفتون في برنامج: نور على الدرب، جملة:(لا ينبغي) فهل هذه الجملة تعني: التحريم أو الكراهية؟ فأنا مثلًا أعلم أن الفتوى لا تكون إلا بإحدى هذه الكلمات، وهي: التحريم، الكراهية، الوجوب، المسنون، المندوب، أو الحل، أو فرض عين، أو فرض كفاية، فمثلًا: في إحدى الحلقات سئل أحد المشايخ عن أكل الكبد أو الطحال نيئًا بدون طبخ، ولكنني لم أفهم من كلامه هل هو حرام أم مكروه؛ لأنه تكلم بتلكم العبارة التي أسأل عنها؟ والآن وجهونا حيال ذلك جزاكم الله خيرًا.","title":"مفهوم عبارة \"لا ينبغي\" عند أهل الفتوى","answer":"الجواب: كثير من الناس يستعمل (لا ينبغي) بمعنى: يكره، وكلمة (لا ينبغي) عظيمة في القرآن؛ كما قال تعالى: وَمَا يَنْبَغِي لِلرَّحْمَنِ أَنْ يَتَّخِذَ وَلَدًا [مريم:92] فهي عظيمة وشديدة في اللغة العربية، أما في عرف الناس فقد يستعملها كثير من الناس بمعنى أن الشيء يكره، ولا ينبغي فعله، وقد يستعملها آخرون من أهل العلم بمعنى أنه حرام، وأنه لا يجوز، فإذا استعملها طالب العلم فينبغي له أن يوضح، حتى لا يكون المستمع في شك، ينبغي للعالم والمفتي أن يوضح مراده بهذه الكلمة، أو يعبر بعبارة أوضح منها كيحرم ولا يجوز، حتى يكون المستمع على بينة وعلى بصيرة، نعم. وأما أكل الكبد ونحوها نيئًا فهذا لا نعلم ما يدل على تحريمه، ليس هناك ما يدل على تحريمه فيما نعلم، وقصاراه أن يقال: إنه مكروه إذا كان يخشى منه ضرر، أما إذا كان لا يخشى منه ضرر، فلا وجه أيضًا للكراهة، ولكن عادة الناس والمعروف عند الناس أن هذه الأشياء إنما تؤكل بعد الطبخ وبعد الإنضاج، فإذا علم من طريق الطب، من طريق أهل الخبرة أنه لا يضر، وأن أكله نيئًا لا يضر فلا حرج في ذلك.  أما إن كان يضر، فهو بين التحريم والكراهة، إن كان ضرره خفيفًا كره، وإن كان ضرره كبيرًا حرم، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17765/مفهوم-عبارة-لا-ينبغي-عند-اهل-الفتوى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_919/nour_91905.mp3","categories":["أصول الفقه"]},{"id":18722,"question":"يقول السائل سماحة الشيخ: ما الفرق بين السنة والنافلة، فاختلط على كثير من الأشخاص معنى كل منهما عند كثير من المسلمين؟ لعل لكم توجيهًا.","title":"الفرق بين السنة والنافلة","answer":"الجواب: النافلة هي التي لم يفرضها الله، تسمى نافلة، مثل صلاة الضحى، الوتر، الرواتب، سنة الوضوء، هذه يقال لها: نافلة.  أما صلاة الظهر الفريضة، والعصر، والمغرب هذه يقال لها: فريضة، والحج الأول يسمى فريضة، والحج الثاني للشخص يسمى نافلة، صوم يوم الإثنين والخميس نافلة، صوم رمضان فريضة، وهكذا. والسنة فيها تفصيل؛ تطلق السنة على كلام النبي ﷺ، وأفعاله، وأقواله، يقال لها: سنة، وتطلق السنة على النافلة تسمى صلاة الضحى سنة، وتسمى نافلة، فالسنة مرادفة للنافلة في بعض الأحيان، فتطلق على ما ليس بفرض وهو مشروع مثل: صلاة الضحى، الوتر يقال له: سنة، يعني: ليس بواجب. وتطلق السنة على أفعال النبي، وأقواله، وسيرته -عليه الصلاة والسلام- وتطلق السنة على ما يخالف البدعة، يقال مثلاً: صيام الإثنين والخميس سنة، تخصيص رجب بالصيام أو الجمعة بالصيام بدعة، وصيام السنة كلها بدعة، الرسول ﷺ نهى عنه، ليس بقربة، قال: لا صام من صام الأبد إذا صام ثلاثة أيام من كل شهر صام يوم الإثنين والخميس هذه يقال لها: سنة، فهذه وجوه السنة، تطلق على النافلة، وعلى ما هو مشروع ليس بواجب، وعلى ما هو ضد البدعة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/17838/الفرق-بين-السنة-والنافلة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78902.mp3","categories":["أصول الفقه"]},{"id":18744,"question":"شيخ عبد العزيز تضعون مدرسة ينبغي أن ينهل منها طلاب العلم، ذلكم أنكم كثيرًا ما تقدرون لابن تيمية، ولابن القيم بالذات اجتهاداتهم، وأنتم هنا تدعون إلى الرجوع إلى كتاب الله، وسنة رسوله عندما يكون هناك خلاف بين العلماء، أطمع في كلمة في هذه المناسبة لو تكرمتم.","title":"موقفنا إذا أخطأ المجتهد في اجتهاده","answer":"الجواب: نعم، نعم، شيخ الإسلام ابن تيمية -رحمه الله- وابن القيم، والإمام الشافعي، والإمام مالك، والإمام أبو حنيفة، والإمام أحمد -رحمة الله على الجميع- والإمام الثوري، والإمام إسحاق بن راهويه، والإمام الأوزاعي، وغيرهم من الأئمة، كلهم لهم المنزلة العظيمة عندنا وعند غيرنا من أهل العلم، يعرفون لهم فضلهم، واجتهادهم، وعلمهم، لا شك في هذا. ولكن لا يلزم -من كوننا نعظمهم ونعرف لهم أقدارهم- أن نوافق على ما قد يقع من خطأ من بعضهم؛ لأن كل إمام تقع له بعض الأخطاء، وبعض الأغلاط، وكل إمام يؤخذ من قوله ويترك إلا رسول الله -عليه الصلاة والسلام- فإن قوله هو الحق، كما قال مالك -رحمه الله-: ما منا إلا راد ومردود عليه، إلا صاحب هذا القبر، يعني: الرسول -عليه الصلاة والسلام-. وقال الإمام الشافعي -رحمه الله-: أجمع الناس على أن من استبانت له سنة رسول الله ﷺ لم يكن له أن يدعها لأحد من الناس، لم يكن له أن يدعها لقول أحد من الناس، حكاه إجماعًا لأهل العلم. وهذا صحيح؛ فإن الواجب على الأمة كلها تقديم ما قاله الله ورسوله، في مسائل النزاع، وفي مسائل الإجماع، فكما أن مسائل الإجماع يجب أن تحترم، وأن يؤخذ بها، وأن لا يلتفت إلى من خالفها، فهكذا من باب أولى الكتاب والسنة، يجب تعظيمهما، والأخذ بهما، وترك ما خالفهما من أقوال الناس، نعم. المقدم: بارك الله فيكم، وجزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/17870/موقفنا-اذا-اخطا-المجتهد-في-اجتهاده","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_875/nour_87502.mp3","categories":["أصول الفقه"]},{"id":18749,"question":"سماحة الشيخ، لعل لكم كلمة لبعض النساء اللاتي يقمن بالفتيا دون علم شرعي، تساهل النساء بمثل هذه الأحكام الشرعية، وليس عندهن علم شرعي، شيخ.","title":"نصيحة للمتساهلات في الفتوى بغير علم","answer":"الجواب: لا يجوز للرجل ولا للمرأة الفتيا بغير علم، يجب على كل مسلم أن يحذر القول على الله بغير علم، سواء كان رجلًا أو امرأة؛ لأن الله يقول سبحانه: قُلْ إِنَّمَا حَرَّمَ رَبِّيَ الْفَوَاحِشَ مَا ظَهَرَ مِنْهَا وَمَا بَطَنَ وَالإِثْمَ وَالْبَغْيَ بِغَيْرِ الْحَقِّ وَأَنْ تُشْرِكُوا بِاللَّهِ مَا لَمْ يُنَزِّلْ بِهِ سُلْطَانًا وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ[الأعراف:33] فجعل القول على الله بغير علم فوق مرتبة الشرك في التحريم لما يترتب عليه من الشر العظيم، فلا يجوز القول على الله بغير علم، ولا تجوز الفتوى بغير علم لا من الرجل ولا من المرأة. الواجب على من ليس لديه علم أن يسأل أهل العلم قال تعالى: فَاسْأَلُوا أَهْلَ الذِّكْرِ إِنْ كُنْتُمْ لا تَعْلَمُونَ[النحل:43]. أما أن يفتي بغير علم أو تفتي المرأة بغير علم هذا لا يجوز، وهذا من أمر الشيطان، قال الله في الشيطان: إِنَّمَا يَأْمُرُكُمْ بِالسُّوءِ وَالْفَحْشَاءِ وَأَنْ تَقُولُوا عَلَى اللَّهِ مَا لا تَعْلَمُونَ[البقرة:169] هذا من الشيطان، الشيطان يأمر الناس بأن يقولوا على الله بغير علم لما في هذا من الفساد الكبير، فالواجب على كل امرأة وعلى كل رجل أن يتقي الله، وأن يحذر الفتوى بغير علم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/17884/نصيحة-للمتساهلات-في-الفتوى-بغير-علم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_790/nour_79010.mp3","categories":["أصول الفقه"]},{"id":18993,"question":"رسالة وصلت إلى البرنامج من الباكستان، عندنا في باكستان بعض أشياء قد كثر فيها الخلاف والشقاق ومنها: ما يسمى حيلة الإسقاط، تفعل للميت قبل دفنه لإسقاط ما عليه من الواجبات، يعطى مبلغ من المال فيدار في دائرة تتضمن عصبة من الفقراء يأخذه هذا ويهبه لهذا، ثم هذا إلى هذا وهكذا إلى أن يتم العمل، ويستدلون لجواز هذه الحيلة: إن الحيل مطلقها جائز صحيح أجازه الكتاب والسنة، ويمثلون لذلك بقصة أيوب عليه السلام في أمر الله  له بالضرب بالضغث تحلة له عن يمينه وأمثال هذه القصة أشياء أخرى يقولون: فبناءً على هذا: الحيلة إذا فعلت لغرض صحيح من غير أن يحل بها حرام أو يحرم بها حلال فإنها تكون جائزة، وكما في نظائرها من الكتاب والسنة.والمرجو من سماحتكم الإفادة عن جميع نواحي هذه المسألة، كتابًا وسنة ودراية، مبينًا شأن الاستدلال بالعموميات أو المطلقات على الموارد الخاصة الجزئية كما في هذه المسألة؟ جزاكم الله تعالى خيرًا، المتمني لكم عافية دائمة وعيشة راضية وحياة طيبة مباركة، نظام الدين عبد الحنان .","title":"حكم الحيل في الشرع","answer":"الجواب: الحيل التي يتوصل بها إلى إسقاط واجب أو فعل محرم محرمة؛ لأن الوسائل لها حكم الغايات، قد حرم الله جل وعلا كل ذريعة إلى محرم وكل ذريعة إلى إسقاط الواجب، فلا يجوز لمسلم أن يفعل حيلة تسقط عنه واجب الزكاة أو واجب الصيام، أو واجب الحج أو غير ذلك، بل ي0جب عليه أن يأتي الأمور من أبوابها وأن يؤدي ما أوجب الله عليه، ويدع ما حرم الله عليه، وأن لا يتحيل في شيء من ذلك. وقد قال عليه الصلاة والسلام في الحديث الصحيح: لا ترتكبوا ما ارتكبت اليهود فتستحلوا محارم الله بأدنى الحيل وقد احتال أهل السبت لما حرم الله عليهم الصيد يوم السبت من بني إسرائيل احتالوا فنصبوا الشباك يوم الجمعة وأخذوا الصيود يوم الأحد، وقالوا: ما صدنا يوم السبت، فلم يعذرهم الله بذلك، فدل ذلك على أن الحيل التي تسقط الواجبات أو تفضي إلى المحرمات محرمة. أما حيلة جعلها الله حيلة وشرعها حيلة فلا بأس بها كما جعل البيع سببًا لأخذك مال أخيك برضاه والانتفاع به بالبيع الشرعي، وهكذا الهبة الشرعية، وهكذا المواريث، فالأسباب التي شرعها الله وجعلها حيلة لإيصال المرء إلى حاجته لا بأس بها، فكل حيلة شرعها الله وأباحها لعباده فلا بأس، أما حيل يتوصل بها إلى إسقاط الواجب أو إلى المحرم من دون إذن من الشارع فهذا لا يجوز لا في الزكاة ولا في غيرها، والله المستعان. نعم. المقدم: الله المستعان.","link":"https://binbaz.org.sa/fatwas/18146/حكم-الحيل-في-الشرع","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_926/nour_92601.mp3","categories":["أصول الفقه"]},{"id":19011,"question":"هناك أشخاص يقولون: أنا أصلي على المذهب الشافعي أو الحنفي أو المالكي، علمًا بأن هناك اختلافًا بين هذه المذاهب في الصلاة من حيث الأوضاع أو القراءة وما شابه ذلك، ما حكم الشرع في ذلك؟","title":"حكم من يلتزم مذهبًا معينًا في الصلاة والعبادة","answer":"الجواب: الواجب على المؤمن أن يتحرى سيرة النبي ﷺ وأفعاله وأقواله، وأن يسأل أهل العلم عما أشكل عليه، ولا يتقيد بشافعي أو حنبلي أو مالكي أو حنفي، لا بل يعتني بأفعال النبي ﷺ وسنته، وينظر كلام أهل العلم إذا كان طالب علم، ويسأل أهل العلم عما أشكل عليه، حتى يصلي كما صلى النبي ﷺ لا كما قال المذهب الفلاني والمذهب الفلاني، كل مذهب قد يخطئ، قد يكون فيه بعض الأغلاط لكن إذا سأل طالب العلم أهل العلم أرشدوه، وإن كان يستطيع النظر نظر في كتب أهل العلم وأدلتهم حتى يعلم ما كان موافقًا لفعل النبي ﷺ وما يخالف ذلك، فيفعل ما يوافق فعله ﷺ وقوله ويدع ما يخالف ذلك، والله المستعان. نعم. المقدم: الله المستعان، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18178/حكم-من-يلتزم-مذهبا-معينا-في-الصلاة-والعبادة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_926/nour_92605.mp3","categories":["أصول الفقه"]},{"id":19012,"question":"أخونا يسأل ويقول: هل الإنسان ملزم باتباع مذهب معين، وهناك كتاب عنوانه: (اللامذهبية أخطر بدعة تهدد الشريعة الإسلامية) هل اللامذهبية بدعة؟ وكتاب آخر عنوانه: (السلفية مرحلة متميزة مباركة ولكنها ليست مذهبًا إسلاميًا) ما هو رأيكم فيما سبق؟ جزاكم الله خيرًا، والكتابان اللذين ذكرتهما لعالم كبير.","title":"الكلام على التمذهب واللامذهبية والسلفية","answer":"الجواب: المذهبية ليست لازمة، ومن قال: إنه يلزم الناس أن يتمذهبوا بمذهب أحمد أو مالك أو الشافعي فقوله غير صحيح، المذاهب جديدة حدثت بعد الصحابة وبعد التابعين، فليست لازمة لأحد، إنما هي أقوال علماء اشتهروا ودونت أقوالهم فاشتهرت هذه المذاهب. فأحمد رحمه الله ومالك رحمه الله والشافعي رحمه الله وأبو حنيفة رحمه الله علماء من جنس الثوري من جنس الأوزاعي من جنس إسحاق بن راهويه، فكما أنه لا يلزمنا أن نأخذ أقوال الثوري أو ابن عيينة أو إسحاق أو الأوزاعي أو غيرهم، فكهذا لا يلزمنا أن نأخذ قول أحمد أو مالك أو الشافعي أو أبي حنيفة، ولكن ننظر في مسائل الخلاف فما وافق الحق من أقوالهم أخذناه وما خالفه تركناه. وما أجمع عليه العلماء وجب الأخذ به، ولم يكن هناك عذر في مخالفته، ما أجمعوا عليه وجب الأخذ به والتمسك به، وما اختلفوا فيه وجب عرضه على الكتاب والسنة كما قال الله : فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ[النساء:59]، فما وافق الكتاب والسنة أخذناه، وما خالفهما تركناه. وقول من قال: اللامذهبية، هذا إن أراد أن لا يجب التمذهب وليس بلازم فهو صحيح، وإن أراد أنه لا يجوز أن ينتسب فليس بصحيح، يجوز أن يتنسب الإنسان أن يكون شافعيًا أو حنبليًا أو مالكيًا أو حنفيًا؛ لأنه نشأ على ذلك، وتعلم على مشايخهم.. ونحو ذلك؛ لا بأس أن ينتسب، الانتساب لا يضر، إنما المهم أن لا يقلد ويتعصب، بل متى ظهر الحق أخذ به ولو في غير مذهبه، لا يجوز التعصب والتقليد الأعمى. فإذا أراد من قال اللامذهبية مراده يعني: أن لا تعصب ولا تقليد أعمى فهذا صحيح، أما إن أراد أنه لا يجوز الانتساب إلى هذه المذاهب هذا مخالف لما عليه أهل العلم ولا وجه له، إنما المنكر التعصب لزيد أو عمرو ولو قال خطأً، والتقليد الأعمى الذي ليس معه نظر ولا تفكير في الأدلة هذا هو الممنوع، وأما كونه ينتسب لمذهب لكنه يخالفه فيما خالف الحق ويأخذ بالحق مع من كان هذا صواب. وأما السلفية فالمعنى فيها سلوك مسلك السلف في أسماء الله وصفاته، والإيمان بها وإمرارها كما جاءت من غير تحريف ولا تعطيل ولا تكييف ولا تمثيل، والأخذ بالدليل وعدم التقليد الأعمى والتعصب هذا مراد السلفية. فالسلفية، هي طريق النبي ﷺ وطريق أصحابه، هي الطريقة المحمدية، إذا صار أهلها عندهم علم وعندهم بصيرة؛ لأنه قد يدعي السلفية من هو جاهل، فالاعتبار بمن أتقن علم السنة وعرف علم السنة واتبع ما كان عليه الرسول ﷺ وأصحابه، هذا هو السلفي الذي يعتني بما عليه السلف الصالح ويسير على نهجهم، فيأخذ بالدليل ويؤمن بآيات الله وأسمائه وصفاته، ويسير على نهج السلف في إثبات أسماء الله وصفاته، على الوجه اللائق بالله ويقول: إن القرآن كلام الله منزل غير مخلوق، ويقول: إنه يرى يوم القيامة وفي الجنة يراه المؤمنون، كل هذا حق، كل هذا قول السلف الصالح، وهو قول النبي ﷺ  أصحابه. فالسلفي هو الذي ينتسب إلى سلف الأمة، وهم أصحاب النبي ﷺ وأتباعهم بإحسان، فإن كان فاهمًا وملتزمًا بما عليه السلف فهو صادق، وإن كان يقوله باللسان ولكنه لا يمثله بالعمل يكون كاذبًا في قوله، فلابد من الصدق، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18179/الكلام-على-التمذهب-واللامذهبية-والسلفية","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_926/nour_92606.mp3","categories":["أصول الفقه"]},{"id":19220,"question":"رسالة وصلت إلى البرنامج من الجمهورية العراقية، مدينة الموصل إعدادية الدراسات الإسلامية، وباعث الرسالة أخ لنا من هناك يقول: مشعل عبد الله العلي، أخونا يسأل ثلاثة أسئلة، في سؤاله الأول يقول: هل يجوز التمسك بمذهب واحد من المذاهب الأربعة في أمور الفقه وغيرها؟","title":"حكم التمسك بمذهب واحد من المذاهب الأربعة","answer":"الجواب: لا مانع من الانتساب إلى مذهب من المذاهب الأربعة: الحنفية والمالكية والشافعية والحنبلية، لكن لا يجوز التمسك به في كل شيء سواء أصاب أو أخطأ، لا، بل يسأل طالب العلم، وينظر إن كان عنده بصيرة، فإذا وجد مسألة الحق فيها خلاف المذهب أخذ بالحق؛ لأن ما من مذهب إلا وفيه مسائل مرجوحة، فإذا كان الحنبلي أخذ بالمذهب المالكي أو الشافعي أو الحنفي في مسألة رأى أن الحق معهم وأن الدليل معهم، هذا هو الواجب عليه، وهكذا المالكي وهكذا الشافعي وهكذا الحنفي. المقصود لا مانع من الانتساب إلى المذاهب، لكن من دون تعصب، ومن دون جمود على المرجوح إذا عرفت الراجح، إذا كنت طالب عالم تفهم فعليك أن تأخذ بالأرجح بما يقتضيه الدليل ولو خالف مذهبك الذي انتسبت إليه أو نشأت عليه، وعليك أن تنظر في مسائل الخلاف بالأدلة، فما قام عليه الدليل وعرفت أنه الأرجح أخذت به، وإلا سألت أهل العلم عما أشكل عليك، سألت من تطمئن إليهم من أهل العلم في علمهم وفضلهم وورعهم واستقامتهم حتى يوضحوا لك ما هو الأرجح في مسائل الخلاف. نعم. المقدم: جزاكم الله خيرًا، وهذا يشمل الفقه والعقيدة وكل شيء سماحة الشيخ؟ الشيخ: نعم نعم. المقدم: بارك الله فيكم. الشيخ: يشمل الجميع، ولكنه في العقيدة أشد وآكد.","link":"https://binbaz.org.sa/fatwas/18404/حكم-التمسك-بمذهب-واحد-من-المذاهب-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_889/nour_88903.mp3","categories":["أصول الفقه"]},{"id":19305,"question":"السؤال الأخير الذي نعرضه من أسئلة أختنا في هذه الحلقة يقول: هل أحاديث رسول الله ﷺ هي وحي من الله ؟","title":"بيان أن السنة النبوية وحي من الله","answer":"الجواب: نعم، أحاديث الرسول ﷺ وحي من الله، يقول الله : وَالنَّجْمِ إِذَا هَوَى [النجم:1] هذا قسم من الله بالنجم وهو يقسم من خلقه بما يشاء ، كما قال تعالى: وَالطُّورِ ۝ وَكِتَابٍ مَسْطُور [الطور:2] وقال: وَالسَّمَاءِ ذَاتِ الْبُرُوجِ [البروج:1] وَالسَّمَاءِ وَالطَّارِقِ [الطارق:1]، وَاللَّيْلِ إِذَا يَغْشَى [الليل:1] كل هذه أقسام من الله، فهو سبحانه يقسم من خلقه بما يشاء؛ لأن في هذه المخلوقات آيات ودلالات على قدرته العظيمة وأنه رب العالمين  يقول جل وعلا: وَالنَّجْمِ إِذَا هَوَى ۝ مَا ضَلَّ صَاحِبُكُمْ [النجم:1-2] يعني: محمد عليه الصلاة والسلام وَمَا غَوَى [النجم:2] الضلال ضد العلم، والغواية عدم العمل بالعلم، فالرسول صلى الله عليه وسلم ليس بضال، وليس بغاوٍ، بل هو بار راشد عالم بالحق عليه الصلاة والسلام، على هدى، فهو مهتدي وراشد في أعماله كلها عليه الصلاة والسلام. ثم قال بعدها: وَمَا يَنْطِقُ عَنِ الْهَوَى [النجم:3] إذ ليس كلامه عن هوى من نفسه، بل عن وحي؛ ولهذا قال: إِنْ هُوَ إِلَّا وَحْيٌ يُوحَى [النجم:4] إن نافية، المعنى: ما هو إلا وحي يوحى، يعني: ما كلامه إلا وحي من الله  فإذا قال كذا، أمر بكذا، ونهى عن كذا، فكله وحي من الله عز وجل بنص هذه الآية الكريمة. وكذلك بقوله ﷺ لما قال له عبد الله بن عمرو: أنكتب يا رسول الله ما تقول؟ قال: نعم، اكتب، فوالذي نفسي بيده لا يخرج من هذا إلا حق عليه الصلاة والسلام، أو كما قال عليه الصلاة والسلام. فالمقصود أنه لا يخبر عن هواه وعن نفسه، وإنما يخبر عما يوحي الله إليه من الأوامر والنواهي والتشريع عليه الصلاة والسلام، وسبق أن الله يقسم من خلقه بما يشاء، لكن العبد ليس له أن يقسم إلا بربه، ليس للإنسان أن يحلف إلا بالله وحده، فليس له أن يحلف بأبيه أو بالأمانة أو بالنبي ﷺ أو بالكعبة أو بشرف فلان أو حياته، كل هذا لا يجوز، يقول النبي ﷺ: من كان حالفًا فليحلف بالله أو ليصمت ويقول عليه الصلاة والسلام: لا تحلفوا بآبائكم ولا بأمهاتكم ولا بالأنداد، ولا تحلفوا بالله إلا وأنتم صادقون . ويقول عليه الصلاة والسلام: من حلف بشيء دون الله فقد أشرك رواه الإمام أحمد بإسناد صحيح عن عمر  قال العلماء: الشرك هنا شرك أصغر، الحلف بغير الله من الشرك الأصغر، وقد يكون أكبر إذا قام بقلبه تعظيم المخلوق مثل عظمة الله أو أنه يجوز أن يعبد مع الله أو نحو هذا صار شركًا أكبر نعوذ بالله. فالحاصل والخلاصة أنه ليس للعبد أن يحلف بالمخلوقات، وإنما يحلف بالله وحده، أما ربنا سبحانه فله أن يقسم من خلقه بما يشاء لا أحد يتحجر عليه .  المقدم: جزاكم الله خيرًا. والخلاصة أيضًا أن الحديث هو وحي من الله وهو سؤال أختنا؟\nالشيخ: نعم.\nالمقدم: بارك الله فيكم.\nالشيخ: وحي من الله. نعم.\nالمقدم: جزاكم الله خيراً.","link":"https://binbaz.org.sa/fatwas/18507/بيان-ان-السنة-النبوية-وحي-من-الله","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_894/nour_89407.mp3","categories":["أصول الفقه"]},{"id":19472,"question":"من إربيل في الجمهورية العراقية، هذه رسالة بعث بها المستمع (س. س. أ) يسأل ويقول: المذاهب الأربعة: الحنفي، والمالكي، والشافعي، والحنبلي هي ثمرة الاجتهادات الفقهية في الدين، فإذا كان الأمر كذلك، هل يجوز لفقهاء المسلمين أن يأتوا بمذهب آخر نتيجة اجتهاداتهم الفقهية أم لا ولماذا؟","title":"حكم الإتيان بمذهب آخر غير المذاهب الأربعة","answer":"الجواب: ليس العلم مقصورًا في المذاهب الأربعة، بل هناك مذاهب أخرى مثل: التابعين، وأتباع التابعين، والأئمة المعروفين من أهل العلم غير الأربعة، هناك الأوزاعي، وهناك الثوري، وهناك إسحاق بن راهويه، وهناك أئمة كبار لهم آراء، ولهم معلومات نقلها العلماء عنهم. فالمؤمن أعني: طالب العلم المتبصر ينظر في الأدلة إذا وقع الخلاف، ويأخذ بما وافق الدليل من أقوال الأئمة الأربعة وغيرهم من أهل العلم من أئمة الصحابة، والتابعين، وأتباعهم بإحسان، وليس ذلك مقصورًا على الأئمة الأربعة فقط، بل الأئمة الأربعة هم من علماء الأمة، ومن كبار علماء الأمة أبي حنيفة، والشافعي، ومالك، وأحمد، كل هؤلاء من أئمة الإسلام ولهم فضل كبير، وعلوم جمة معلومة، ولكن ليس العلم مقصورًا عليهم، بل هناك غيرهم من العلماء مثلما تقدم كإسحاق بن راهويه المعروف، وكالأوزاعي رحمه الله، وكالثوري وابن عيينة وغيرهم من الأئمة المعروفين المجتهدين الذين لهم قدم صدق في الأمة. وهكذا من قبلهم من التابعين كسعيد بن المسيب، والشعبي، وطاوس وغيرهم من أئمة الإسلام المعروفين ممن لقي الصحابة، وقبلهم من هو أفضل وأعظم وهم الصحابة  وأرضاهم لهم أقوال، ولهم روايات نقلها العلماء عنهم يستعين بها طالب العلم في معرفة الحق بأدلته. فالواجب على أهل العلم وأهل البصيرة أن يعتنوا بهذا، وأن يعرضوا ما تنازع فيه الناس من الأئمة الأربعة ومن قبلهم أو من بعدهم على الأدلة الشرعية من الكتاب والسنة، فما وافق الدليل في مسائل الخلاف وجب الأخذ به، وطرح ما سواه سواء كان ذلك القول قال به أحد الأئمة الأربعة، أو قال به غيرهم؛ لأن الله يقول : يَا أَيُّهَا الَّذِينَ آمَنُوا أَطِيعُوا اللَّهَ وَأَطِيعُوا الرَّسُولَ وَأُوْلِي الأَمْرِ مِنْكُمْ فَإِنْ تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ[النساء:59]. فالواجب الرد إلى الكتاب، والسنة عند النزاع. وقال سبحانه: وَمَا اخْتَلَفْتُمْ فِيهِ مِنْ شَيْءٍ فَحُكْمُهُ إِلَى اللَّهِ[الشورى:10] وهذا محل إجماع بين أهل العلم، أن مسائل الخلاف يجب ردها إلى كتاب الله، وإلى سنة رسوله محمد عليه الصلاة والسلام، فما وافقهما فهو الحق، وما خالفهما وجب اطراحه، أما الاقتصار على المذاهب الأربعة، وتقليدها، والتعصب لها فليس من شأن أهل العلم، والله ولي التوفيق، نعم. المقدم: جزاكم الله خيرًا، ونفع بعلمكم.","link":"https://binbaz.org.sa/fatwas/18728/حكم-الاتيان-بمذهب-اخر-غير-المذاهب-الاربعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_945/nour_94504.mp3","categories":["أصول الفقه"]},{"id":19536,"question":"يقول السائل: إذا سألك شخص في أمر من أمور الشرع، وأنت تعرف الجواب من خلال استماعك لبرنامج نور على الدرب، هل يجب أن تعطيهم الجواب وتقول: سمعت ذلك من برنامج نور على الدرب لتبرئ الذمة؟","title":"حكم من سئل عن شيء فأجاب بفتوى سمعها من الغير","answer":"الجواب: نعم تخبرهم بما سمعت، سمعت فلان يقول كذا. نعم.","link":"https://binbaz.org.sa/fatwas/18792/حكم-من-سىل-عن-شيء-فاجاب-بفتوى-سمعها-من-الغير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_946/nour_94623.mp3","categories":["أصول الفقه"]},{"id":19588,"question":"هل الأطفال الذين يموتون في سن التاسعة والعاشرة، هل عليهم ذنب؟ وما هو السن الذي يحاسب به العبد؟ وما هو البرزخ؟","title":"السن الذي يحاسب به العبد","answer":"الجواب: السن الذي يحاسب عليه إذا بلغ البلوغ الذي يحصل به التكليف، وذلك بإكمال خمسة عشر سنة، أو بإنبات الشعر حول الفرج، هذا يسمى بالغًا ويسمى مكلفًا، والمرأة كذلك تسمى مكلفة وبالغة، وتزيد أمرًا رابعًا وهو الحيض، إذا حاضت صارت مكلفة، عليها واجب الصلاة والصوم والحج، أما الزكاة تجب ولو مع الصغر، الزكاة تجب في مال اليتيم ومال الصغير؛ على وليه أن يخرجها. نعم. المقدم: حفظكم الله سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/18842/السن-الذي-يحاسب-به-العبد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_949/nour_94904.mp3","categories":["أصول الفقه"]}]
